  assert.equal(roomAmbient824a70EntityAnm2Ptr(0x1000), 0x1048);
  assert.equal(roomAmbient824a70EntityAnm2Ptr(0xffffffc0), 0x8); // wrap
  assert.equal(roomAmbient824a70A2ThisPtr(0x1000), 0x1030);
