  // H5 residual plan / wire matrix (helpers ABI v24 freestanding; not Update-wired).
  assert.equal(ROOM_AMBIENT_824A70_RESIDUAL_NONE, 0);
  assert.equal(ROOM_AMBIENT_824A70_RESIDUAL_BODY, 1);
  assert.equal(ROOM_AMBIENT_824A70_RESIDUAL_MONOLITHIC, 2);
