  assert.equal(openPlan.frameAge1NeedsHost, 0); // age 4 not 1
  assert.equal(openPlan.tempfxWalkNeedsHost, 1);
  assert.equal(openPlan.residualKind, ROOM_B9B11_RESIDUAL_ALWAYS_HOST);
  assert.equal(openPlan.pureComplete, 0);
