    b9b11Flag11f4,
    b9b11B10Enemies,
    b9b11B10Fatal,
    b9b11Double409030,
    b9b11Stage1a,
    b9b11FrameAge1,
    b9b11TempfxFlagClear,
    b9b11TempfxListEmpty,
    b9b11TempfxWalk,
    b9b11TempfxContinue,
