  const jsD = roomTailmidCurseDeltas(40, 20, jsC.centerX, jsC.centerY);
  assert.equal(readF32(view, dPtr + 0), jsD.dx);
  assert.equal(readF32(view, dPtr + 4), jsD.dy);

  assert.equal(tailmidCursePosZero(0, 0, 0, 0) | 0, 1);
  assert.equal(readF32(view, 0) || true, true); // keep view live
