  assert.equal(tailmid801ee0Special(7, 5, 0, 1) | 0, 1);
  assert.equal(tailmid801ee0Timer13() | 0, ROOM_TAILMID_WAVE_TIMER_SET);
  assert.equal(tailmid801ee0DescClear(0x4f) >>> 0, roomTailmid801ee0DescClearBit40(0x4f));
  assert.equal(tailmid801ee0GameOr(0) >>> 0, 0x1000);
  assert.equal(tailmidSpecialType() >>> 0, ROOM_TAILMID_SPECIAL_EFFECT_TYPE);
  assert.equal(tailmidSfxId() >>> 0, ROOM_TAILMID_SFX_ID);
  assert.equal(Math.fround(tailmidSfxVol()), roomTailmidSfxVolume());
  assert.equal(tailmidSfxDelay() | 0, 2);
  assert.equal(tailmidSfxLoop() | 0, 0);
  assert.equal(tailmidMusicId() >>> 0, ROOM_TAILMID_MUSIC_ID);
  assert.equal(tailmid800500Skip(1, 0) | 0, 1);
