  assert.equal(readI32(view, ptr + 0) | 0, jsFrame.frameGate);
  assert.equal(readI32(view, ptr + 4) | 0, jsFrame.seedPresent);
  assert.equal(readI32(view, ptr + 8) | 0, jsFrame.needsSeedFatal);
