  assert.equal(ROOM_B5_HOST_VA_PASS2_VCALL4C, 0x00803a42);
  assert.equal(ROOM_B5_HOST_VA_PASS2_RNG, 0x00803a60);
  assert.equal(ROOM_B5_HOST_VA_NEXT, 0x00803b1d);
