  assert.equal(ROOM_B3_TE_CALL_FIELD50, 3);
  assert.equal(ROOM_B3_TE_CALL_FIELD54_BITS, 0x3dcccccd);

  // FCO pure CF
  assert.equal(roomB3OwnerTwinWalkFlag(1, 1, 0x80000000), 1);
  assert.equal(roomB3OwnerTwinWalkFlag(0, 1, 0x80000000), 0);
  assert.equal(roomB3OwnerTwinWalkFlag(1, 0, 0x80000000), 0);
  assert.equal(roomB3OwnerTwinWalkFlag(1, 1, 0), 0);
  assert.equal(roomB3OwnerListEmpty(0x10, 0x10), 1);
  assert.equal(roomB3OwnerListEmpty(0x10, 0x14), 0);
  assert.equal(roomB3OwnerPlayerSlotActive(0), 1);
  assert.equal(roomB3OwnerPlayerSlotActive(1), 0);
  assert.equal(roomB3OwnerTwinPresent(0), 0);
  assert.equal(roomB3OwnerTwinPresent(0xabc), 1);
  assert.equal(roomB3OwnerHasCollectibleHit(0), 0);
  assert.equal(roomB3OwnerHasCollectibleHit(1), 1);
  assert.equal(roomB3OwnerHasCollectibleHit(0x100), 0);
  assert.equal(roomB3OwnerListContinue(0x10, 0x18), 1);
  assert.equal(roomB3OwnerListContinue(0x14, 0x18), 0);

  // HCE pure CF
  assert.equal(roomB3HceGateOpen(0), 1);
  assert.equal(roomB3HceGateOpen(1), 0);
  assert.equal(roomB3HceListEmpty(0, 0), 1);
  assert.equal(roomB3HceListEmpty(0, 0x10), 0);
  assert.equal(roomB3HceTypeEligible(1), 1);
  assert.equal(roomB3HceTypeEligible(2), 0);
  assert.equal(roomB3HceTypeEligible(3), 1);
  assert.equal(roomB3HceTypeEligible(4), 1);
  assert.equal(roomB3HceEntryMatch(1, 0x2a5, 0x2a5), 1);
  assert.equal(roomB3HceEntryMatch(1, 0x2a5, 0x100), 0);
  assert.equal(roomB3HceEntryMatch(2, 0x2a5, 0x2a5), 0);
  assert.equal(roomB3HceListContinue(0, 0x20), 1);
  assert.equal(roomB3HceListContinue(0x10, 0x20), 0);
  assert.equal(roomB3HceBoolFromMatch(1), 1);
  assert.equal(roomB3HceBoolFromMatch(0), 0);
  assert.equal(roomB3ChallengeBodyNeedsHost(1), 1);
  assert.equal(roomB3ChallengeBodyNeedsHost(0), 0);

  // Challenge body pure CF / float posts
  assert.equal(roomB3CbGceHit(0), 0);
  assert.equal(roomB3CbGceHit(0x1000), 1);
  assert.equal(roomB3CbHceHit(0xff), 1);
