test("room v54 FUN_00428b20 spawn relay arg-relayout (helpers ABI v54)", () => {
  /* FUN_00428b20 (B15 rain spawn relay; also prefix B1/B2/B4 + tail B20
     spawn paths) is a pure stdcall arg-relayout shim: 8 pushes (leading 0,
     then a7..a1 R->L) and one call to the opaque create 0x006fe410; ret
     0x1c = 7 dword args; ecx untouched. The callee's ordered stack frame is
     {a1,a2,a3,a4,a5,a6,a7,0}. PE listing 0x00428b20..0x00428b45:

       0x00428b20 55           push ebp
       0x00428b21 8bec         mov ebp,esp
       0x00428b23 83e4f8       and esp,0xfffffff8
       0x00428b26 6a00         push 0
       0x00428b28 ff7520       push dword [ebp+0x20]
       0x00428b2b ff751c       push dword [ebp+0x1c]
       0x00428b2e ff7518       push dword [ebp+0x18]
       0x00428b31 ff7514       push dword [ebp+0x14]
       0x00428b34 ff7510       push dword [ebp+0x10]
       0x00428b37 ff750c       push dword [ebp+0xc]
       0x00428b3a ff7508       push dword [ebp+8]
       0x00428b3d e8ce582d00   call 0x006fe410
       0x00428b42 8be5         mov esp,ebp
       0x00428b44 5d           pop ebp
       0x00428b45 c21c00       ret 0x1c   */
  const { abi, memory, spawn428b20FrameAt, spawn428b20Arity,
    spawn428b20FrameDepth, spawn428b20RelaysEcx, spawn428b20HostCalleeVa,
    spawn428b20LeadingZero, spawn428b20Relayout,
  } = loadExports();
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.match(readFileSync(header, "utf8"),
    /ISAAC_ROOM_PURE_HELPERS_ABI_VERSION = 88/);
  /* PE constants. */
  assert.equal(ROOM_SPAWN_428B20_VA, 0x00428b20);
  assert.equal(ROOM_SPAWN_428B20_RET_VA, 0x00428b45);
  assert.equal(ROOM_SPAWN_428B20_END_VA, 0x00428b48);
  assert.equal(ROOM_SPAWN_428B20_CALL_VA, 0x00428b3d);
  assert.equal(ROOM_SPAWN_428B20_CALLEE_VA, 0x006fe410);
  assert.equal(ROOM_SPAWN_428B20_ARITY, 7);
  assert.equal(ROOM_SPAWN_428B20_FRAME_DEPTH, 8);
  assert.equal(ROOM_SPAWN_428B20_LEADING_ZERO, 0);
  assert.equal(spawn428b20Arity(), ROOM_SPAWN_428B20_ARITY);
  assert.equal(spawn428b20FrameDepth(), ROOM_SPAWN_428B20_FRAME_DEPTH);
  assert.equal(spawn428b20RelaysEcx(), 1);
  assert.equal(spawn428b20HostCalleeVa() >>> 0, ROOM_SPAWN_428B20_CALLEE_VA);
  assert.equal(spawn428b20LeadingZero(), ROOM_SPAWN_428B20_LEADING_ZERO);

  /* Independent PE-truth transcribed branch-by-branch from the listing:
     the push at 0x00428b3a lands a1 at the lowest callee address, then a2..
     a7 above it, and the 0x00428b26 push 0 tops the frame. For the drive
     args below the ordered callee frame is exactly this vector. */
  const drive = [0x100, 0x1ff, 0xffffffff, 0x7, 0xdeadbeef, 0x0c0ffee,
    0x5a5a5a5a];
  const peFrame = [0x100, 0x1ff, 0xffffffff, 0x7, 0xdeadbeef, 0x0c0ffee,
    0x5a5a5a5a, 0];

  /* Behavioural: every arg forwarded verbatim (no pre-mask), leading 0 at
     slot 7, out-of-contract index -> 0. */
  for (let i = 0; i < 8; i++) {
    const wasm = spawn428b20FrameAt(i >>> 0,
      drive[0] >>> 0, drive[1] >>> 0, drive[2] >>> 0, drive[3] >>> 0,
      drive[4] >>> 0, drive[5] >>> 0, drive[6] >>> 0) >>> 0;
    assert.equal(wasm, peFrame[i], `frame_at slot ${i}`);
    const js = roomSpawn428b20FrameAt(i,
      drive[0], drive[1], drive[2], drive[3], drive[4], drive[5], drive[6]);
    assert.equal(wasm, js, `frame_at slot ${i} vs oracle`);
  }
  /* Wide index (0x100) and out-of-contract 8 read nothing in PE. */
  assert.equal(spawn428b20FrameAt(0x100, ...drive) >>> 0, 0, "wide index");
  assert.equal(spawn428b20FrameAt(8, ...drive) >>> 0, 0, "index 8");
  assert.equal(spawn428b20FrameAt(0xffffffff, ...drive) >>> 0, 0, "max index");
  /* Wide args land verbatim — a mask on any slot would fold these. */
  assert.equal(spawn428b20FrameAt(0, 0x100, 0, 0, 0, 0, 0, 0) >>> 0, 0x100);
  assert.equal(spawn428b20FrameAt(1, 0, 0x1ff, 0, 0, 0, 0, 0) >>> 0, 0x1ff);
  assert.equal(spawn428b20FrameAt(2, 0, 0, 0xffffffff, 0, 0, 0, 0) >>> 0,
    0xffffffff);
  assert.equal(spawn428b20FrameAt(6, 0, 0, 0, 0, 0, 0, 0x5a5a5a5a) >>> 0,
    0x5a5a5a5a);
  assert.equal(spawn428b20FrameAt(7, 0x100, 1, 2, 3, 4, 5, 6) >>> 0, 0,
    "slot 7 is the leading 0 regardless of args");

  /* Struct relayout: 64B pack-1 frame, header/table fields, VAs. */
  const view = new DataView(memory.buffer);
  const OUT = MEM + 0x6a00;
  spawn428b20Relayout(
    drive[0] >>> 0, drive[1] >>> 0, drive[2] >>> 0, drive[3] >>> 0,
    drive[4] >>> 0, drive[5] >>> 0, drive[6] >>> 0, OUT);
  for (let i = 0; i < 8; i++) {
    assert.equal(view.getUint32(OUT + i * 4, true), peFrame[i],
      `relayout.frame[${i}]`);
  }
  assert.equal(view.getUint32(OUT + 32, true), ROOM_SPAWN_428B20_ARITY,
    "relayout.arity");
  assert.equal(view.getUint32(OUT + 36, true), ROOM_SPAWN_428B20_FRAME_DEPTH,
    "relayout.frameDepth");
  assert.equal(view.getUint32(OUT + 40, true), ROOM_SPAWN_428B20_CALLEE_VA,
    "relayout.hostCalleeVa");
  assert.equal(view.getUint32(OUT + 44, true), 1, "relayout.relaysEcx");
  assert.equal(view.getUint32(OUT + 48, true), ROOM_SPAWN_428B20_VA,
    "relayout.va");
  assert.equal(view.getUint32(OUT + 52, true), ROOM_SPAWN_428B20_RET_VA,
    "relayout.retVa");
  assert.equal(view.getUint32(OUT + 56, true), ROOM_SPAWN_428B20_CALL_VA,
    "relayout.callVa");
  /* Cross-check with the JS oracle struct. */
  const jsOut = roomSpawn428b20Relayout(
    drive[0], drive[1], drive[2], drive[3], drive[4], drive[5], drive[6]);
  assert.deepEqual([...jsOut.frame], peFrame, "oracle frame");
  assert.equal(jsOut.arity, 7);
  assert.equal(jsOut.frameDepth, 8);
  assert.equal(jsOut.hostCalleeVa, 0x006fe410);
  assert.equal(jsOut.relaysEcx, 1);

  /* Randomized differential: LCG-driven args, wasm == oracle on every slot. */
  let lcg = 0x2f9a371b;
  const rnd = () => ((lcg = (Math.imul(lcg, 1664525) + 1013904223) >>> 0), lcg);
  for (let k = 0; k < 400; k++) {
    const args = [rnd(), rnd(), rnd(), rnd(), rnd(), rnd(), rnd()];
    const idx = rnd() % 12;
    for (let s = 0; s < 8; s++) {
      const wasm = spawn428b20FrameAt(s,
        args[0] >>> 0, args[1] >>> 0, args[2] >>> 0, args[3] >>> 0,
        args[4] >>> 0, args[5] >>> 0, args[6] >>> 0) >>> 0;
      const js = roomSpawn428b20FrameAt(s,
        args[0], args[1], args[2], args[3], args[4], args[5], args[6]);
      assert.equal(wasm, js, `rand slot ${s} k ${k}`);
      const expect = s < 7 ? args[s] : 0;
      assert.equal(wasm, expect, `rand slot ${s} k ${k} truth`);
    }
    const wasmIdx = spawn428b20FrameAt(idx,
      args[0] >>> 0, args[1] >>> 0, args[2] >>> 0, args[3] >>> 0,
      args[4] >>> 0, args[5] >>> 0, args[6] >>> 0) >>> 0;
    const jsIdx = roomSpawn428b20FrameAt(idx,
      args[0], args[1], args[2], args[3], args[4], args[5], args[6]);
    assert.equal(wasmIdx, jsIdx, `rand wide idx ${idx} k ${k}`);
  }
});

test("room v54 mutation checks (helpers ABI v54)", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    withMutant("v54 leading zero dropped (slot 7 = a1)",
      (s) => s.replace(
        "out->frame[7] =\n      static_cast<uint32_t>(ISAAC_ROOM_SPAWN_428B20_LEADING_ZERO);",
        "out->frame[7] = a1;",
      ),
      () => {
        const { memory, spawn428b20Relayout } = loadExports();
        const view = new DataView(memory.buffer);
        const P = MEM + 0x6b00;
        spawn428b20Relayout(0x100, 0x1ff, 0, 0, 0, 0, 0, P);
        assert.equal(view.getUint32(P + 28, true), 0, "slot 7 stays 0");
      });
    withMutant("v54 frame_at masks arg to low byte",
      (s) => s.replace(
        "    case 0:\n      return a1;",
        "    case 0:\n      return a1 & 0xffu;",
      ),
      () => {
        const { spawn428b20FrameAt } = loadExports();
        assert.equal(spawn428b20FrameAt(0, 0x100, 0, 0, 0, 0, 0, 0) >>> 0,
          0x100, "wide a1 verbatim");
      });
    withMutant("v54 arg order reversed (slot 0 = a7)",
      (s) => s.replace(
        "  out->frame[0] = a1;\n  out->frame[1] = a2;",
        "  out->frame[0] = a7;\n  out->frame[1] = a6;",
      ),
      () => {
        const { memory, spawn428b20Relayout } = loadExports();
        const view = new DataView(memory.buffer);
        const P = MEM + 0x6b00;
        spawn428b20Relayout(1, 2, 3, 4, 5, 6, 7, P);
        assert.equal(view.getUint32(P + 0, true), 1, "slot 0 = a1");
        assert.equal(view.getUint32(P + 4, true), 2, "slot 1 = a2");
        assert.equal(view.getUint32(P + 24, true), 7, "slot 6 = a7");
      });
    withMutant("v54 arity pinned 6 (forgot ret 0x1c = 7)",
      (s) => s.replace(
        "  return ISAAC_ROOM_SPAWN_428B20_ARITY;",
        "  return 6;",
      ),
      () => {
        const { spawn428b20Arity } = loadExports();
        assert.equal(spawn428b20Arity(), 7, "ret 0x1c -> 7 args");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});

/* ------------------------------------------------------------------ v55 --- */
test("room v55 B15 rain loop CF + spawn-site provenance (helpers ABI v55)", () => {
  /* B15 rain shuffle/spawn loop (0x00802c20..0x00802e0d, PE listings
     cpu-dump/00802a80.txt + cpu-dump/00802c80.txt) + spawn-site arg
     provenance (0x00802daf..0x00802dc4). Fisher-Yates over 0x78-byte
     buffer slots; the seed lives in esi and is carried across iterations
     (0x00802e02): seed_{i+1} = xorshift(xorshift(seed_i)). Per iteration:

       0x00802c20 sub eax,ecx             ; remaining = spawn_count - index
       0x00802c28 test esi,esi / jne      ; seed==0 -> fatal assert
       0x00802c3c..64 xorshift(seed_in)   ; -> seed_shuffle
       0x00802c6e test ecx,ecx / je       ; remaining==0 -> rem = 0
       0x00802c72 div ecx                 ; UNSIGNED rem = seed % remaining
       0x00802c7c lea ecx,[edx+eax]       ; swap_index = index + rem
       0x00802c8b..99 swap_offset = swap_index*0x78 (shl4/sub/lea*8)
       0x00802d02..2f xorshift(seed_shuffle) -> seed_corner (carry + corner)
       0x00802de0 add [ebp-0x98c],0x78    ; slot_offset = index * 0x78
       0x00802de7 inc ecx                 ; next_index = index + 1
       0x00802dfe cmp ecx,eax / jge exit  ; continue iff next_index < count

     Spawn-site relay args (FUN_00428b20, the v54 law): a7 = *(slot+0x34),
     a6 = *(slot+8), a5 = 0, a4 = 0xc7b640, a3 = search_result (host
     0x00813520), a2 = *(slot+4), a1 = *(slot); ecx = Game 0xc71678 relays
     through; entity = relay return is bound by FUN_007ef420 (host, this =
     owner, args entity then slot) and marked entity+0x32c = -1. Blob-gated:
     host supplies seed0 / spawn_count / the slot-field values. */
  const { abi, memory, b15RainStride, b15RainPosVecPtr, b15RainGameGlobal,
    b15RainEntityMarkField, b15RainEntityMarkValue, b15RainHostVaBind,
    b15RainHostVaPosition, b15RainHostVaSpawnSite, b15RainLoopStep,
    b15RainLoopWalk, b15RainSpawnArgs, spawn428b20FrameAt } = loadExports();
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.match(readFileSync(header, "utf8"),
    /ISAAC_ROOM_PURE_HELPERS_ABI_VERSION = 88/);

  /* PE constants. */
  assert.equal(ROOM_B15_RAIN_LOOP_HEAD_VA, 0x00802c20);
  assert.equal(ROOM_B15_RAIN_LOOP_EXIT_VA, 0x00802e0d);
  assert.equal(ROOM_B15_RAIN_SPAWN_SITE_VA, 0x00802dc4);
  assert.equal(ROOM_B15_RAIN_BIND_SITE_VA, 0x00802dd5);
  assert.equal(ROOM_B15_RAIN_POSITION_SITE_VA, 0x00802da4);
  assert.equal(ROOM_B15_RAIN_SEED_LOAD_VA, 0x00802bf0);
  assert.equal(ROOM_B15_RAIN_STRIDE, 0x78);
  assert.equal(ROOM_B15_RAIN_LOOP_MAX_STEPS, 8);
  assert.equal(ROOM_B15_RAIN_POS_VEC_PTR, 0x00c7b640);
  assert.equal(ROOM_B15_RAIN_GAME_GLOBAL, 0x00c71678);
  assert.equal(ROOM_B15_RAIN_SLOT_FIELD_34_OFF, 0x34);
  assert.equal(ROOM_B15_RAIN_ENTITY_MARK_FIELD, 0x32c);
  assert.equal(ROOM_B15_RAIN_ENTITY_MARK_VALUE, 0xffffffff);
  assert.equal(ROOM_B15_RAIN_HOST_VA_BIND, 0x007ef420);
  assert.equal(ROOM_B15_RAIN_HOST_VA_POSITION, 0x00813520);
  assert.equal(b15RainStride(), ROOM_B15_RAIN_STRIDE);
  assert.equal(b15RainPosVecPtr() >>> 0, ROOM_B15_RAIN_POS_VEC_PTR);
  assert.equal(b15RainGameGlobal() >>> 0, ROOM_B15_RAIN_GAME_GLOBAL);
  assert.equal(b15RainEntityMarkField() >>> 0, ROOM_B15_RAIN_ENTITY_MARK_FIELD);
  assert.equal(b15RainEntityMarkValue() >>> 0, ROOM_B15_RAIN_ENTITY_MARK_VALUE);
  assert.equal(b15RainHostVaBind() >>> 0, ROOM_B15_RAIN_HOST_VA_BIND);
  assert.equal(b15RainHostVaPosition() >>> 0, ROOM_B15_RAIN_HOST_VA_POSITION);
  assert.equal(b15RainHostVaSpawnSite() >>> 0, ROOM_B15_RAIN_SPAWN_SITE_VA);

  const view = new DataView(memory.buffer);
  const OUT = MEM + 0x7200;
  const WALK = MEM + 0x7300;
  const SPAWN = MEM + 0x7400;

  /* Independent PE-truth: literal transcription of the rain-tail instruction
     stream branch-by-branch. div @0x00802c72 is UNSIGNED (div, not idiv);
     the 0x00802c6e test/je is a full-word zero guard; the swap_index add
     wraps; the 0x00802dfe exit is the SIGNED jge. */
  function peRainStep(seedIn, index, spawnCount) {
    const remaining = (spawnCount | 0) - (index | 0);       /* sub eax,ecx */
    let x = seedIn >>> 0;                                   /* xorshift 1 */
    x = ((x >>> 1) ^ x) >>> 0;
    x = (((x << 9) >>> 0) ^ x) >>> 0;
    const seedShuffle = ((x >>> 29) ^ x) >>> 0;
    let rem = 0;
    if ((remaining | 0) !== 0) {                            /* test/je */
      rem = (seedShuffle >>> 0) % (remaining >>> 0);        /* div ecx */
    }
    const swapIndex = ((index | 0) + (rem >>> 0)) | 0;      /* lea ecx,[edx+eax] */
    const slotOffset = Math.imul(index | 0, 0x78) | 0;      /* [ebp-0x98c] += 0x78 */
    const swapOffset = Math.imul(swapIndex, 0x78) | 0;      /* shl4/sub/lea*8 */
    x = seedShuffle;                                        /* xorshift 2 */
    x = ((x >>> 1) ^ x) >>> 0;
    x = (((x << 9) >>> 0) ^ x) >>> 0;
    const seedCorner = ((x >>> 29) ^ x) >>> 0;
    const nextIndex = ((index | 0) + 1) | 0;                /* inc ecx */
    const continueLoop = (nextIndex < (spawnCount | 0)) ? 1 : 0; /* jge exit */
    return { remaining, seedIn: seedIn >>> 0, seedShuffle, shuffleRem: rem,
      needsSwap: rem !== 0 ? 1 : 0, swapIndex, slotOffset, swapOffset,
      seedCorner, seedOut: seedCorner, nextIndex, continueLoop };
  }
  function peRainWalk(seed0, count) {
    const steps = [];
    let seed = seed0 >>> 0;
    for (let i = 0; i < count; i++) {
      const s = peRainStep(seed, i, count);
      steps.push(s);
      if (seed === 0) break;    /* 0x00802c28/cee assert fires -> PE dies */
      seed = s.seedOut;         /* esi carry @0x00802e02 */
    }
    return steps;
  }
  const readStep = (p) => ({
    remaining: view.getInt32(p + 0, true),
    seedIn: view.getUint32(p + 4, true),
    seedShuffle: view.getUint32(p + 8, true),
    shuffleRem: view.getUint32(p + 12, true),
    needsSwap: view.getInt32(p + 16, true),
    swapIndex: view.getInt32(p + 20, true),
    slotOffset: view.getInt32(p + 24, true),
    swapOffset: view.getInt32(p + 28, true),
    seedCorner: view.getUint32(p + 32, true),
    seedOut: view.getUint32(p + 36, true),
    nextIndex: view.getInt32(p + 40, true),
    continueLoop: view.getInt32(p + 44, true),
    seedFatal: view.getInt32(p + 48, true),
  });

  /* Hand-transcribed spot values (the transcriber's own arithmetic on the
     instruction stream; decimal from the div/lea/xor chain applied by hand):
     xorshift(0x12345678) = 1205138758; xorshift twice = 421610981;
     slot/swap offsets are index * 120 (0x78). */
  const spots = [
    { seedIn: 0x12345678, index: 0, count: 5, fields: {
      remaining: 5, seedShuffle: 1205138758, shuffleRem: 3, swapIndex: 3,
      slotOffset: 0, swapOffset: 360, seedCorner: 421610981, nextIndex: 1,
      continueLoop: 1 } },
    { seedIn: 0x12345678, index: 4, count: 5, fields: {
      remaining: 1, shuffleRem: 0, swapIndex: 4, slotOffset: 480,
      swapOffset: 480, nextIndex: 5, continueLoop: 0 } },
    { seedIn: 0xdeadbeef, index: 0, count: 8, fields: {
      remaining: 8, seedShuffle: 1194873242, shuffleRem: 2, swapIndex: 2,
      slotOffset: 0, swapOffset: 240, seedCorner: 743888726,
      continueLoop: 1 } },
    { seedIn: 0x0c0ffee, index: 0x100, count: 5, fields: {
      remaining: -251, shuffleRem: 1101050395, swapIndex: 1101050651,
      slotOffset: 30720, swapOffset: -1017908056, nextIndex: 257,
      continueLoop: 0 } },
    { seedIn: 0x0c0ffee, index: 0xffffffff, count: 5, fields: {
      remaining: 6, shuffleRem: 1, swapIndex: 0, slotOffset: -120,
      swapOffset: 0, nextIndex: 0, continueLoop: 1 } },
    { seedIn: 0x1, index: 0, count: 1, fields: {
      remaining: 1, seedShuffle: 513, shuffleRem: 0, swapIndex: 0,
      slotOffset: 0, swapOffset: 0, seedCorner: 393473, nextIndex: 1,
      continueLoop: 0 } },
  ];
  for (const sp of spots) {
    const P2 = MEM + 0x7100;
    b15RainLoopStep(sp.seedIn >>> 0, sp.index | 0, sp.count | 0, P2);
    const wm2 = readStep(P2);
    for (const [f, expect] of Object.entries(sp.fields)) {
      assert.equal(wm2[f], expect,
        `${sp.seedIn.toString(16)}/${sp.index}/${sp.count} ${f} hand-transcribed`);
    }
  }

  /* Behavioural fixed drives: wasm == PE-truth == oracle on every field. */
  const drives = [
    { seedIn: 0x12345678, index: 0, count: 5 },
    { seedIn: 0x12345678, index: 1, count: 5 },
    { seedIn: 0x12345678, index: 4, count: 5 },
    { seedIn: 0xdeadbeef, index: 0, count: 8 },
    { seedIn: 0xdeadbeef, index: 7, count: 8 },
    { seedIn: 0x5a5a5a5a, index: 3, count: 3 },
    { seedIn: 0x0c0ffee, index: 0x100, count: 5 },
    { seedIn: 0x0c0ffee, index: 0xffffffff, count: 5 },
    { seedIn: 0x1, index: 0, count: 1 },
    { seedIn: 0, index: 0, count: 5 },
  ];
  for (const d of drives) {
    b15RainLoopStep(d.seedIn >>> 0, d.index | 0, d.count | 0, OUT);
    const wm = readStep(OUT);
    const pe = peRainStep(d.seedIn, d.index, d.count);
    const js = roomB15RainLoopStep({
      seedIn: d.seedIn, index: d.index, spawnCount: d.count });
    const tagged = `${d.seedIn.toString(16)}/${d.index}/${d.count}`;
    for (const f of ["remaining", "shuffleRem", "needsSwap", "swapIndex",
      "slotOffset", "swapOffset", "nextIndex", "continueLoop"]) {
      assert.equal(wm[f], pe[f], `${tagged} ${f} vs PE-truth`);
      assert.equal(wm[f], js[f], `${tagged} ${f} vs oracle`);
    }
    for (const f of ["seedShuffle", "seedCorner", "seedOut"]) {
      assert.equal(wm[f], pe[f] >>> 0, `${tagged} ${f} vs PE-truth`);
      assert.equal(wm[f], js[f] >>> 0, `${tagged} ${f} vs oracle`);
    }
    assert.equal(wm.seedIn, d.seedIn >>> 0, `${tagged} seed_in echoes input`);
    assert.equal(wm.seedFatal, pe.seedShuffle === 0 ? 1 : 0,
      `${tagged} seed_fatal`);
    assert.equal(wm.seedFatal, js.seedFatal, `${tagged} seed_fatal vs oracle`);
  }

  /* ---- chained walk: seed carry (esi @0x00802e02) + 0x78 stride + exit ---- */
  const written5 = b15RainLoopWalk(0x12345678, 5, WALK, 8);
  assert.equal(written5, 5, "count 5 -> 5 steps");
  const walkPe = peRainWalk(0x12345678, 5);
  const walkJs = roomB15RainLoopWalk(0x12345678, 5);
  assert.equal(walkJs.length, 5, "oracle walk length");
  for (let i = 0; i < 5; i++) {
    const wm = readStep(WALK + i * 52);
    assert.equal(wm.seedIn,
      i === 0 ? 0x12345678 : readStep(WALK + (i - 1) * 52).seedOut,
      `step ${i} seed carry`);
    assert.equal(wm.seedIn, walkPe[i].seedIn, `step ${i} seedIn vs PE-truth`);
    assert.equal(wm.seedOut, walkPe[i].seedOut >>> 0,
      `step ${i} seedOut vs PE-truth`);
    assert.equal(wm.seedOut, walkJs[i].seedOut >>> 0,
      `step ${i} seedOut vs oracle`);
    assert.equal(wm.continueLoop, walkPe[i].continueLoop,
      `step ${i} continue vs PE-truth`);
    assert.equal(wm.slotOffset, Math.imul(i, 0x78) | 0, `step ${i} stride`);
    assert.equal(wm.seedFatal, 0, `step ${i} not fatal`);
  }
  assert.equal(readStep(WALK + 4 * 52).continueLoop, 0,
    "index 4 of 5: jge exits");
  assert.notEqual(readStep(WALK + 4 * 52).seedIn, 0x12345678,
    "carried seed differs from seed0 (mutant guard)");
  /* Enter gate 0x00802c0a: nonpositive counts skip the loop entirely. */
  assert.equal(b15RainLoopWalk(0x12345678, 0, WALK, 8), 0, "count 0");
  assert.equal(b15RainLoopWalk(0x12345678, -3, WALK, 8), 0, "negative count");
  /* Capacity clip. */
  assert.equal(b15RainLoopWalk(0x12345678, 5, WALK, 2), 2, "capacity clip");
  assert.equal(readStep(WALK + 0).slotOffset, 0, "clipped first step");
  /* Zero seed0: PE assert @0x00802c28 -> the fatal step is recorded, stop. */
  assert.equal(b15RainLoopWalk(0, 5, WALK, 8), 1, "fatal stops at step 0");
  assert.equal(readStep(WALK + 0).seedFatal, 1, "fatal flag on step 0");

  /* ---- spawn-site arg provenance (0x00802daf..0x00802dc4) ---- */
  function peRainSpawnArgs(slotF0, slotF4, slotF8, slotF34, searchResult) {
    /* Push order a7..a1 (first push = deepest = a7): esi (slot+0x34), edi
       (slot+8), 0, 0xc7b640, eax (search), [edi+4], [edi]. */
    return { a1: slotF0 >>> 0, a2: slotF4 >>> 0, a3: searchResult >>> 0,
      a4: 0xc7b640, a5: 0, a6: slotF8 >>> 0, a7: slotF34 >>> 0 };
  }
  const slotF0 = 0x100, slotF4 = 0x1ff, slotF8 = 0xffffffff,
        slotF34 = 0x5a5a5a5a, searchResult = 0xdeadbeef;
  b15RainSpawnArgs(slotF0 >>> 0, slotF4 >>> 0, slotF8 >>> 0, slotF34 >>> 0,
    searchResult >>> 0, SPAWN);
  const peArgs = peRainSpawnArgs(slotF0, slotF4, slotF8, slotF34, searchResult);
  const jsArgs = roomB15RainSpawnArgs({
    slotF0, slotF4, slotF8, slotF34, searchResult });
  assert.equal(view.getUint32(SPAWN + 0, true), ROOM_B15_RAIN_SPAWN_SITE_VA,
    "relay_va");
  for (const [i, name] of ["a1", "a2", "a3", "a4", "a5", "a6", "a7"].entries()) {
    assert.equal(view.getUint32(SPAWN + 4 + i * 4, true), peArgs[name],
      `spawn arg ${name} vs PE-truth`);
    assert.equal(view.getUint32(SPAWN + 4 + i * 4, true), jsArgs[name],
      `spawn arg ${name} vs oracle`);
  }
  assert.equal(view.getUint32(SPAWN + 32, true), 1, "relays_ecx");
  assert.equal(view.getUint32(SPAWN + 36, true), ROOM_B15_RAIN_HOST_VA_BIND,
    "bind_va");
  assert.equal(view.getUint32(SPAWN + 40, true), 1, "bind_entity_first");
  assert.equal(view.getUint32(SPAWN + 44, true), 1, "bind_slot_second");
  assert.equal(view.getUint32(SPAWN + 48, true), ROOM_B15_RAIN_ENTITY_MARK_FIELD,
    "mark field");
  assert.equal(view.getUint32(SPAWN + 52, true), ROOM_B15_RAIN_ENTITY_MARK_VALUE,
    "mark value");

  /* Compose with the v54 relay law: the ordered callee frame equals the
     provenance args slot-by-slot (a1..a7 then the leading 0). */
  const relayArgs = [slotF0, slotF4, searchResult, 0xc7b640, 0, slotF8,
    slotF34];
  for (let i = 0; i < 8; i++) {
    const wasm = spawn428b20FrameAt(i,
      relayArgs[0] >>> 0, relayArgs[1] >>> 0, relayArgs[2] >>> 0,
      relayArgs[3] >>> 0, relayArgs[4] >>> 0, relayArgs[5] >>> 0,
      relayArgs[6] >>> 0) >>> 0;
    const expect = i < 7 ? peArgs[`a${i + 1}`] : 0;
    assert.equal(wasm, expect, `relay frame slot ${i} from rain args`);
  }
  /* Wide slot fields are forwarded verbatim — any mask folds these. */
  b15RainSpawnArgs(0x100, 0x1ff, 0xffffffff, 0x5a5a5a5a, 0x100, SPAWN);
  assert.equal(view.getUint32(SPAWN + 4, true), 0x100, "wide slot_f0 verbatim");
  assert.equal(view.getUint32(SPAWN + 8, true), 0x1ff, "wide slot_f4 verbatim");
  assert.equal(view.getUint32(SPAWN + 12, true), 0x100,
    "wide search_result verbatim");
  assert.equal(view.getUint32(SPAWN + 24, true), 0xffffffff,
    "wide slot_f8 verbatim");
  assert.equal(view.getUint32(SPAWN + 28, true), 0x5a5a5a5a,
    "slot_f34 verbatim");

  /* ---- Randomized differential: wasm == PE-truth == oracle ---- */
  let lcg = 0x2f9a371b;
  const rnd = () => ((lcg = (Math.imul(lcg, 1664525) + 1013904223) >>> 0), lcg);
  for (let k = 0; k < 400; k++) {
    const seedIn = rnd(), index = rnd(), count = 1 + (rnd() % 10);
    b15RainLoopStep(seedIn, index | 0, count | 0, OUT);
    const wm = readStep(OUT);
    const pe = peRainStep(seedIn, index | 0, count | 0);
    assert.equal(wm.remaining, pe.remaining, `rand remaining k${k}`);
    assert.equal(wm.shuffleRem, pe.shuffleRem, `rand shuffleRem k${k}`);
    assert.equal(wm.swapIndex, pe.swapIndex, `rand swapIndex k${k}`);
    assert.equal(wm.slotOffset, pe.slotOffset, `rand slotOffset k${k}`);
    assert.equal(wm.swapOffset, pe.swapOffset, `rand swapOffset k${k}`);
    assert.equal(wm.seedOut, pe.seedOut >>> 0, `rand seedOut k${k}`);
    assert.equal(wm.continueLoop, pe.continueLoop, `rand continueLoop k${k}`);
    const s = rnd(), sf0 = rnd(), sf4 = rnd(), sf8 = rnd(), sf34 = rnd();
    b15RainSpawnArgs(sf0, sf4, sf8, sf34, s, SPAWN);
    const jsa = roomB15RainSpawnArgs({
      slotF0: sf0, slotF4: sf4, slotF8: sf8, slotF34: sf34, searchResult: s });
    for (const [i, name] of ["a1", "a2", "a3", "a4", "a5", "a6", "a7"].entries()) {
      assert.equal(view.getUint32(SPAWN + 4 + i * 4, true), jsa[name],
        `rand spawn arg ${name} k${k}`);
    }
  }
  /* Chained walk sweep: 3 seeds x counts 1..8 vs the PE-truth chain. */
  for (const seed0 of [0x12345678, 0xdeadbeef, 0x5a5a5a5a]) {
    for (let count = 1; count <= 8; count++) {
      const w = b15RainLoopWalk(seed0, count, WALK, 8);
      const wp = peRainWalk(seed0, count);
      assert.equal(w, wp.length, `walk ${seed0.toString(16)}/${count} length`);
      for (let i = 0; i < wp.length; i++) {
        const wm = readStep(WALK + i * 52);
        assert.equal(wm.seedOut, wp[i].seedOut >>> 0,
          `walk ${count}/${i} seedOut`);
        assert.equal(wm.swapIndex, wp[i].swapIndex,
          `walk ${count}/${i} swapIndex`);
        assert.equal(wm.continueLoop, wp[i].continueLoop,
          `walk ${count}/${i} continue`);
      }
    }
  }
});

test("room v55 mutation checks (helpers ABI v55)", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    withMutant("v55 stride folded 0x78 -> 0x60",
      (s) => s.replace(
        "out->slot_offset = index * ISAAC_ROOM_B15_RAIN_STRIDE;",
        "out->slot_offset = index * 0x60;",
      ),
      () => {
        const { memory, b15RainLoopStep } = loadExports();
        const view = new DataView(memory.buffer);
        const P = MEM + 0x7600;
        b15RainLoopStep(0x12345678, 2, 5, P);
        assert.equal(view.getInt32(P + 24, true), 0x78 * 2,
          "slot_offset stride 0x78");
      });
    withMutant("v55 loop bound jge -> jg (continue on equality)",
      (s) => s.replace(
        "(out->next_index < spawn_count) ? 1 : 0;",
        "(out->next_index <= spawn_count) ? 1 : 0;",
      ),
      () => {
        const { memory, b15RainLoopStep } = loadExports();
        const view = new DataView(memory.buffer);
        const P = MEM + 0x7600;
        b15RainLoopStep(0x12345678, 4, 5, P);
        assert.equal(view.getInt32(P + 44, true), 0,
          "index 4 of 5 exits (jge @0x00802dfe)");
      });
    withMutant("v55 xorshift reuse: walk reseeds every step (no esi carry)",
      (s) => s.replace(
        "    seed = s->seed_out;",
        "    seed = seed0;",
      ),
      () => {
        const { memory, b15RainLoopWalk } = loadExports();
        const view = new DataView(memory.buffer);
        const P = MEM + 0x7600;
        b15RainLoopWalk(0x12345678, 5, P, 8);
        assert.equal(view.getUint32(P + 4 + 52, true),
          view.getUint32(P + 36, true),
          "step1.seed_in == step0.seed_out (0x00802e02 carry)");
        assert.notEqual(view.getUint32(P + 4 + 52, true), 0x12345678,
          "carried seed differs from seed0");
      });
    withMutant("v55 index provenance: swap_index = rem (forgot + index)",
      (s) => s.replace(
        "  out->swap_index =\n      isaac_room_b1_shuffle_swap_index(index, out->shuffle_rem);",
        "  out->swap_index = static_cast<int32_t>(out->shuffle_rem);",
      ),
      () => {
        const { memory, b15RainLoopStep } = loadExports();
        const view = new DataView(memory.buffer);
        const P = MEM + 0x7600;
        b15RainLoopStep(0x12345678, 1, 5, P);
        assert.equal(view.getUint32(P + 12, true), 2, "rem is 2");
        assert.equal(view.getInt32(P + 20, true), 3,
          "swap_index = index + rem (lea ecx,[edx+eax] @0x00802c7c)");
      });
    withMutant("v55 spawn args a6/a7 swapped",
      (s) => s.replace(
        "  out->a6 = slot_f8;           /* 0x00802db0 push edi (pre-reload) */\n  out->a7 = slot_f34;          /* 0x00802daf push esi         */",
        "  out->a6 = slot_f34;          /* 0x00802daf push esi         */\n  out->a7 = slot_f8;           /* 0x00802db0 push edi (pre-reload) */",
      ),
      () => {
        const { memory, b15RainSpawnArgs } = loadExports();
        const view = new DataView(memory.buffer);
        const P = MEM + 0x7600;
        b15RainSpawnArgs(1, 2, 3, 4, 5, P);
        assert.equal(view.getUint32(P + 24, true), 3,
          "a6 = *(slot+8) (push edi pre-reload @0x00802db0)");
        assert.equal(view.getUint32(P + 28, true), 4,
          "a7 = *(slot+0x34) (push esi @0x00802daf)");
      });
    withMutant("v55 search_result masked to low byte",
      (s) => s.replace(
        "out->a3 = search_result;     /* 0x00802dbe push eax (host)  */",
        "out->a3 = search_result & 0xffu;",
      ),
      () => {
        const { memory, b15RainSpawnArgs } = loadExports();
        const view = new DataView(memory.buffer);
        const P = MEM + 0x7600;
        b15RainSpawnArgs(0, 0, 0, 0, 0x100, P);
        assert.equal(view.getUint32(P + 12, true), 0x100,
          "wide search_result verbatim");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});


/* ---- ABI v56: 0x007ef420 B15 rain bind pure laws ---- */

test("room v56: 0x007ef420 B15 bind pure laws (PE 0x7ef420..0x7ef697)", () => {
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.equal(ROOM_B15_BIND_VA, 0x007ef420);
  assert.equal(ROOM_B15_BIND_RET_VA, 0x007ef697);
  assert.equal(ROOM_B15_BIND_CLAMP_MIN, -2);
  assert.equal(ROOM_B15_BIND_CLAMP_MAX, 7);
  assert.equal(ROOM_B15_BIND_SCALE_X_BITS, 0x3f800000);
  assert.equal(ROOM_B15_BIND_SCALE_Y_BITS, 0x3f800000);

  const { b15BindVa, b15BindRetVa, b15BindPosUnordered,
          b15BindPosRederive, b15BindClampVal, b15BindScalePair,
          b15BindTailGate } = loadExports();

  /* clamp: signed to [-2, 7]: cmp eax,-2 ; jle -> -2 ; cmp eax,7 ; jl ->
     val ; else 7. */
  for (const [v, want] of [[-100, -2], [-3, -2], [-2, -2], [-1, -1],
                           [0, 0], [5, 5], [7, 7], [8, 7], [100, 7],
                           [0xffffffff, -1] /* 0xffffffff|0 = -1, in range */]) {
    assert.equal(roomB15BindClampVal(v), want, `js clamp ${v}`);
    assert.equal(b15BindClampVal(v), want, `wasm clamp ${v}`);
  }
  /* -2 signed is 0xfffffffe only as u32; clamp of 0xfffffffe = -2. */
  assert.equal(roomB15BindClampVal(0xfffffffe), -2, "0xfffffffe -> -2");
  assert.equal(b15BindClampVal(0xfffffffe), -2, "wasm 0xfffffffe -> -2");

  /* pos unordered: NaN in either operand -> 1 (skip re-derive). */
  assert.equal(roomB15BindPosUnordered(0x7fc00000, 0x3f800000), 1, "NaN field");
  assert.equal(roomB15BindPosUnordered(0x3f800000, 0x7fc00000), 1, "NaN vec");
  assert.equal(roomB15BindPosUnordered(0x3f800000, 0x3f800000), 0, "ordered");
  assert.equal(b15BindPosUnordered(0x7fc00000, 0x3f800000), 1, "wasm NaN");
  assert.equal(b15BindPosRederive(0x3f800000, 0x3f800000, 0x3f800000, 0x3f800000), 1,
    "both ordered -> re-derive");
  assert.equal(b15BindPosRederive(0x7fc00000, 0x3f800000, 0x3f800000, 0x3f800000), 0,
    "NaN x -> no re-derive");
  assert.equal(b15BindPosRederive(0x3f800000, 0x3f800000, 0x7fc00000, 0x3f800000), 0,
    "NaN y -> no re-derive");

  /* scale pair: f32(v) * 1.0f both axes, bits preserved. */
  const sp = roomB15BindScalePair(0x3f800000);            /* 1.0f */
  assert.equal(sp.xBits, 0x3f800000, "scale 1.0 x");
  assert.equal(sp.yBits, 0x3f800000, "scale 1.0 y");
  const sp2 = roomB15BindScalePair(0x40000000);           /* 2.0f */
  assert.equal(sp2.xBits, 0x40000000, "scale 2.0 x");
  assert.equal(roomB15BindScalePair(0x80000000).xBits, 0x80000000, "-0.0 * 1.0");
  {
    const inst = loadExports();
    const P = MEM + 0x7800;
    inst.b15BindScalePair(0x3f800000, P, P + 4);
    const view = new DataView(inst.memory.buffer);
    assert.equal(view.getUint32(P, true), 0x3f800000, "wasm scale x bits");
    assert.equal(view.getUint32(P + 4, true), 0x3f800000, "wasm scale y bits");
  }

  /* tail gate: [Game+0x18304]==-0xc && byte[Game+0x269e9]!=0 &&
     [edi+0x2c]==0x64 && SIGNED [edi+0x32c]>=0. */
  assert.equal(roomB15BindTailGate(-0xc, 1, 0x64, 0), 1, "all gates");
  assert.equal(roomB15BindTailGate(-0xb, 1, 0x64, 0), 0, "game18304");
  assert.equal(roomB15BindTailGate(-0xc, 0, 0x64, 0), 0, "byte269e9");
  assert.equal(roomB15BindTailGate(-0xc, 1, 0x65, 0), 0, "field2c");
  assert.equal(roomB15BindTailGate(-0xc, 1, 0x64, -1), 0, "field32c neg");
  assert.equal(roomB15BindTailGate(-0xc, 1, 0x64, 0x80000000), 0, "field32c sign");
  assert.equal(roomB15BindTailGate(-0xc, 0x100, 0x64, 0), 0, "byte gate wide masks to 0");
  assert.equal(b15BindTailGate(-0xc, 1, 0x64, 0), 1, "wasm all");
  assert.equal(b15BindTailGate(-0xc, 1, 0x64, -1), 0, "wasm neg");
  assert.equal(b15BindTailGate(-0xc, 0x100, 0x64, 0), 0, "wasm wide byte masks to 0");

  assert.equal(b15BindVa() >>> 0, 0x007ef420, "bind VA");
  assert.equal(b15BindRetVa() >>> 0, 0x007ef697, "bind ret VA");
});

test("room v56: B15 bind laws mutation discrimination", () => {
  /* Each mutant changes behaviour AND a pinned assertion catches it: the
     test FAILS on the mutated build (loadExports rebuilds the wasm from
     the current cpp every call). */
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s2) => (crlfFile ? s2.replace(/\n/g, "\r\n") : s2);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, label + ": mutant did not apply");
    writeSourceRetry(toFile(bad));
    let threw = false;
    try { check(); } catch { threw = true; }
    writeSourceRetry(original);
    assert.ok(threw, label + ": mutant survived every assertion");
  };
  try {
    const eq = (a, b) => assert.equal(a, b);
/* (1) clamp max +1: 8 becomes in-range (returns 8 not 7). */
    withMutant("clamp max +1",
      (s2) => s2.replace(
        "return ISAAC_ROOM_B15_BIND_CLAMP_MAX;",
        "return ISAAC_ROOM_B15_BIND_CLAMP_MAX + 1;",
      ),
      () => {
        const e = loadExports();
        eq(e.b15BindClampVal(8), 7);
        eq(e.b15BindClampVal(100), 7);
      });
    /* (2) tail gate 0x2c const flipped (0x64 -> 0x46). */
    withMutant("tail field2c const",
      (s2) => s2.replace("field2c != 0x64", "field2c != 0x46"),
      () => {
        const e = loadExports();
        eq(e.b15BindTailGate(-0xc, 1, 0x64, 0), 1);
      });
    /* (3) byte269e9 narrowed to bit0 -> byte 0x2 (nonzero byte, even bit)
       blocked. */
    withMutant("tail byte269e9 narrow",
      (s2) => s2.replace("(byte269e9 & 0xffu) == 0u", "(byte269e9 & 0x1u) == 0u"),
      () => {
        const e = loadExports();
        eq(e.b15BindTailGate(-0xc, 0x2, 0x64, 0), 1);
        eq(e.b15BindTailGate(-0xc, 0xff, 0x64, 0), 1);
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});


/* ---- ABI v57: 0x007ef5d5..0x007ef60f B15 bind sub-list copy law ---- */

test("room v57: 0x007ef5d5 sub-list copy (PE 0x7ef5d5..0x7ef60f)", () => {
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.equal(ROOM_B15_BIND_SUB_COUNT_OFF, 0x5c0);
  assert.equal(ROOM_B15_BIND_SUB_LIST_OFF, 0x5a0);
  assert.equal(ROOM_B15_BIND_SUB_MAX, 8);
  assert.equal(ROOM_B15_BIND_ENTRY_0x64_COUNT, 8);
  assert.equal(ROOM_B15_BIND_ENTRY_0x64_STRIDE, 4);

  const { b15BindSubListCopy, memory } = loadExports();

  /* JS oracle (the REAL loop): cmp [ebx+0x64],0 ; je -> ptr==0 gate:
     count UNTOUCHED (no reset, no copy). Else count:=0 then 8-iteration
     stride-4 loop; entry==0 breaks; count<8 (jae cap) stores. */
  const g = roomB15BindSubListCopy(null, 3);
  assert.equal(g.countAfter, 3, "null ptr gate: count untouched");
  assert.deepEqual(g.stored, [], "null ptr gate: no stores");

  const c = roomB15BindSubListCopy([1, 2, 3, 0, 0, 0, 0, 0], 0);
  assert.equal(c.countAfter, 3, "three entries then zero break");
  assert.deepEqual(c.stored, [1, 2, 3], "stored entries verbatim");

  const full = roomB15BindSubListCopy([1, 2, 3, 4, 5, 6, 7, 8], 0);
  assert.equal(full.countAfter, 8, "eight entries, full list");
  assert.deepEqual(full.stored, [1, 2, 3, 4, 5, 6, 7, 8], "eight stored");

  /* Wide dword drives: entry 0x100 (nonzero dword, zero low byte) and
     0x80000000 (negative i32, nonzero dword) must be STORED — the break
     is a full-dword zero test (test edx,edx; je), NOT a low-byte or
     signed test. */
  const wide = roomB15BindSubListCopy([0x100, 0x80000000, 0, 0, 0, 0, 0, 0], 0);
  assert.equal(wide.countAfter, 2, "wide dwords stored verbatim");
  assert.deepEqual(wide.stored, [0x100, 0x80000000], "wide entries verbatim");

  const zeroFirst = roomB15BindSubListCopy([0, 0x100, 0, 0, 0, 0, 0, 0], 0);
  assert.equal(zeroFirst.countAfter, 0, "first entry zero breaks immediately");
  assert.deepEqual(zeroFirst.stored, [], "nothing stored");

  /* WASM: write source dwords into linear memory at SRC, call the
     exported law with the SRC offset + count_in, read back OUT. */
  {
    const view = new DataView(memory.buffer);
    const SRC = MEM + 0x7a00;
    const OUT = MEM + 0x7a40;
    for (let i = 0; i < 8; i += 1) view.setUint32(SRC + 4 * i, 0, true);
    view.setUint32(SRC, 10, true);       /* entry 0 */
    view.setUint32(SRC + 4, 0x100, true); /* entry 1 (wide dword) */
    view.setUint32(SRC + 8, 0, true);    /* entry 2 -> zero break */
    for (let i = 0; i < 8; i += 1) view.setUint32(OUT + 4 * i, 0xdeadbeef, true);

    const n = b15BindSubListCopy(SRC, 7, OUT);
    assert.equal(n, 2, "wasm countAfter");
    assert.equal(view.getUint32(OUT, true), 10, "wasm out[0]");
    assert.equal(view.getUint32(OUT + 4, true), 0x100, "wasm out[1] (wide verbatim)");
    assert.equal(view.getUint32(OUT + 8, true), 0xdeadbeef, "wasm out[2] untouched");

    /* wasm ptr==0 gate: count_in returned untouched, OUT untouched. */
    const gateN = b15BindSubListCopy(0, 0xffffffff, OUT);
    assert.equal(gateN >>> 0, 0xffffffff, "wasm null gate passes count through");
    assert.equal(view.getUint32(OUT, true), 10, "wasm null gate leaves OUT alone");
  }
});

test("room v57: sub-list copy mutation discrimination", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s2) => (crlfFile ? s2.replace(/\n/g, "\r\n") : s2);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, label + ": mutant did not apply");
    writeSourceRetry(toFile(bad));
    let threw = false;
    try { check(); } catch { threw = true; }
    writeSourceRetry(original);
    assert.ok(threw, label + ": mutant survived every assertion");
  };
  try {
    const eq = (a, b) => assert.equal(a, b);
    /* (1) zero-break narrowed to a low-byte test -> entry 0x100 (nonzero
       dword, zero low byte) would wrongly break. */
    withMutant("sub-list low-byte break",
      (s2) => s2.replace("if (e == 0u) break;", "if ((e & 0xffu) == 0u) break;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const SRC = MEM + 0x7a80;
        const OUT = MEM + 0x7ac0;
        for (let i = 0; i < 8; i += 1) view.setUint32(SRC + 4 * i, 0, true);
        view.setUint32(SRC, 0x100, true);
        view.setUint32(SRC + 4, 2, true);
        eq(e.b15BindSubListCopy(SRC, 9, OUT), 2);
        eq(view.getUint32(OUT, true), 0x100);
      });
    /* (2) cap lowered 8 -> 7: eight nonzero entries must store all 8
       (PE jae only skips at count>=8; from count 0 the 8th store runs). */
    withMutant("sub-list cap 7",
      (s2) => s2.replace("count < ISAAC_ROOM_B15_BIND_SUB_MAX",
                         "count < 7u"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const SRC = MEM + 0x7b00;
        const OUT = MEM + 0x7b40;
        for (let i = 0; i < 8; i += 1) {
          view.setUint32(SRC + 4 * i, i + 1, true);
          view.setUint32(OUT + 4 * i, 0xdeadbeef, true);
        }
        eq(e.b15BindSubListCopy(SRC, 0, OUT), 8);
        eq(view.getUint32(OUT + 4 * 7, true), 8);
      });
    /* (3) ptr==0 gate removed -> null ptr no longer returns count_in. */
    withMutant("sub-list gate removed",
      (s2) => s2.replace("if (sub_list_ptr == 0u) return count_in;\n", ""),
      () => {
        const e = loadExports();
        const OUT = MEM + 0x7b80;
        eq(e.b15BindSubListCopy(0, 0xffffffff, OUT) >>> 0, 0xffffffff);
      });
    /* (4) zero-break flipped to signed<=0 -> entry 0x80000000 (negative
       i32, NONzero dword per test edx,edx) would wrongly break. */
    withMutant("sub-list signed break",
      (s2) => s2.replace("if (e == 0u) break;",
                         "if (static_cast<int32_t>(e) <= 0) break;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const SRC = MEM + 0x7c00;
        const OUT = MEM + 0x7c40;
        for (let i = 0; i < 8; i += 1) view.setUint32(SRC + 4 * i, 0, true);
        view.setUint32(SRC, 0x80000000, true);
        view.setUint32(SRC + 4, 2, true);
        eq(e.b15BindSubListCopy(SRC, 0, OUT), 2);
        eq(view.getUint32(OUT, true), 0x80000000);
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});


/* ---- ABI v58: 0x007ef4a2..0x007ef5d5 B15 bind store-pack relayout ---- */

/* v58 src struct layout (pack 1, all dwords) — IsaacRoomB15BindSrc. */
const V58_SRC_OFF = {
  f8: 0, f0c: 4, f10: 8, f14: 12, f18: 16, f1c: 20, f20: 24, f22: 28,
  f23: 32, f24: 36, f30: 40, f38: 44, f3c: 48, f40: 52, f50: 56, f54: 60,
  f58: 64, f5c: 68, f60: 72,
};
/* v58 out struct layout (pack 1, all dwords) — IsaacRoomB15BindStorePack. */
const V58_OUT_OFF = {
  dst_3dc: 0, dst_3e0_lo: 4, dst_3e0_hi: 8, dst_3e8: 12, dst_32c: 16,
  dst_404: 20, type5: 24, store_524: 28, dst_524: 32, dst_538: 36,
  dst_53c: 40, dst_52c: 44, dst_588: 48, reset_5c0: 52, dst_528: 56,
  dst_34: 60, dst_38: 64, dst_540: 68, dst_e4_bits: 72, dst_e8_bits: 76,
  dst_52e: 80, dst_59c: 84, dst_530: 88, call_a_va: 92, call_a_arg: 96,
  call_b_va: 100, call_b_fire: 104, call_b_arg: 108, call_c_va: 112,
  call_c_arg: 116, qword_const_va: 120, dword_const_va: 124,
};

function v58WriteSrc(view, base, src) {
  for (const [k, off] of Object.entries(V58_SRC_OFF)) {
    view.setUint32(base + off, src[k] >>> 0, true);
  }
}
function v58ReadOut(view, base) {
  const out = {};
  for (const [k, off] of Object.entries(V58_OUT_OFF)) {
    out[k] = view.getUint32(base + off, true) >>> 0;
  }
  return out;
}

test("room v58: 0x007ef4a2 store-pack relayout (PE 0x7ef4a2..0x7ef5d5)", () => {
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.equal(ROOM_B15_BIND_STORE_PACK_VA, 0x007ef4a2);
  assert.equal(ROOM_B15_BIND_STORE_TYPE5_HEAD_VA, 0x007ef4e5);
  assert.equal(ROOM_B15_BIND_STORE_SUB_LIST_VA, 0x007ef5d5);
  assert.equal(ROOM_B15_BIND_STORE_QWORD_CONST_VA, 0x00b1f630);
  assert.equal(ROOM_B15_BIND_STORE_DWORD_CONST_VA, 0x00b1f638);
  assert.equal(ROOM_B15_BIND_STORE_QWORD_LO, 0x4);
  assert.equal(ROOM_B15_BIND_STORE_QWORD_HI, 0x3);
  assert.equal(ROOM_B15_BIND_STORE_DWORD_CONST, 0x11);
  assert.equal(ROOM_B15_BIND_STORE_HOST_A_VA, 0x006e2570);
  assert.equal(ROOM_B15_BIND_STORE_HOST_B_VA, 0x006e21f0);
  assert.equal(ROOM_B15_BIND_STORE_HOST_C_VA, 0x006e1a80);
  assert.equal(ROOM_B15_BIND_STORE_TYPE5, 5);

  const { b15BindStorePackVa, b15BindStoreType5HeadVa, b15BindStoreSubListVa,
          b15BindStorePack, memory } = loadExports();
  assert.equal(b15BindStorePackVa() >>> 0, 0x007ef4a2, "wasm store pack VA");
  assert.equal(b15BindStoreType5HeadVa() >>> 0, 0x007ef4e5, "wasm type5 head VA");
  assert.equal(b15BindStoreSubListVa() >>> 0, 0x007ef5d5, "wasm sub-list boundary VA");

  const JL = (label, src, type28, old52e, field2c, field30) => {
    const want = roomB15BindStorePack(src, type28, old52e, field2c, field30);
    const view = new DataView(memory.buffer);
    const SRC = MEM + 0x7d00;
    const OUT = MEM + 0x7d80;
    v58WriteSrc(view, SRC, src);
    b15BindStorePack(SRC, type28 >>> 0, old52e >>> 0, field2c >>> 0,
                     field30 >>> 0, OUT);
    const got = v58ReadOut(view, OUT);
    const keys = Object.keys(V58_OUT_OFF);
    for (const k of keys) {
      assert.equal(got[k], want[k] >>> 0, `${label}: out.${k}`);
    }
    return { got, want };
  };

  /* Full type-5 drive with distinct field values; F20 word 0x8000 must be
     SIGN-EXTENDED (movsx) to 0xffff8000, not zero-extended. */
  {
    const src = {
      f8: 0x100, f0c: 0xaa, f10: 7, f14: 0xbb, f18: 0xfffffffe, f1c: 0x1c,
      f20: 0x8000, f22: 0x1ff, f23: 0x2ff, f24: 5, f30: 0x30, f38: 0x38,
      f3c: 0x3c, f40: 0x40, f50: 0x50, f54: 0x40000000, f58: 0x58, f5c: 0x5c,
      f60: 0x1ff,
    };
    const { got } = JL("type5 full", src, 5, 0x1, 0x64, 1);
    assert.equal(got.type5, 1, "type gate 5 -> type5");
    assert.equal(got.store_524, 1, "f8=0x100 (nonzero dword) enables 0x524");
    assert.equal(got.dst_538, 0xff, "byte f60 masked to low byte");
    assert.equal(got.dst_52c, 0xff, "byte f22 masked");
    assert.equal(got.dst_52e, 0xff, "byte f23 masked (NEW)");
    assert.equal(got.dst_53c, 0xfffffffe, "clamp f18=-2 -> -2");
    assert.equal(got.dst_32c, 0xffff8000, "sxw 0x8000 -> 0xffff8000");
    assert.equal(got.dst_3e0_lo, 0x4, "qword const lo");
    assert.equal(got.dst_3e0_hi, 0x3, "qword const hi");
    assert.equal(got.dst_3e8, 0x11, "dword const");
    assert.equal(got.call_a_arg, 0xbb, "call A arg = f14");
    assert.equal(got.call_c_arg, 0xaa, "call C arg = f0c");
    assert.equal(got.call_b_fire, 1, "2c=0x64 && 30!=0 && old!=new -> fire B");
    assert.equal(got.dst_e4_bits, 0x40000000, "scale X 2.0f bits");
    assert.equal(got.dst_e8_bits, 0x40000000, "scale Y 2.0f bits");
  }

  /* type != 5: pack gate 0; common stores still computed; call B gated. */
  {
    const { got } = JL("type6", {
      f8: 3, f0c: 9, f10: 1, f14: 2, f18: 8, f1c: 3, f20: 0x7fff, f22: 1,
      f23: 1, f24: 0, f30: 4, f38: 5, f3c: 6, f40: 7, f50: 8, f54: 0x3f800000,
      f58: 9, f5c: 10, f60: 2,
    }, 6, 0, 0x64, 1);
    assert.equal(got.type5, 0, "type 6 -> not type5");
    assert.equal(got.dst_3dc, 5, "common store still computed");
    assert.equal(got.dst_404, 9, "common store still computed");
    assert.equal(got.dst_32c, 0x7fff, "sxw 0x7fff -> 0x7fff");
    assert.equal(got.call_b_fire, 0, "type!=5 -> call B never fires");
  }

  /* Clamp SIGNED bounds: f18 = 8 -> 7; f18 = 0xffffffff (-1) -> -1 (in
     range); f18 = 0x80000000 -> -2 (<= -2). */
  {
    const base = {
      f8: 0, f0c: 0, f10: 0, f14: 0, f18: 8, f1c: 0, f20: 0, f22: 0, f23: 0,
      f24: 0, f30: 0, f38: 0, f3c: 0, f40: 0, f50: 0, f54: 0x3f800000,
      f58: 0, f5c: 0, f60: 0,
    };
    assert.equal(JL("clamp8", { ...base, f18: 8 }, 5, 0, 0x64, 0).got.dst_53c,
                 7, "clamp 8 -> 7");
    assert.equal(JL("clampNeg1", { ...base, f18: 0xffffffff }, 5, 0, 0x64, 0)
                   .got.dst_53c, 0xffffffff, "clamp -1 in range");
    assert.equal(JL("clampMin", { ...base, f18: 0x80000000 }, 5, 0, 0x64, 0)
                   .got.dst_53c, 0xfffffffe, "clamp 0x80000000 <= -2 -> -2");
  }

  /* reset_5c0 gates: f24 full-dword tests. 0 and 0xffffffff (-1) skip;
     0x100 (nonzero dword, zero low byte) resets. */
  {
    const base = {
      f8: 0, f0c: 0, f10: 0, f14: 0, f18: 0, f1c: 0, f20: 0, f22: 0, f23: 0,
      f24: 0, f30: 0, f38: 0, f3c: 0, f40: 0, f50: 0, f54: 0x3f800000,
      f58: 0, f5c: 0, f60: 0,
    };
    assert.equal(JL("reset0", { ...base, f24: 0 }, 5, 0, 0x64, 0).got.reset_5c0,
                 0, "f24=0 skips the 0x5c0 reset");
    assert.equal(JL("resetNeg1", { ...base, f24: 0xffffffff }, 5, 0, 0x64, 0)
                   .got.reset_5c0, 0, "f24=-1 skips the 0x5c0 reset");
    assert.equal(JL("resetWide", { ...base, f24: 0x100 }, 5, 0, 0x64, 0)
                   .got.reset_5c0, 1, "f24=0x100 (nonzero dword) resets");
  }

  /* call B gate legs: field_2c!=0x64 || field_30==0 || old byte == new
     byte each suppress the call; wide byte drives prove the old/new
     compare masks to the low byte (old_52e=0x100 -> byte 0). */
  {
    const base = {
      f8: 0, f0c: 0, f10: 0, f14: 0, f18: 0, f1c: 0, f20: 0, f22: 0, f23: 1,
      f24: 0, f30: 1, f38: 0, f3c: 0, f40: 0, f50: 0, f54: 0x3f800000,
      f58: 0, f5c: 0, f60: 0,
    };
    assert.equal(JL("bLeg2c", { ...base, f23: 1 }, 5, 0x2, 0x65, 1)
                   .got.call_b_fire, 0, "field_2c!=0x64 no fire");
    assert.equal(JL("bLeg30", { ...base, f23: 1 }, 5, 0x2, 0x64, 0)
                   .got.call_b_fire, 0, "field_30==0 no fire");
    assert.equal(JL("bLegSame", { ...base, f23: 0x1 }, 5, 0x1, 0x64, 1)
                   .got.call_b_fire, 0, "old byte == new byte no fire");
    assert.equal(JL("bLegWideOld", { ...base, f23: 0 }, 5, 0x100, 0x64, 1)
                   .got.call_b_fire, 0, "old_52e=0x100 masks to 0 == new (0) -> no fire");
    assert.equal(JL("bLegWideNew", { ...base, f23: 0x1ff }, 5, 0, 0x64, 1)
                   .got.call_b_fire, 1, "f23=0x1ff masks to 0xff != old -> fire");
  }
});

test("room v58: store-pack mutation discrimination", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s2) => (crlfFile ? s2.replace(/\n/g, "\r\n") : s2);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, label + ": mutant did not apply");
    writeSourceRetry(toFile(bad));
    let threw = false;
    try { check(); } catch { threw = true; }
    writeSourceRetry(original);
    assert.ok(threw, label + ": mutant survived every assertion");
  };
  const drive = () => {
    const e = loadExports();
    const view = new DataView(e.memory.buffer);
    const SRC = MEM + 0x7e00;
    const OUT = MEM + 0x7e80;
    const src = {
      f8: 0x100, f0c: 0xaa, f10: 7, f14: 0xbb, f18: 0xfffffffe, f1c: 0x1c,
      f20: 0x8000, f22: 0x1ff, f23: 0x2ff, f24: 5, f30: 0x30, f38: 0x38,
      f3c: 0x3c, f40: 0x40, f50: 0x50, f54: 0x40000000, f58: 0x58, f5c: 0x5c,
      f60: 0x1ff,
    };
    v58WriteSrc(view, SRC, src);
    e.b15BindStorePack(SRC, 5, 0x1, 0x64, 1, OUT);
    return v58ReadOut(view, OUT);
  };
  try {
    const eq = (a, b) => assert.equal(a, b);
    /* (1) FIELD OFFSET: dst 0x3dc read from src f3c instead of f38. */
    withMutant("store-pack field offset 3dc",
      (s2) => s2.replace("out->dst_3dc = src->f38;", "out->dst_3dc = src->f3c;"),
      () => {
        const o = drive();
        eq(o.dst_3dc, 0x38);
        eq(o.dst_34, 0x3c);
      });
    /* (2) ORDER: dst 0x34 / dst 0x38 sources swapped (f3c <-> f40). */
    withMutant("store-pack order 34/38",
      (s2) => s2
        .replace("out->dst_34 = src->f3c;", "out->dst_34 = src->f40; /*SWAP*/")
        .replace("out->dst_38 = src->f40;", "out->dst_38 = src->f3c; /*SWAP*/"),
      () => {
        const o = drive();
        eq(o.dst_34, 0x3c);
        eq(o.dst_38, 0x40);
      });
    /* (3) SIGNED WORD EXTENSION: movsx -> plain word (zero-extend). */
    withMutant("store-pack sxw zero-extend",
      (s2) => s2.replace(
        "static_cast<int16_t>(src->f20 & 0xffffu)));",
        "static_cast<uint16_t>(src->f20 & 0xffffu)));"),
      () => {
        eq(drive().dst_32c, 0xffff8000);
      });
    /* (4) QWORD SOURCE: qword const lo/hi swapped (4/3 -> 3/4). */
    withMutant("store-pack qword const swap",
      (s2) => s2.replace(
        "out->dst_3e0_lo = ISAAC_ROOM_B15_BIND_STORE_QWORD_LO;",
        "out->dst_3e0_lo = ISAAC_ROOM_B15_BIND_STORE_QWORD_HI;"),
      () => {
        const o = drive();
        eq(o.dst_3e0_lo, 0x4);
        eq(o.dst_3e0_hi, 0x3);
        eq(o.dst_3e8, 0x11);
      });
    /* (5) [ebx+8] gate narrowed to a low-byte test -> 0x100 (nonzero
       dword, zero low byte) would NOT enable the 0x524 store. */
    withMutant("store-pack 0x524 low-byte gate",
      (s2) => s2.replace("out->store_524 = (src->f8 != 0u) ? 1u : 0u;",
                         "out->store_524 = ((src->f8 & 0xffu) != 0u) ? 1u : 0u;"),
      () => {
        eq(drive().store_524, 1);
      });
    /* (6) CLAMP SIGN FLIP: unsigned upper compare would clamp 0xffffffff
       (signed -1, IN range) to 7 instead of keeping -1. */
    withMutant("store-pack clamp unsigned",
      (s2) => s2.replace(
        "isaac_room_b15_bind_clamp_val(static_cast<int32_t>(src->f18)));",
        "((src->f18 > 7u) ? 7u : src->f18));"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const SRC = MEM + 0x7f00;
        const OUT = MEM + 0x7f80;
        const src = {
          f8: 0, f0c: 0, f10: 0, f14: 0, f18: 0xffffffff, f1c: 0, f20: 0,
          f22: 0, f23: 0, f24: 0, f30: 0, f38: 0, f3c: 0, f40: 0, f50: 0,
          f54: 0x3f800000, f58: 0, f5c: 0, f60: 0,
        };
        v58WriteSrc(view, SRC, src);
        e.b15BindStorePack(SRC, 5, 0, 0x64, 0, OUT);
        eq(view.getUint32(OUT + 40, true), 0xffffffff, "clamp -1 stays -1");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});


/* ---- ABI v59: type-6 dispatch tail 0x7ef69a..0x7ef6c7 + 0x6c-stride
   ANM2 chain 0x7ef611..0x7ef62f ---- */

/* v59 struct layouts (pack 1, all dwords). */
const V59_TYPE6_SRC_OFF = { f0c: 0, f10: 4, f30: 8 };
const V59_TYPE6_OUT_OFF = {
  type6: 0, dst_420: 4, store_424: 8, dst_424: 12, call_d_fire: 16,
  call_d_va: 20, call_d_arg: 24, head_va: 28, ret_va: 32,
};
const V59_CHAIN_SRC_OFF = { base: 0, item_dword: 4 };
const V59_CHAIN_OUT_OFF = {
  stride: 0, next_base: 4, skip: 8, fire_a: 12, call_a_va: 16,
  call_a_this_off: 20, call_a_arg: 24, fire_b: 28, call_b_va: 32,
  call_b_this_off: 36, chain_va: 40, epilogue_va: 44,
};

function v59WriteChainSrc(view, base, src) {
  view.setUint32(base + 0, src.base >>> 0, true);
  view.setUint32(base + 4, src.item_dword >>> 0, true);
}
function v59ReadChainOut(view, base) {
  const out = {};
  for (const [k, off] of Object.entries(V59_CHAIN_OUT_OFF)) {
    out[k] = view.getUint32(base + off, true) >>> 0;
  }
  return out;
}
function v59WriteType6Src(view, base, src) {
  view.setUint32(base + 0, src.f0c >>> 0, true);
  view.setUint32(base + 4, src.f10 >>> 0, true);
  view.setUint32(base + 8, src.f30 >>> 0, true);
}
function v59ReadType6Out(view, base) {
  const out = {};
  for (const [k, off] of Object.entries(V59_TYPE6_OUT_OFF)) {
    out[k] = view.getUint32(base + off, true) >>> 0;
  }
  return out;
}

test("room v59: type-6 dispatch tail + 0x6c-stride chain (PE 0x7ef611..0x7ef6c7)", () => {
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.equal(ROOM_B15_BIND_CHAIN_VA, 0x007ef611);
  assert.equal(ROOM_B15_BIND_CHAIN_EPILOGUE_VA, 0x007ef630);
  assert.equal(ROOM_B15_BIND_CHAIN_STRIDE, 0x6c);
  assert.equal(ROOM_B15_BIND_CHAIN_THIS_A_OFF, 0x5c8);
  assert.equal(ROOM_B15_BIND_CHAIN_THIS_B_OFF, 0x5d0);
  assert.equal(ROOM_B15_BIND_CHAIN_HOST_A_VA, 0x004d74a0);
  assert.equal(ROOM_B15_BIND_CHAIN_HOST_B_VA, 0x00407f10);
  assert.equal(ROOM_B15_BIND_TYPE6_VA, 0x007ef69a);
  assert.equal(ROOM_B15_BIND_TYPE6_RET_VA, 0x007ef6c7);
  assert.equal(ROOM_B15_BIND_TYPE6, 6);
  assert.equal(ROOM_B15_BIND_TYPE6_FIELD_2C_GATE, 0xa);
  assert.equal(ROOM_B15_BIND_TYPE6_HOST_D_VA, 0x00665500);

  const { memory, b15BindChainVa, b15BindChainEpilogueVa,
          b15BindChainStep, b15BindType6Va, b15BindType6RetVa,
          b15BindType6 } = loadExports();
  assert.equal(b15BindChainVa() >>> 0, 0x007ef611, "wasm chain VA");
  assert.equal(b15BindChainEpilogueVa() >>> 0, 0x007ef630, "wasm epilogue VA");
  assert.equal(b15BindType6Va() >>> 0, 0x007ef69a, "wasm type6 head VA");
  assert.equal(b15BindType6RetVa() >>> 0, 0x007ef6c7, "wasm type6 ret 8 VA");

  const view = new DataView(memory.buffer);
  const CSRC = MEM + 0x8100, COUT = MEM + 0x8140;
  const TSRC = MEM + 0x8180, TOUT = MEM + 0x81c0;
  const chainJL = (label, src) => {
    const want = roomB15BindChainStep(src.base, src.item_dword);
    v59WriteChainSrc(view, CSRC, src);
    b15BindChainStep(CSRC, COUT);
    const got = v59ReadChainOut(view, COUT);
    for (const k of Object.keys(V59_CHAIN_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: chain.${k}`);
    }
    return got;
  };
  const type6JL = (label, src, type28, field2c) => {
    const want = roomB15BindType6(src, type28, field2c);
    v59WriteType6Src(view, TSRC, src);
    b15BindType6(TSRC, type28 >>> 0, field2c >>> 0, TOUT);
    const got = v59ReadType6Out(view, TOUT);
    for (const k of Object.keys(V59_TYPE6_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: type6.${k}`);
    }
    return got;
  };

  /* ---- CHAIN (PE-truth, cpu-dump/007ef611.txt): add ebx,0x6c ; cmp
     dword ptr [ebx],0 ; je 0x7ef630 (FULL-dword zero test) ; push ebx ;
     lea ecx,[edi+0x5c8] ; call 0x4d74a0 ; lea ecx,[edi+0x5d0] ; call
     0x407f10 (ANM2::Reset) ; fall into the shared epilogue @0x7ef630
     (v56 tail-gate law covers its pure 0x7ef63c..0x7ef687 gate). ---- */
  {
    const g = chainJL("chainSkip", { base: 0x12345678, item_dword: 0 });
    assert.equal(g.stride, 0x6c, "stride const 0x6c");
    assert.equal(g.next_base, 0x123456e4, "base + 0x6c");
    assert.equal(g.skip, 1, "[ebx]==0 -> je skips BOTH host calls");
    assert.equal(g.fire_a, 0, "skip -> no call A");
    assert.equal(g.fire_b, 0, "skip -> no call B");
  }
  {
    const g = chainJL("chainFireWide", { base: 0x12345678, item_dword: 0x100 });
    assert.equal(g.skip, 0, "0x100 nonzero dword, zero low byte -> NO skip");
    assert.equal(g.fire_a, 1, "fires call A");
    assert.equal(g.fire_b, 1, "fires call B (ANM2::Reset)");
    assert.equal(g.call_a_va, 0x004d74a0, "call A VA");
    assert.equal(g.call_a_this_off, 0x5c8, "call A this offset 0x5c8");
    assert.equal(g.call_a_arg, 0x123456e4, "call A arg = POST-add ebx");
    assert.equal(g.call_b_va, 0x00407f10, "call B VA");
    assert.equal(g.call_b_this_off, 0x5d0, "call B this offset 0x5d0");
    assert.equal(g.chain_va, 0x007ef611, "chain head VA");
    assert.equal(g.epilogue_va, 0x007ef630, "epilogue boundary VA");
  }
  {
    const g = chainJL("chainWrap", { base: 0xfffffffc, item_dword: 0x80000000 });
    assert.equal(g.next_base, 0x68, "u32 wrap: 0xfffffffc + 0x6c -> 0x68");
    assert.equal(g.skip, 0, "0x80000000 (negative i32, nonzero dword) -> fire");
  }
  {
    const g = chainJL("chainWrapMax", { base: 0xffffffff, item_dword: 1 });
    assert.equal(g.next_base, 0x6b, "u32 wrap: 0xffffffff + 0x6c -> 0x6b");
    assert.equal(g.skip, 0, "nonzero dword fires");
  }

  /* ---- TYPE-6 (PE-truth, cpu-dump/007ef69a.txt): cmp esi,6 ; jne
     0x7ef6ca (FULL-dword type gate) ; cmp [edi+0x2c],0xa (sets FLAGS) ;
     mov eax,[ebx+0xc] ; mov [edi+0x420],eax (NO flag effect) ; jne
     0x7ef6b7 (tests the cmp's ZF) ; mov eax,[ebx+0x10] ; mov
     [edi+0x424],eax ; push [ebx+0x30] ; mov ecx,edi ; call 0x665500
     (HOST, unconditional within the body) ; ret 8. ---- */
  {
    const g = type6JL("t6Full",
      { f0c: 0x11111111, f10: 0x22222222, f30: 0x33333333 }, 6, 0xa);
    assert.equal(g.type6, 1, "type 6 -> body runs");
    assert.equal(g.dst_420, 0x11111111, "0x420 = f0c (unconditional)");
    assert.equal(g.store_424, 1, "field_2c==0xa -> 0x424 store");
    assert.equal(g.dst_424, 0x22222222, "0x424 = f10");
    assert.equal(g.call_d_fire, 1, "call D fires within the body");
    assert.equal(g.call_d_va, 0x00665500, "call D VA");
    assert.equal(g.call_d_arg, 0x33333333, "call D arg = f30");
    assert.equal(g.head_va, 0x007ef69a, "type6 head VA");
    assert.equal(g.ret_va, 0x007ef6c7, "type6 ret 8 VA");
  }
  {
    const g = type6JL("t6No424",
      { f0c: 0xaaaa, f10: 0xbbbb, f30: 0xcccc }, 6, 0xb);
    assert.equal(g.type6, 1, "type 6 body runs");
    assert.equal(g.dst_420, 0xaaaa,
      "0x420 store STILL runs when 2c!=0xa (cmp ZF survives mov/mov)");
    assert.equal(g.store_424, 0, "field_2c!=0xa -> no 0x424 store");
    assert.equal(g.call_d_fire, 1, "call D still fires");
  }
  {
    const g = type6JL("t6Wide2c", { f0c: 1, f10: 2, f30: 3 }, 6, 0x100a);
    assert.equal(g.store_424, 0,
      "FULL-dword 2c gate: 0x100a != 0xa (low byte 0xa must NOT pass)");
  }
  {
    const g = type6JL("t6WideType", { f0c: 1, f10: 2, f30: 3 }, 0x106, 0xa);
    assert.equal(g.type6, 0, "FULL-dword type gate: 0x106 != 6");
    assert.equal(g.store_424, 0, "not type 6 -> no 0x424 store");
    assert.equal(g.call_d_fire, 0, "not type 6 -> no call D");
  }
  {
    const g = type6JL("t6Type5", { f0c: 1, f10: 2, f30: 3 }, 5, 0xa);
    assert.equal(g.type6, 0, "type 5 -> next dispatch (0x3e8) — body skipped");
  }
});

test("room v59: type-6 + chain mutation discrimination", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s2) => (crlfFile ? s2.replace(/\n/g, "\r\n") : s2);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, label + ": mutant did not apply");
    writeSourceRetry(toFile(bad));
    let threw = false;
    try { check(); } catch { threw = true; }
    writeSourceRetry(original);
    assert.ok(threw, label + ": mutant survived every assertion");
  };
  try {
    const eq = (a, b) => assert.equal(a, b);
    /* (1) FLAG LIFETIME (recapture): gating dst_420 on the 0xa compare
       would drop the UNCONDITIONAL 0x420 store for field_2c != 0xa. */
    withMutant("type6 dst_420 gated on 0xa",
      (s2) => s2.replace(
        "out->dst_420 = src->f0c;",
        "out->dst_420 = (static_cast<int32_t>(field_2c) == ISAAC_ROOM_B15_BIND_TYPE6_FIELD_2C_GATE) ? src->f0c : 0u;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const TSRC = MEM + 0x8200, TOUT = MEM + 0x8240;
        v59WriteType6Src(view, TSRC, { f0c: 0xaaaa, f10: 0xbbbb, f30: 1 });
        e.b15BindType6(TSRC, 6, 0xb, TOUT);
        eq(view.getUint32(TOUT + 4, true), 0xaaaa,
          "0x420 = f0c even when field_2c != 0xa");
      });
    /* (2) GATE DROPPED: store_424 always set for type6 -> field_2c != 0xa
       would wrongly enable the 0x424 store. */
    withMutant("type6 store_424 gate dropped",
      (s2) => s2.replace(
        "static_cast<int32_t>(field_2c) ==\n                    ISAAC_ROOM_B15_BIND_TYPE6_FIELD_2C_GATE) ? 1u : 0u;",
        "ISAAC_ROOM_B15_BIND_TYPE6_FIELD_2C_GATE) ? 1u : 0u;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const TSRC = MEM + 0x8280, TOUT = MEM + 0x82c0;
        v59WriteType6Src(view, TSRC, { f0c: 1, f10: 2, f30: 3 });
        e.b15BindType6(TSRC, 6, 0xb, TOUT);
        eq(view.getUint32(TOUT + 8, true), 0, "field_2c=0xb -> store_424 0");
      });
    /* (3) TYPE GATE LOW-BYTE: (type_28 & 0xff)==6 would accept 0x106. */
    withMutant("type6 type gate low-byte",
      (s2) => s2.replace(
        "(static_cast<int32_t>(type_28) ==\n                         ISAAC_ROOM_B15_BIND_TYPE6) ? 1 : 0;",
        "((type_28 & 0xffu) ==\n                         ISAAC_ROOM_B15_BIND_TYPE6) ? 1 : 0;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const TSRC = MEM + 0x8300, TOUT = MEM + 0x8340;
        v59WriteType6Src(view, TSRC, { f0c: 1, f10: 2, f30: 3 });
        e.b15BindType6(TSRC, 0x106, 0xa, TOUT);
        eq(view.getUint32(TOUT, true), 0, "0x106 != 6 -> type6 0");
      });
    /* (4) STRIDE FOLDED: 0x6c -> 0x60 shifts next_base. */
    withMutant("chain stride 0x60",
      (s2) => s2.replace(
        "out->next_base = src->base + ISAAC_ROOM_B15_BIND_CHAIN_STRIDE;",
        "out->next_base = src->base + 0x60u;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const CSRC = MEM + 0x8380, COUT = MEM + 0x83c0;
        v59WriteChainSrc(view, CSRC, { base: 0x12345678, item_dword: 1 });
        e.b15BindChainStep(CSRC, COUT);
        eq(view.getUint32(COUT + 4, true), 0x123456e4,
          "next_base = base + 0x6c");
      });
    /* (5) SKIP LOW-BYTE: (item_dword & 0xff)==0 would skip 0x100. */
    withMutant("chain skip low-byte",
      (s2) => s2.replace(
        "out->skip = (src->item_dword == 0u) ? 1u : 0u;",
        "out->skip = ((src->item_dword & 0xffu) == 0u) ? 1u : 0u;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const CSRC = MEM + 0x8400, COUT = MEM + 0x8440;
        v59WriteChainSrc(view, CSRC, { base: 0x1000, item_dword: 0x100 });
        e.b15BindChainStep(CSRC, COUT);
        eq(view.getUint32(COUT + 8, true), 0,
          "0x100 nonzero dword -> NOT skipped");
      });
    /* (6) CALL A ARG PRE-ADD: push ebx runs AFTER add ebx,0x6c, so the
       arg is next_base, not the pre-add base. */
    withMutant("chain call A arg pre-add",
      (s2) => s2.replace(
        "out->call_a_arg = out->next_base;",
        "out->call_a_arg = src->base;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const CSRC = MEM + 0x8480, COUT = MEM + 0x84c0;
        v59WriteChainSrc(view, CSRC, { base: 0x12345678, item_dword: 1 });
        e.b15BindChainStep(CSRC, COUT);
        eq(view.getUint32(COUT + 24, true), 0x123456e4,
          "call A arg = POST-add ebx");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});

/* ---- ABI v60: type-1000 dispatch head 0x7ef6ca..0x7ef817 ---- */

/* v60 struct layouts (pack 1, all dwords). */
const V60_T1000_SRC_OFF = { f0c: 0, f10: 4, f18: 8 };
const V60_T1000_OUT_OFF = {
  type1000: 0, mode_pos: 4, mode_44: 8, mode_74: 12, mode_78: 16,
  mode_default: 20, store_420: 24, dst_420: 28, store_424: 32, dst_424: 36,
  store_450: 40, dst_450: 44, indirect_fire: 48, indirect_slot: 52,
  pos_fire: 56, pos_genrand_va: 60, pos_scale_va: 64, pos_scale_bits: 68,
  pos_sign_tbl_va: 72, pos_game_global: 76, pos_game_off: 80, head_va: 84,
  next_va: 88, default_va: 92,
};
const V60_POS_SRC_OFF = { v0_bits: 0, v1_bits: 4, v2_bits: 8, v3_bits: 12 };
const V60_POS_OUT_OFF = {
  dst_33c_bits: 0, dst_340_bits: 4, genrand_va: 8, scale_bits: 12,
};

function v60WriteT1000Src(view, base, src) {
  view.setUint32(base + 0, src.f0c >>> 0, true);
  view.setUint32(base + 4, src.f10 >>> 0, true);
  view.setUint32(base + 8, src.f18 >>> 0, true);
}
function v60ReadT1000Out(view, base) {
  const out = {};
  for (const [k, off] of Object.entries(V60_T1000_OUT_OFF)) {
    out[k] = view.getUint32(base + off, true) >>> 0;
  }
  return out;
}
function v60WritePosSrc(view, base, src) {
  view.setUint32(base + 0, src.v0_bits >>> 0, true);
  view.setUint32(base + 4, src.v1_bits >>> 0, true);
  view.setUint32(base + 8, src.v2_bits >>> 0, true);
  view.setUint32(base + 12, src.v3_bits >>> 0, true);
}
function v60ReadPosOut(view, base) {
  const out = {};
  for (const [k, off] of Object.entries(V60_POS_OUT_OFF)) {
    out[k] = view.getUint32(base + off, true) >>> 0;
  }
  return out;
}
function v60F32(view, bits) {
  const v = new DataView(view.buffer);
  v.setUint32(0, bits >>> 0, true);
  return v.getFloat32(0, true);
}

test("room v60: type-1000 dispatch head (PE 0x7ef6ca..0x7ef817)", () => {
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.equal(ROOM_B15_BIND_TYPE1000_VA, 0x007ef6ca);
  assert.equal(ROOM_B15_BIND_TYPE1000_NEXT_VA, 0x007ef817);
  assert.equal(ROOM_B15_BIND_TYPE1000_DEFAULT_VA, 0x007efa3d);
  assert.equal(ROOM_B15_BIND_TYPE1000_TYPE, 0x3e8);
  assert.deepEqual(ROOM_B15_BIND_TYPE1000_POS_SET,
    [0x15, 0x21, 0x3f, 0x40, 0x41, 0x45, 0x9e]);
  assert.equal(ROOM_B15_BIND_TYPE1000_MODE_44, 0x44);
  assert.equal(ROOM_B15_BIND_TYPE1000_MODE_74, 0x74);
  assert.equal(ROOM_B15_BIND_TYPE1000_MODE_78, 0x78);
  assert.equal(ROOM_B15_BIND_TYPE1000_VTABLE_SLOT, 0xc);
  assert.equal(ROOM_B15_BIND_TYPE1000_GENRAND_VA, 0x006eef60);
  assert.equal(ROOM_B15_BIND_TYPE1000_SCALE_VA, 0x00ba9ff4);
  assert.equal(ROOM_B15_BIND_TYPE1000_SCALE_BITS, 0x2f800000);
  assert.equal(ROOM_B15_BIND_TYPE1000_SIGN_TABLE_VA, 0x00bacb00);
  assert.equal(ROOM_B15_BIND_TYPE1000_GAME_GLOBAL, 0x00c71678);
  assert.equal(ROOM_B15_BIND_TYPE1000_GAME_18300_OFF, 0x18300);

  const { memory, b15BindType1000Va, b15BindType1000NextVa,
          b15BindType1000DefaultVa, b15BindType1000,
          b15BindType1000Pos } = loadExports();
  assert.equal(b15BindType1000Va() >>> 0, 0x007ef6ca, "wasm type1000 head VA");
  assert.equal(b15BindType1000NextVa() >>> 0, 0x007ef817, "wasm next dispatch VA");
  assert.equal(b15BindType1000DefaultVa() >>> 0, 0x007efa3d, "wasm default VA");

  const view = new DataView(memory.buffer);
  const TSRC = MEM + 0x8500, TOUT = MEM + 0x8540;
  const PSRC = MEM + 0x8580, POUT = MEM + 0x85c0;
  const t1000JL = (label, src, type28, field2c) => {
    const want = roomB15BindType1000(src, type28, field2c);
    v60WriteT1000Src(view, TSRC, src);
    b15BindType1000(TSRC, type28 >>> 0, field2c >>> 0, TOUT);
    const got = v60ReadT1000Out(view, TOUT);
    for (const k of Object.keys(V60_T1000_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: t1000.${k}`);
    }
    return got;
  };
  const posJL = (label, src, g0, g1) => {
    const want = roomB15BindType1000Pos(src, g0, g1);
    v60WritePosSrc(view, PSRC, src);
    b15BindType1000Pos(PSRC, g0 >>> 0, g1 >>> 0, POUT);
    const got = v60ReadPosOut(view, POUT);
    for (const k of Object.keys(V60_POS_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: pos.${k}`);
    }
    return got;
  };

  /* ---- TYPE GATE (cpu-dump/007ef6ca.txt): cmp esi,0x3e8 FULL dword ;
     jne 0x7ef817 -> NEXT dispatch (types 0x21/0x124/4..., host). esi =
     [edi+0x28] read @0x7ef4ca. Type != 1000: body never entered; the
     mode flags + store flags are field_2c classifications the caller
     ANDs with type1000 (PE never executes the mode compares when
     type != 1000). */
  {
    const g = t1000JL("t1000Full",
      { f0c: 0x11111111, f10: 0x22222222, f18: 0x33333333 }, 0x3e8, 0x74);
    assert.equal(g.type1000, 1, "type 1000 -> body entered");
    assert.equal(g.mode_74, 1, "mode 0x74 branch");
    assert.equal(g.store_450, 1, "mode 0x74 stores 0x450");
    assert.equal(g.dst_450, 0x11111111, "0x450 = src.f0c");
    assert.equal(g.store_420, 0, "0x74 does NOT store 0x420");
    assert.equal(g.store_424, 0, "0x74 does NOT store 0x424");
    assert.equal(g.mode_default, 0, "not default");
    assert.equal(g.head_va, 0x007ef6ca, "head VA");
    assert.equal(g.next_va, 0x007ef817, "next dispatch VA");
    assert.equal(g.default_va, 0x007efa3d, "default epilogue VA");
  }
  {
    const g = t1000JL("t1000TypeNot",
      { f0c: 1, f10: 2, f18: 3 }, 0x1e8, 0x74);
    assert.equal(g.type1000, 0,
      "FULL-dword type gate: 0x1e8 != 0x3e8 (low byte 0xe8 matches)");
  }
  {
    const g = t1000JL("t1000TypeWideMax",
      { f0c: 1, f10: 2, f18: 3 }, 0xffffffff, 0x74);
    assert.equal(g.type1000, 0, "0xffffffff != 0x3e8");
  }
  /* ---- MODE 0x78: THREE stores incl. the 0x7ef733 fall-through
     (0x7ef721 [edi+0x420]=[ebx+0x18] ; 0x7ef72a [edi+0x424]=[ebx+0x10] ;
     fall 0x7ef733 [edi+0x450]=[ebx+0xc]). ---- */
  {
    const g = t1000JL("t1000Mode78",
      { f0c: 0xaaaaaaaa, f10: 0xbbbbbbbb, f18: 0xcccccccc }, 0x3e8, 0x78);
    assert.equal(g.mode_78, 1, "mode 0x78 branch");
    assert.equal(g.store_420, 1, "0x78 stores 0x420");
    assert.equal(g.dst_420, 0xcccccccc, "0x420 = src.f18");
    assert.equal(g.store_424, 1, "0x78 stores 0x424");
    assert.equal(g.dst_424, 0xbbbbbbbb, "0x424 = src.f10");
    assert.equal(g.store_450, 1, "0x78 falls into 0x450 store");
    assert.equal(g.dst_450, 0xaaaaaaaa, "0x450 = src.f0c");
    assert.equal(g.mode_74, 0, "not 0x74");
  }
  /* ---- WIDE mode drives: 0x178/0x144/0x115 must NOT match (FULL-dword
     cmp eax,imm8 sign-ext). ---- */
  {
    const g = t1000JL("t1000Mode78Wide",
      { f0c: 1, f10: 2, f18: 3 }, 0x3e8, 0x178);
    assert.equal(g.mode_78, 0, "FULL-dword: 0x178 != 0x78");
    assert.equal(g.mode_default, 1, "0x178 -> default, no stores");
    assert.equal(g.store_420, 0, "no 0x420 store");
    assert.equal(g.store_450, 0, "no 0x450 store");
    assert.equal(g.indirect_fire, 0, "no indirect call");
  }
  {
    const g = t1000JL("t1000Mode44Wide",
      { f0c: 1, f10: 2, f18: 3 }, 0x3e8, 0x144);
    assert.equal(g.mode_44, 0, "FULL-dword: 0x144 != 0x44");
    assert.equal(g.indirect_fire, 0, "no indirect call");
  }
  /* ---- MODE 0x44: INDIRECT vtable call [eax+0xc] (eax=[edi], ecx=edi,
     HOST, 1 indirect call) then ret 8. NO stores. ---- */
  {
    const g = t1000JL("t1000Mode44",
      { f0c: 1, f10: 2, f18: 3 }, 0x3e8, 0x44);
    assert.equal(g.mode_44, 1, "mode 0x44 branch");
    assert.equal(g.indirect_fire, 1, "indirect call fires");
    assert.equal(g.indirect_slot, 0xc, "vtable slot offset +0xc");
    assert.equal(g.store_420, 0, "no stores on 0x44");
    assert.equal(g.store_424, 0, "no 0x424 store");
    assert.equal(g.store_450, 0, "no 0x450 store");
    assert.equal(g.pos_fire, 0, "no pos path on 0x44");
  }
  /* ---- POS SET {0x15,0x21,0x3f,0x40,0x41,0x45,0x9e}: each member ->
     je 0x7ef745 position-model path; member + 0x100 must NOT match. ---- */
  for (const mode of ROOM_B15_BIND_TYPE1000_POS_SET) {
    const g = t1000JL(`t1000Pos${mode.toString(16)}`,
      { f0c: 1, f10: 2, f18: 3 }, 0x3e8, mode);
    assert.equal(g.mode_pos, 1, `mode 0x${mode.toString(16)} in POS set`);
    assert.equal(g.pos_fire, 1, "pos path fires");
    assert.equal(g.pos_genrand_va, 0x006eef60, "genrand host VA");
    assert.equal(g.pos_scale_va, 0x00ba9ff4, "scale VA");
    assert.equal(g.pos_scale_bits, 0x2f800000, "scale bits 2^-32");
    assert.equal(g.pos_sign_tbl_va, 0x00bacb00, "sign table VA");
    assert.equal(g.pos_game_global, 0x00c71678, "game global");
    assert.equal(g.pos_game_off, 0x18300, "game +0x18300 off");
    assert.equal(g.mode_default, 0, "pos mode is not default");
    const wide = t1000JL(`t1000PosWide${mode.toString(16)}`,
      { f0c: 1, f10: 2, f18: 3 }, 0x3e8, mode + 0x100);
    assert.equal(wide.mode_pos, 0, `0x${(mode + 0x100).toString(16)} != mode (FULL dword)`);
  }
  {
    const g = t1000JL("t1000Default",
      { f0c: 1, f10: 2, f18: 3 }, 0x3e8, 0x99);
    assert.equal(g.mode_default, 1, "mode 0x99 -> default epilogue");
    assert.equal(g.store_450, 0, "no stores on default");
    assert.equal(g.indirect_fire, 0, "no indirect on default");
    assert.equal(g.pos_fire, 0, "no pos on default");
  }

  /* ---- POS-MODEL PATH (PE 0x7ef745..0x7ef806): a0..a3 = f32
     [Game->0x18300 + 0x14/0x18/0x1c/0x20] (host blob); HOST genrand #1
     (0x7ef77c) -> u32_1 -> Y; HOST genrand #2 (0x7ef7bd) -> u32_2 -> X.
     u32->f32: cvtdq2pd signed + 0xbacb00 bias (0.0 or 2^32 f64) +
     cvtpd2ps, then mulss 0x2f800000 (2^-32) -> unit. y = a1 +
     unit0*(a3-a1) -> [edi+0x340]; x = a0 + unit1*(a2-a0) -> [edi+0x33c].
     subss/mulss/addss single-rounding f32 each. ---- */
  const POS_SRC_0 = {
    v0_bits: 0x3f800000, /* a0 = 1.0 */
    v1_bits: 0x40400000, /* a1 = 3.0 */
    v2_bits: 0x40800000, /* a2 = 4.0 */
    v3_bits: 0x40c00000, /* a3 = 6.0 */
  };
  {
    /* genrand0 0x80000000: signed -2^31, +2^32 -> 2^31 -> f32 2^31 ->
       unit0 = Math.fround(2^31 * 2^-32) = 0.5. y = 3 + 0.5*(6-3) = 4.5. */
    const g = posJL("posYHalf",
      POS_SRC_0, 0x80000000, 0x00000000);
    assert.equal(v60F32(view, g.dst_340_bits), 4.5,
      "y = a1 + unit0*(a3-a1) = 3 + 0.5*3 = 4.5");
    assert.equal(g.genrand_va, 0x006eef60, "pos genrand VA");
    assert.equal(g.scale_bits, 0x2f800000, "pos scale bits");
  }
  {
    /* genrand1 0x40000000 -> f32 2^30 -> unit1 = Math.fround(2^30*2^-32)
       = 0.25. x = 1 + 0.25*(4-1) = 1.75 -> f32 bits 0x3fe00000. */
    const g = posJL("posXQuarter",
      POS_SRC_0, 0x00000000, 0x40000000);
    assert.equal(g.dst_33c_bits, 0x3fe00000,
      "x = a0 + unit1*(a2-a0) = 1 + 0.25*3 = 1.75 (0x3fe00000)");
  }
  {
    /* genrand 0xffffffff: signed -1, +2^32 -> 4294967295 f64 ->
       cvtpd2ps rounds to 2^32 -> unit = 1.0 exactly. x = a0 + (a2-a0)
       = a2; y = a1 + (a3-a1) = a3. */
    const g = posJL("posMaxOnes",
      POS_SRC_0, 0xffffffff, 0xffffffff);
    assert.equal(g.dst_33c_bits, 0x40800000,
      "unit1 = 1.0 for u32 0xffffffff -> x = a2 = 4.0 (0x40800000)");
    assert.equal(g.dst_340_bits, 0x40c00000,
      "unit0 = 1.0 for u32 0xffffffff -> y = a3 = 6.0 (0x40c00000)");
  }
  {
    /* genrand 0 -> unit 0: x = a0, y = a1 unchanged. */
    const g = posJL("posZero",
      POS_SRC_0, 0x00000000, 0x00000000);
    assert.equal(g.dst_33c_bits, 0x3f800000, "x = a0 = 1.0");
    assert.equal(g.dst_340_bits, 0x40400000, "y = a1 = 3.0");
  }
  {
    /* Wide drives: 0x100 in genrand low byte must round through the
       full value; wasm pos matches the JS oracle bit-for-bit. */
    const g = posJL("posWideGenrand",
      POS_SRC_0, 0x100, 0x1ff);
    const want = roomB15BindType1000Pos(POS_SRC_0, 0x100, 0x1ff);
    assert.equal(g.dst_33c_bits, want.dst_33c_bits >>> 0,
      "wasm pos matches JS oracle for 0x100/0x1ff genrands");
  }
});

test("room v60: type-1000 + pos mutation discrimination", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s2) => (crlfFile ? s2.replace(/\n/g, "\r\n") : s2);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, label + ": mutant did not apply");
    writeSourceRetry(toFile(bad));
    let threw = false;
    try { check(); } catch { threw = true; }
    writeSourceRetry(original);
    assert.ok(threw, label + ": mutant survived every assertion");
  };
  try {
    const eq = (a, b) => assert.equal(a, b);
    /* (1) TYPE GATE LOW-BYTE: (type_28 & 0xff)==0xe8 would accept
       0x1e8 (low byte of 0x3e8). */
    withMutant("type1000 type gate low-byte",
      (s2) => s2.replace(
        "(static_cast<int32_t>(type_28) == ISAAC_ROOM_B15_BIND_TYPE1000_TYPE) ? 1 : 0;",
        "((type_28 & 0xffu) == 0xe8u) ? 1 : 0;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const TSRC = MEM + 0x8600, TOUT = MEM + 0x8640;
        v60WriteT1000Src(view, TSRC, { f0c: 1, f10: 2, f18: 3 });
        e.b15BindType1000(TSRC, 0x1e8, 0x74, TOUT);
        eq(view.getUint32(TOUT + 0, true), 0, "0x1e8 != 0x3e8 -> type1000 0");
      });
    /* (2) POS SET MEMBER DROPPED: omit 0x9e -> mode 0x9e misrouted to
       default. */
    withMutant("type1000 pos set drops 0x9e",
      (s2) => s2.replace(
        "m == ISAAC_ROOM_B15_BIND_TYPE1000_POS_F ||\n       m == ISAAC_ROOM_B15_BIND_TYPE1000_POS_G) ? 1 : 0;",
        "m == ISAAC_ROOM_B15_BIND_TYPE1000_POS_F) ? 1 : 0;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const TSRC = MEM + 0x8680, TOUT = MEM + 0x86c0;
        v60WriteT1000Src(view, TSRC, { f0c: 1, f10: 2, f18: 3 });
        e.b15BindType1000(TSRC, 0x3e8, 0x9e, TOUT);
        eq(view.getUint32(TOUT + 4, true), 1, "0x9e in POS set -> mode_pos 1");
      });
    /* (3) 0x74 SINGLE-STORE RECAPTURE: dropping 0x74 from store_450
       loses the shared 0x7ef733 store on the 0x74 path. */
    withMutant("type1000 store_450 drops 0x74",
      (s2) => s2.replace(
        "out->store_450 = ((m74 != 0) || (m78 != 0)) ? 1u : 0u;",
        "out->store_450 = (m78 != 0) ? 1u : 0u;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const TSRC = MEM + 0x8700, TOUT = MEM + 0x8740;
        v60WriteT1000Src(view, TSRC, { f0c: 0xaaaa, f10: 2, f18: 3 });
        e.b15BindType1000(TSRC, 0x3e8, 0x74, TOUT);
        eq(view.getUint32(TOUT + 40, true), 1, "mode 0x74 stores 0x450");
      });
    /* (4) 0x78 FALL-THROUGH RECAPTURE: gating the 0x450 store on the
       wrong mode (0x44) drops it for the 0x78 fall-through. */
    withMutant("type1000 store_450 gate on 0x44",
      (s2) => s2.replace(
        "out->store_450 = ((m74 != 0) || (m78 != 0)) ? 1u : 0u;",
        "out->store_450 = (m44 != 0) ? 1u : 0u;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const TSRC = MEM + 0x8780, TOUT = MEM + 0x87c0;
        v60WriteT1000Src(view, TSRC, { f0c: 0xaaaa, f10: 2, f18: 3 });
        e.b15BindType1000(TSRC, 0x3e8, 0x78, TOUT);
        eq(view.getUint32(TOUT + 40, true), 1, "mode 0x78 falls into 0x450 store");
      });
    /* (5) POS GENRAND ORDER SWAP: the PE uses genrand #1 for Y (dst
       0x340) and #2 for X (dst 0x33c); swapping unit0/unit1 mixes the
       axes. */
    withMutant("pos genrand order swap",
      (s2) => s2.replace(
        "const float unit0 = u32_unit(genrand0);   /* genrand #1 -> Y */\n  const float unit1 = u32_unit(genrand1);   /* genrand #2 -> X */",
        "const float unit0 = u32_unit(genrand1);   /* SWAP */\n  const float unit1 = u32_unit(genrand0);   /* SWAP */"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const PSRC = MEM + 0x8800, POUT = MEM + 0x8840;
        v60WritePosSrc(view, PSRC, {
          v0_bits: 0x3f800000, v1_bits: 0x40400000,
          v2_bits: 0x40800000, v3_bits: 0x40c00000,
        });
        e.b15BindType1000Pos(PSRC, 0x80000000, 0x40000000, POUT);
        eq(view.getUint32(POUT + 4, true), 0x40900000,
          "genrand0 0x80000000 (unit 0.5) drives Y: 3 + 0.5*3 = 4.5 (0x40900000)");
      });
    /* (6) SCALE FOLDED: unit = f32(u32) without the 2^-32 mulss ->
       a genrand 0x40000000 becomes f32 2^30 instead of 0.25. */
    withMutant("pos scale folded (no 2^-32)",
      (s2) => s2.replace(
        "const float unit_scale = __builtin_bit_cast(float, 0x2f800000u);\n    return as_f32 * unit_scale;",
        "const float unit_scale = __builtin_bit_cast(float, 0x2f800000u);\n    return as_f32;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const PSRC = MEM + 0x8880, POUT = MEM + 0x88c0;
        v60WritePosSrc(view, PSRC, {
          v0_bits: 0x3f800000, v1_bits: 0x40400000,
          v2_bits: 0x40800000, v3_bits: 0x40c00000,
        });
        e.b15BindType1000Pos(PSRC, 0x40000000, 0x00000000, POUT);
        eq(view.getUint32(POUT + 4, true), 0x40700000,
          "unit0 = 0.25 for genrand 0x40000000 -> y = 3 + 0.25*3 = 3.75 (0x40700000)");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});

/* ---- ABI v61: B15 bind dispatch tail 0x7ef817..0x7efa43 ---- */

/* v61 struct layouts (pack 1). */
const V61_TAIL_SRC_OFF = {
  f0c: 0, f10: 4, f14: 8, f18: 12, f1c: 16, f23: 20, f28: 24, f34: 28,
  f3c: 32, f50: 36, f54: 40, f60: 44,
};
const V61_TAIL_OUT_OFF = {
  type21: 0, type124: 4, type4: 8, type11: 12, type38b: 16,
  path_a: 20, path_b: 24, path_c: 28,
  store_438: 32, dst_438: 36, store_43c: 40, dst_43c: 44,
  store_440: 48, dst_440: 52, store_444: 56, dst_444: 60,
  store_463: 64, dst_463: 68, store_448: 72, dst_448: 76,
  store_418: 80, dst_418: 84, store_44c: 88, dst_44c: 92,
  store_e4: 96, dst_e4_bits: 100, store_e8: 104, dst_e8_bits: 108,
  store_34: 112, dst_34: 116, store_434: 120, dst_434: 124,
  chain_fire: 128, chain_arg: 132, chain_count: 136, chain_host_va: 140,
  subcall_fire: 144, subcall_va: 148, subcall_this_off: 152,
  chain_this_off: 156, chain_ret_va: 160, final_va: 164,
  store_380_v21: 168, dst_380_v21_bits: 172,
  store_380: 176, dst_380: 180,
  call_6d03e0_fire: 184, call_6d03e0_va: 188, call_6d03e0_arg: 192,
  call_6d03e0_arg2: 196,
  call_a10600_va: 200, call_a10600_arg: 204, call_a10600_this_off: 208,
  call_812d00_va: 212, call_813520_va: 216, call_67f070_va: 220,
  gate_va: 224, lerp_fire: 228, genrand_va: 232, scale20_va: 236,
  scale20_bits: 240, scale2_va: 244, scale2_bits: 248, sign_tbl_va: 252,
  game_global: 256, game_count_lo_off: 260, game_count_hi_off: 264,
  f80_bits: 268, head_va: 272, default_va: 276,
};
const V61_LERP_SRC_OFF = {
  vec0_bits: 0, vec1_bits: 4, base_x_bits: 8, base_y_bits: 12,
};
const V61_LERP_OUT_OFF = {
  dst_33c_bits: 0, dst_340_bits: 4, genrand_va: 8, scale2_va: 12,
  scale2_bits: 16, scale20_va: 20, scale20_bits: 24, sign_tbl_va: 28,
  host_vec_va: 32, lerp_va: 36,
};

function v61WriteTailSrc(view, base, src) {
  for (const [k, off] of Object.entries(V61_TAIL_SRC_OFF)) {
    view.setUint32(base + off, (src[k] ?? 0) >>> 0, true);
  }
}
function v61ReadTailOut(view, base) {
  const out = {};
  for (const [k, off] of Object.entries(V61_TAIL_OUT_OFF)) {
    out[k] = view.getUint32(base + off, true) >>> 0;
  }
  return out;
}
function v61WriteLerpSrc(view, base, src) {
  for (const [k, off] of Object.entries(V61_LERP_SRC_OFF)) {
    view.setUint32(base + off, (src[k] ?? 0) >>> 0, true);
  }
}
function v61ReadLerpOut(view, base) {
  const out = {};
  for (const [k, off] of Object.entries(V61_LERP_OUT_OFF)) {
    out[k] = view.getUint32(base + off, true) >>> 0;
  }
  return out;
}
function v61F32(view, bits) {
  const v = new DataView(view.buffer);
  v.setUint32(0, bits >>> 0, true);
  return v.getFloat32(0, true);
}

test("room v61: B15 bind dispatch tail (PE 0x7ef817..0x7efa43)", () => {
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.equal(ROOM_B15_BIND_TAIL_VA, 0x007ef817);
  assert.equal(ROOM_B15_BIND_TAIL_PACK_VA, 0x007ef835);
  assert.equal(ROOM_B15_BIND_TAIL_OTHER_VA, 0x007ef924);
  assert.equal(ROOM_B15_BIND_TAIL_V21_VA, 0x007efa1a);
  assert.equal(ROOM_B15_BIND_TAIL_DEFAULT_VA, 0x007efa3d);
  assert.equal(ROOM_B15_BIND_TAIL_LERP_VA, 0x007ef9b4);
  assert.equal(ROOM_B15_BIND_TAIL_RET_VA, 0x007efa17);
  assert.equal(ROOM_B15_BIND_TAIL_TYPE4_RET_VA, 0x007ef921);
  assert.equal(ROOM_B15_BIND_TAIL_TYPE_21, 0x21);
  assert.equal(ROOM_B15_BIND_TAIL_TYPE_124, 0x124);
  assert.equal(ROOM_B15_BIND_TAIL_TYPE_4, 4);
  assert.equal(ROOM_B15_BIND_TAIL_TYPE_11, 0x11);
  assert.equal(ROOM_B15_BIND_TAIL_TYPE_38B, 0x38b);
  assert.equal(ROOM_B15_BIND_TAIL_CHAIN_HOST_VA, 0x00417870);
  assert.equal(ROOM_B15_BIND_TAIL_SUBCALL_VA, 0x004cf210);
  assert.equal(ROOM_B15_BIND_TAIL_SUBCALL_THIS_OFF, 0x3cc);
  assert.equal(ROOM_B15_BIND_TAIL_CHAIN_THIS_OFF, 0x3c8);
  assert.equal(ROOM_B15_BIND_TAIL_FINAL_VA, 0x004cdcf0);
  assert.equal(ROOM_B15_BIND_TAIL_GATE_VA, 0x006ac530);
  assert.equal(ROOM_B15_BIND_TAIL_6D03E0_VA, 0x006d03e0);
  assert.equal(ROOM_B15_BIND_TAIL_A10600_VA, 0x00a10600);
  assert.equal(ROOM_B15_BIND_TAIL_A10600_ARG, 0x00c7b640);
  assert.equal(ROOM_B15_BIND_TAIL_812D00_VA, 0x00812d00);
  assert.equal(ROOM_B15_BIND_TAIL_813520_VA, 0x00813520);
  assert.equal(ROOM_B15_BIND_TAIL_67F070_VA, 0x0067f070);
  assert.equal(ROOM_B15_BIND_TAIL_GENRAND_VA, 0x006eef60);
  assert.equal(ROOM_B15_BIND_TAIL_SCALE20_VA, 0x00baa87c);
  assert.equal(ROOM_B15_BIND_TAIL_SCALE20_BITS, 0x41a00000);
  assert.equal(ROOM_B15_BIND_TAIL_GAME_GLOBAL, 0x00c71678);
  assert.equal(ROOM_B15_BIND_TAIL_GAME_COUNT_LO_OFF, 0x1baa8);
  assert.equal(ROOM_B15_BIND_TAIL_GAME_COUNT_HI_OFF, 0x1baac);
  assert.equal(ROOM_B15_BIND_TAIL_F80_BITS, 0x42a00000);

  const { memory, b15BindTailDispatchVa, b15BindTailDispatch,
          b15BindTailLerp } = loadExports();
  assert.equal(b15BindTailDispatchVa() >>> 0, 0x007ef817, "wasm tail head VA");

  const view = new DataView(memory.buffer);
  const TSRC = MEM + 0x8900, TOUT = MEM + 0x8940;
  const LSRC = MEM + 0x89c0, LOUT = MEM + 0x8a00;
  const tailJL = (label, src, type28, f3c8, gLo, gHi) => {
    const want = roomB15BindTailDispatch(src, type28, f3c8, gLo, gHi);
    v61WriteTailSrc(view, TSRC, src);
    b15BindTailDispatch(TSRC, type28 >>> 0, f3c8 >>> 0, gLo >>> 0,
                        gHi >>> 0, TOUT);
    const got = v61ReadTailOut(view, TOUT);
    for (const k of Object.keys(V61_TAIL_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: tail.${k}`);
    }
    return got;
  };
  const lerpJL = (label, src, genrand) => {
    const want = roomB15BindTailLerp(src, genrand);
    v61WriteLerpSrc(view, LSRC, src);
    b15BindTailLerp(LSRC, genrand >>> 0, LOUT);
    const got = v61ReadLerpOut(view, LOUT);
    for (const k of Object.keys(V61_LERP_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: lerp.${k}`);
    }
    return got;
  };

  /* ---- TYPE DISPATCH (cpu-dump/007ef817.txt): cmp esi,0x21/0x124 ->
     je 0x7efa1a (path A); cmp esi,4 -> jne 0x7ef924 (path C). ALL FULL
     dword. ---- */
  {
    const wantBits = (() => {
      const dv = new DataView(new ArrayBuffer(4));
      dv.setFloat32(0, Math.fround(0x12345678), true);
      return dv.getUint32(0, true);
    })();
    const g = tailJL("tailV21Exact", { f0c: 0x12345678 }, 0x21, 0, 0, 0);
    assert.equal(g.type21, 1, "type 0x21 classified");
    assert.equal(g.path_a, 1, "type 0x21 -> path a");
    assert.equal(g.path_b, 0, "not path b");
    assert.equal(g.path_c, 0, "not path c");
    assert.equal(g.store_380_v21, 1, "v21 stores 0x380");
    assert.equal(g.dst_380_v21_bits, wantBits,
      "v21 dst 0x380 = f32(u32 src.f0c) exact bits");
    const wide = tailJL("tailV21Wide", { f0c: 1 }, 0x121, 0, 0, 0);
    assert.equal(wide.type21, 0, "FULL dword: 0x121 != 0x21 (low byte matches)");
    assert.equal(wide.path_a, 0, "0x121 not path a");
    assert.equal(wide.path_c, 1, "0x121 -> path c");
    assert.equal(wide.store_380_v21, 0, "no v21 store on 0x121");
  }
  {
    const g = tailJL("tailV124", { f0c: 0x87654321 }, 0x124, 0, 0, 0);
    assert.equal(g.type124, 1, "type 0x124 classified");
    assert.equal(g.path_a, 1, "type 0x124 -> path a");
    assert.equal(g.store_380_v21, 1, "0x124 stores 0x380 f32(u32)");
    const wide = tailJL("tailV124Wide", { f0c: 1 }, 0x324, 0, 0, 0);
    assert.equal(wide.type124, 0, "FULL dword: 0x324 != 0x124");
    assert.equal(wide.path_c, 1, "0x324 -> path c");
  }
  /* ---- TYPE 4 STORE PACK (0x7ef835..0x7ef8ac): 12 stores, the scale
     pair = f32(f54)*1.0f both axes. ---- */
  const PACK_SRC = {
    f0c: 0x0c0c0c0c, f10: 0x10101010, f14: 0x14141414, f18: 0x18181818,
    f1c: 0x1c1c1c1c, f23: 0x1234, f3c: 0x3c3c3c3c, f50: 0x50505050,
    f54: 0x40000000, /* f32 2.0 */
    f60: 0x7f,
  };
  {
    const g = tailJL("tailType4", PACK_SRC, 4, 0x0, 0x0, 0x0);
    assert.equal(g.type4, 1, "type 4 classified");
    assert.equal(g.path_b, 1, "type 4 -> path b");
    assert.equal(g.path_a, 0, "not path a");
    assert.equal(g.store_438, 1, "pack stores 0x438");
    assert.equal(g.dst_438, 0x10101010, "0x438 = src.f10");
    assert.equal(g.dst_43c, 0x14141414, "0x43c = src.f14");
    assert.equal(g.dst_440, 0x18181818, "0x440 = src.f18");
    assert.equal(g.dst_444, 0x1c1c1c1c, "0x444 = src.f1c");
    assert.equal(g.dst_463, 1, "byte 0x463 = 1");
    assert.equal(g.dst_448, 0x34, "byte 0x448 = low byte src.f23");
    assert.equal(g.dst_418, 0x50505050, "0x418 = src.f50");
    assert.equal(g.dst_44c, 0x40000000, "0x44c = src.f54");
    assert.equal(g.dst_e4_bits, 0x40000000, "0xe4 = f32(f54)*1.0 (X)");
    assert.equal(g.dst_e8_bits, 0x40000000, "0xe8 = f32(f54)*1.0 (Y)");
    assert.equal(g.dst_34, 0x3c3c3c3c, "0x34 = src.f3c");
    assert.equal(g.dst_434, 0x0c0c0c0c, "0x434 = src.f0c");
    assert.equal(g.store_380_v21, 0, "type 4 does NOT run the v21 store");
  }
  {
    /* WIDE byte drives: f23 low byte only; f60 0x180 -> low byte 0x80 =
       negative -> chain_fire 0. */
    const g = tailJL("tailType4WideBytes",
      { ...PACK_SRC, f23: 0x1020, f60: 0x180 }, 4, 1, 0x10, 0x50);
    assert.equal(g.dst_448, 0x20, "byte 0x448 = f23 & 0xff (wide drive)");
    assert.equal(g.chain_fire, 0, "f60 low byte 0x80 negative -> no chain");
    assert.equal(g.subcall_fire, 1, "this->f3c8 != 0 -> 0x4cf210 fires");
  }
  /* ---- CHAIN decisions: count = (Game[0x1baac]-Game[0x1baa8])>>2 SAR
     (u32 wrap); chain_arg = UNSIGNED edx<count ? edx : 0. ---- */
  {
    const g = tailJL("tailChainArgSmall",
      { ...PACK_SRC, f60: 0x03 }, 4, 0, 0x10, 0x50);
    assert.equal(g.chain_fire, 1, "f60 0x03 non-negative -> chain fires");
    assert.equal(g.chain_count, 0x10, "count = (0x50-0x10)>>2 = 0x10");
    assert.equal(g.chain_arg, 0x03, "edx 3 < 16 -> arg 3");
    const neg = tailJL("tailChainCountNegative",
      { ...PACK_SRC, f60: 0x05 }, 4, 0, 0x20, 0x10);
    assert.equal(neg.chain_count, 0xfffffffc,
      "diff -0x10 SAR -> 0xfffffffc (u32 wrap)");
    assert.equal(neg.chain_arg, 0x05,
      "UNSIGNED: u32(5) < u32(0xfffffffc) -> arg 5 (signed cmp would give 0)");
    const big = tailJL("tailChainArgBig",
      { ...PACK_SRC, f60: 0x7f }, 4, 0, 0x10, 0x50);
    assert.equal(big.chain_arg, 0, "edx 127 >= 16 (u32) -> push 0");
  }
  /* ---- SUB-CALL gate: [this+0x3c8] != 0 -> 0x4cf210 fires. ---- */
  {
    const g = tailJL("tailSubcallZero", PACK_SRC, 4, 0x0, 0, 0);
    assert.equal(g.subcall_fire, 0, "this->f3c8 == 0 -> no 0x4cf210");
    assert.equal(g.subcall_va, 0x004cf210, "subcall VA");
    assert.equal(g.subcall_this_off, 0x3cc, "0x4cf210 this = f3c8+0x3cc");
    assert.equal(g.chain_this_off, 0x3c8, "pre-call read off");
    assert.equal(g.chain_host_va, 0x00417870, "chain host A VA");
    assert.equal(g.chain_ret_va, 0x007ef921, "type-4 success ret");
    assert.equal(g.final_va, 0x004cdcf0, "final host VA");
  }
  /* ---- PATH C: type 0x11/0x38b -> DEFAULT (no 0x380 store, no lerp);
     other types -> dst 0x380 = src.f50; f18 SIGNED gate for 0x6d03e0. */
  {
    const g = tailJL("tailType11", { f50: 0x99999999, f18: 5, f34: 0 }, 0x11, 0, 0, 0);
    assert.equal(g.type11, 1, "type 0x11 classified");
    assert.equal(g.store_380, 0, "0x11 -> no 0x380 store");
    assert.equal(g.lerp_fire, 0, "0x11 -> no lerp");
    assert.equal(g.dst_380, 0x99999999, "dst field still reports src.f50");
    const t38 = tailJL("tailType38b", { f50: 1, f18: 5, f34: 0 }, 0x38b, 0, 0, 0);
    assert.equal(t38.type38b, 1, "type 0x38b classified");
    assert.equal(t38.store_380, 0, "0x38b -> no 0x380 store");
    const w11 = tailJL("tailType11Wide", { f50: 1, f18: 5, f34: 0 }, 0x111, 0, 0, 0);
    assert.equal(w11.type11, 0, "FULL dword: 0x111 != 0x11");
    assert.equal(w11.store_380, 1, "0x111 -> 0x380 store + tail");
    const w38b = tailJL("tailType38bWide", { f50: 1, f18: 5, f34: 0 }, 0x138b, 0, 0, 0);
    assert.equal(w38b.type38b, 0, "FULL dword: 0x138b != 0x38b");
  }
  {
    const g = tailJL("tailPathCStore",
      { f50: 0xaaaaaaaa, f18: 0xffffffff /* signed -1 */, f34: 0 }, 5, 0, 0, 0);
    assert.equal(g.path_c, 1, "type 5 -> path c");
    assert.equal(g.store_380, 1, "type 5 -> 0x380 store");
    assert.equal(g.dst_380, 0xaaaaaaaa, "0x380 = src.f50");
    assert.equal(g.call_6d03e0_fire, 0,
      "f18 = -1 (SIGNED js) -> skip 0x6d03e0");
    assert.equal(g.call_a10600_va, 0x00a10600, "a10600 host VA");
    assert.equal(g.call_a10600_arg, 0x00c7b640, "a10600 arg = pos-vec ptr");
    assert.equal(g.call_a10600_this_off, 0x28, "a10600 this = src.f28 off");
    const g2 = tailJL("tailPathCStorePos",
      { f50: 0x55555555, f18: 7, f34: 0xdeadbeef }, 5, 0, 0, 0);
    assert.equal(g2.call_6d03e0_fire, 1, "f18 7 >= 0 -> 0x6d03e0 fires");
    assert.equal(g2.call_6d03e0_arg, 7, "0x6d03e0 arg1 = f18");
    assert.equal(g2.call_6d03e0_arg2, 0xdeadbeef, "0x6d03e0 arg2 = src.f34");
    assert.equal(g2.gate_va, 0x006ac530, "path C gate host VA");
    assert.equal(g2.lerp_fire, 1, "type 5 -> lerp fires");
    assert.equal(g2.store_380_v21, 0, "type 5 does NOT run the v21 store");
    assert.equal(g2.call_812d00_va, 0x00812d00, "812d00 host VA");
    assert.equal(g2.call_813520_va, 0x00813520, "813520 host VA");
    assert.equal(g2.call_67f070_va, 0x0067f070, "67f070 host VA");
    assert.equal(g2.f80_bits, 0x42a00000, "0x812d00 imm arg = 80.0f");
    assert.equal(g2.head_va, 0x007ef817, "head VA");
    assert.equal(g2.default_va, 0x007efa3d, "default epilogue VA");
    assert.equal(g2.genrand_va, 0x006eef60, "genrand host VA");
    assert.equal(g2.scale20_va, 0x00baa87c, "lerp scale20 VA");
    assert.equal(g2.scale20_bits, 0x41a00000, "lerp scale20 = 20.0f");
    assert.equal(g2.scale2_va, 0x00ba9ff4, "lerp 2^-32 VA");
    assert.equal(g2.scale2_bits, 0x2f800000, "lerp 2^-32 bits");
    assert.equal(g2.sign_tbl_va, 0x00bacb00, "sign table VA");
    assert.equal(g2.game_global, 0x00c71678, "game global");
    assert.equal(g2.game_count_lo_off, 0x1baa8, "count lo off");
    assert.equal(g2.game_count_hi_off, 0x1baac, "count hi off");
  }

  /* ---- LERP (PE 0x7ef9b4..0x7efa09): unit = f32(u32)*2^-32; x =
     (unit*vec0)*20.0f + base_x -> 0x33c; y = (unit*vec1)*20.0f +
     base_y -> 0x340. ---- */
  const LERP_0 = {
    vec0_bits: 0x3f800000, /* 1.0 */
    vec1_bits: 0x40400000, /* 3.0 */
    base_x_bits: 0x40000000, /* 2.0 */
    base_y_bits: 0x40a00000, /* 5.0 */
  };
  {
    /* genrand 0x80000000 -> unit 0.5: x = 0.5*1*20 + 2 = 12.0;
       y = 0.5*3*20 + 5 = 35.0. */
    const g = lerpJL("lerpHalf", LERP_0, 0x80000000);
    assert.equal(v61F32(view, g.dst_33c_bits), 12.0,
      "x = 0.5*1.0*20 + 2 = 12");
    assert.equal(v61F32(view, g.dst_340_bits), 35.0,
      "y = 0.5*3.0*20 + 5 = 35");
    assert.equal(g.genrand_va, 0x006eef60, "lerp genrand VA");
    assert.equal(g.scale20_va, 0x00baa87c, "lerp scale20 VA");
    assert.equal(g.scale20_bits, 0x41a00000, "lerp scale20 20.0f");
    assert.equal(g.scale2_va, 0x00ba9ff4, "lerp 2^-32 VA");
    assert.equal(g.scale2_bits, 0x2f800000, "lerp 2^-32 bits");
    assert.equal(g.sign_tbl_va, 0x00bacb00, "lerp sign table VA");
    assert.equal(g.host_vec_va, 0x0067f070, "lerp host vec VA");
    assert.equal(g.lerp_va, 0x007ef9b4, "lerp VA");
  }
  {
    /* genrand 0xffffffff -> u32 4294967295 -> f32 2^32 -> unit 1.0:
       x = 1*1*20 + 2 = 22; y = 1*3*20 + 5 = 65. */
    const g = lerpJL("lerpMaxOnes", LERP_0, 0xffffffff);
    assert.equal(v61F32(view, g.dst_33c_bits), 22.0, "unit 1.0 -> x 22");
    assert.equal(v61F32(view, g.dst_340_bits), 65.0, "unit 1.0 -> y 65");
  }
  {
    /* Wide genrand 0x100/0x1ff round-trip via wasm<->JS lockstep. */
    const g = lerpJL("lerpWide", LERP_0, 0x100);
    assert.equal(g.dst_33c_bits, roomB15BindTailLerp(LERP_0, 0x100).dst_33c_bits >>> 0,
      "wasm lerp matches JS oracle for 0x100 genrand");
  }
});

test("room v61: dispatch-tail + lerp mutation discrimination", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s2) => (crlfFile ? s2.replace(/\n/g, "\r\n") : s2);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, label + ": mutant did not apply");
    writeSourceRetry(toFile(bad));
    let threw = false;
    try { check(); } catch { threw = true; }
    writeSourceRetry(original);
    assert.ok(threw, label + ": mutant survived every assertion");
  };
  const eq = (a, b, m) => { try { assert.equal(a, b, m); } catch { throw new Error(m); } };
  const callTail = (e, src, type28, f3c8, gl, gh) => {
    const view = new DataView(e.memory.buffer);
    const TSRC = MEM + 0x8b00, TOUT = MEM + 0x8b40;
    v61WriteTailSrc(view, TSRC, src);
    e.b15BindTailDispatch(TSRC, type28 >>> 0, f3c8 >>> 0, gl >>> 0,
                          gh >>> 0, TOUT);
    return v61ReadTailOut(view, TOUT);
  };
  const callLerp = (e, src, g) => {
    const view = new DataView(e.memory.buffer);
    const LSRC = MEM + 0x8b80, LOUT = MEM + 0x8bc0;
    v61WriteLerpSrc(view, LSRC, src);
    e.b15BindTailLerp(LSRC, g >>> 0, LOUT);
    return v61ReadLerpOut(view, LOUT);
  };
  try {
    /* (1) TYPE 21 GATE LOW-BYTE: (type_28 & 0xff)==0x21 would accept
       0x121. */
    withMutant("tail type21 gate low-byte",
      (s2) => s2.replace(
        "const int32_t type21 = (t == ISAAC_ROOM_B15_BIND_TAIL_TYPE_21) ? 1 : 0;",
        "const int32_t type21 = ((t & 0xff) == 0x21) ? 1 : 0;"),
      () => {
        const e = loadExports();
        const g = callTail(e, { f0c: 1 }, 0x121, 0, 0, 0);
        eq(g.type21, 0, "0x121 != 0x21 (FULL dword)");
        eq(g.path_c, 1, "0x121 -> path c");
      });
    /* (2) TYPE 124 DROPPED: path_a only checks 0x21. */
    withMutant("tail type124 dropped from path_a",
      (s2) => s2.replace(
        "const int32_t path_a = (type21 || type124) ? 1 : 0;",
        "const int32_t path_a = type21 ? 1 : 0;"),
      () => {
        const e = loadExports();
        const g = callTail(e, { f0c: 1 }, 0x124, 0, 0, 0);
        eq(g.path_a, 1, "0x124 -> path a");
        eq(g.type124, 1, "0x124 classified");
      });
    /* (3) CHAIN BYTE GATE UNSIGNED/INVERTED: 0xff treated as firing. */
    withMutant("tail chain byte gate inverted",
      (s2) => s2.replace(
        "const int32_t chain_fire = (f60_signed < 0) ? 0 : 1;",
        "const int32_t chain_fire = (f60_signed != 0) ? 1 : 0;"),
      () => {
        const e = loadExports();
        const g = callTail(e, { f60: 0xff }, 4, 0, 0, 0);
        eq(g.chain_fire, 0, "f60 0xff negative -> no chain");
      });
    /* (4) COUNT UNSIGNED SHIFT: (hi-lo)>>2 as LSR on negative diff. */
    withMutant("tail count unsigned shift",
      (s2) => s2.replace(
        "const int32_t count = diff >> 2;         /* SAR */",
        "const int32_t count = static_cast<int32_t>(\n        static_cast<uint32_t>(diff) >> 2); /* LSR mutant */"),
      () => {
        const e = loadExports();
        const g = callTail(e, { f60: 0x05 }, 4, 0, 0x20, 0x10);
        eq(g.chain_count, 0xfffffffc,
          "SAR of -0x10 -> 0xfffffffc (LSR would give 0x3ffffffc)");
      });
    /* (5) CHAIN ARG SIGNED COMPARE: edx < count signed. */
    withMutant("tail chain arg signed compare",
      (s2) => s2.replace(
        "(static_cast<uint32_t>(edx) < static_cast<uint32_t>(count)) ? edx : 0;",
        "(edx < count) ? edx : 0;"),
      () => {
        const e = loadExports();
        const g = callTail(e, { f60: 0x05 }, 4, 0, 0x20, 0x10);
        eq(g.chain_arg, 5,
          "UNSIGNED: u32(5) < u32(0xfffffffc) -> arg 5 (signed gives 0)");
      });
    /* (6) V21 U32->F32 SIGNED FALLBACK: 0xffffffff -> -1.0f not 2^32. */
    withMutant("tail v21 u32->f32 signed fallback",
      (s2) => s2.replace(
        "    const uint32_t u = src->f0c;\n    const int32_t as_signed = static_cast<int32_t>(u);\n    double d = static_cast<double>(as_signed);\n    if ((u >> 31) != 0u) {\n      d += 4294967296.0;\n    }",
        "    const uint32_t u = src->f0c;\n    const int32_t as_signed = static_cast<int32_t>(u);\n    double d = static_cast<double>(as_signed); /* NO +2^32 bias */"),
      () => {
        const e = loadExports();
        const g = callTail(e, { f0c: 0xffffffff }, 0x124, 0, 0, 0);
        eq(g.dst_380_v21_bits, 0x4f800000,
          "u32 0xffffffff -> f32 2^32 (0x4f800000), not -1.0f");
      });
    /* (7) LERP AXIS SWAP: x uses vec1 instead of vec0. */
    withMutant("tail lerp axis swap",
      (s2) => s2.replace(
        "const float x = (unit * v0) * scale20 + bx;",
        "const float x = (unit * v1) * scale20 + bx;   /* SWAP */"),
      () => {
        const e = loadExports();
        const g = callLerp(e, LERP_0, 0x80000000);
        eq(g.dst_33c_bits, 0x41400000,
          "x = 12.0 (0x41400000) uses vec0=1.0, not vec1=3.0");
      });
    /* (8) LERP 20.0f SCALE FOLDED to 1.0f: 0.5*1*20+2 = 12 -> 2.5. */
    withMutant("tail lerp scale20 folded",
      (s2) => s2.replace(
        "const float scale20 = __builtin_bit_cast(float, 0x41a00000u);",
        "const float scale20 = __builtin_bit_cast(float, 0x3f800000u); /* 1.0f */"),
      () => {
        const e = loadExports();
        const g = callLerp(e, LERP_0, 0x80000000);
        eq(g.dst_33c_bits, 0x41400000,
          "x = 12.0 (0x41400000) with 20.0f scale, not 2.5");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});

/* ---- ABI v62: FUN_007efa50 Room::Update-style body ---- */

/* v62 struct layouts (pack 1). */
const V62_HEAD_SRC_OFF = {
  f706c: 0, game_18304: 4, this4_40: 8, f11ec: 12, this4_44: 16,
  this4_4a: 20, this4_10_48: 24, this_f8: 28, greed1: 32, greed2: 36,
  game_18334: 40,
};
const V62_HEAD_OUT_OFF = {
  restock_fire: 0, restock_store_706c: 4, restock_host_va: 8,
  stage_early: 12, slot_early: 16, bomb_fire: 20,
  store_11ec: 24, store_44: 28, store_4a: 32,
  arg_bit10: 36, arg_word4a: 40, arg_10_48: 44, arg_f8: 48,
  call_9e5960_fire: 52, call_9e5960_va: 56, call_9e5960_this_off: 60,
  greed_va: 64, fire_9bb840: 68, call_9bb840_va: 72,
  call_9bb840_this_off: 76, fire_7fb250: 80, call_7fb250_va: 84,
  store_18368_fire: 88, dst_18368: 92, store_18368_src_off: 96,
  store_18368_dst_off: 100, call_571170_fire: 104, call_571170_va: 108,
  call_571170_this_off: 112, game_global: 116, game_18304_expect: 120,
  f706c_off: 124, f11ec_off: 128, n44_off: 132, n4a_off: 136,
  bomb_timer_max: 140, head_va: 144, ret_va: 148,
};
const V62_GRID_SRC_OFF = {
  src_array_ptr: 0, dst_ptr: 4, f0c: 8, f10: 12, garbage: 16,
};
const V62_GRID_OUT_OFF = {
  total: 0, iterations: 4, copies: 8, defaults: 12, stride: 16,
  src_off: 20, dst_off: 24, magic: 28, slot_size: 32, copy_src_off: 36,
  head_va: 40, ret_va: 44, grid_head_va: 48, grid_done_va: 52,
};
const V62_WALK_OUT_OFF = {
  path_a: 0, loop_fire: 4, continue_loop: 8, next_index: 12,
  type_gate: 16, subtype_gate: 20, list_off: 24, count_off: 28,
  stride: 32, magic16_0: 36, magic16_1: 40, magic16_2: 44, magic16_3: 48,
  pos_vec_va: 52, f60_bits: 56, f1_bits: 60, byte1: 64,
  host_7eeeb0_va: 68, vec_ctor_va: 72, vec_grow_va: 76, vec_stride: 80,
  vec_list_off: 84, vec_end_off: 88, vec_head_off: 92, vtable_slot: 96,
  global_a: 100, global_b: 104, entity_type_off: 108, entity_sub_off: 112,
  entity_f3c0_off: 116, head_va: 120, ret_va: 124,
};

function v62WriteHeadSrc(view, base, src) {
  for (const [k, off] of Object.entries(V62_HEAD_SRC_OFF)) {
    view.setInt32(base + off, (src[k] ?? 0) | 0, true);
  }
}
function v62ReadHeadOut(view, base) {
  const out = {};
  for (const [k, off] of Object.entries(V62_HEAD_OUT_OFF)) {
    out[k] = view.getUint32(base + off, true) >>> 0;
  }
  return out;
}
function v62WriteGridSrc(view, base, src) {
  for (const [k, off] of Object.entries(V62_GRID_SRC_OFF)) {
    if (k === "f0c" || k === "f10") {
      view.setInt32(base + off, (src[k] ?? 0) | 0, true);
    } else {
      view.setUint32(base + off, (src[k] ?? 0) >>> 0, true);
    }
  }
}
function v62ReadGridOut(view, base) {
  const out = {};
  for (const [k, off] of Object.entries(V62_GRID_OUT_OFF)) {
    out[k] = view.getUint32(base + off, true) >>> 0;
  }
  return out;
}
function v62ReadWalkOut(view, base) {
  const out = {};
  for (const [k, off] of Object.entries(V62_WALK_OUT_OFF)) {
    out[k] = view.getUint32(base + off, true) >>> 0;
  }
  return out;
}

/* Default slot bytes (PE 0x7efb9f..0x7efbe6): [0..16)=0 ; [16..20)=
   0x16a9de81 ; [20..24)=0 ; byte[24]=0 ; bytes[25..27]=garbage>>8..24 ;
   [28..32)=0x16a9de81. */
function v62DefaultSlot(garbage) {
  const b = new Uint8Array(32);
  b[16] = 0x81; b[17] = 0xde; b[18] = 0xa9; b[19] = 0x16;
  b[24] = 0;
  b[25] = (garbage >>> 8) & 0xff;
  b[26] = (garbage >>> 16) & 0xff;
  b[27] = (garbage >>> 24) & 0xff;
  b[28] = 0x81; b[29] = 0xde; b[30] = 0xa9; b[31] = 0x16;
  return b;
}

/* Independent PE-truth reference for the grid dst bytes: given srcFlags
   (array of 0/1 meaning src pointer zero/nonzero) this returns the dst
   bytes as the PE would lay them (the nonzero copy payload is supplied by
   the test via payloads; the law test compares wasm memory to the oracle
   for the default-only cases and to direct byte expectations for copies). */
function v62GridDstBytes(f0c, f10, garbage, srcFlags, payloads) {
  const total = Math.imul(f0c | 0, f10 | 0) | 0;
  const dst = new Uint8Array(total > 0 ? total * 32 : 0);
  for (let i = 0; i < total; i++) {
    const base = i * 32;
    if (srcFlags[i] === 1) {
      const p = payloads[i];
      dst.set(p.subarray(4, 36), base); /* copy [src+4..src+0x23] */
    } else {
      dst.set(v62DefaultSlot(garbage), base);
    }
  }
  return dst;
}

test("room v62: FUN_007efa50 head gates (PE 0x7efa7f..0x7efb66)", () => {
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.equal(ROOM_706C_HEAD_VA, 0x007efa50);
  assert.equal(ROOM_706C_HEAD_RET_VA, 0x007eff48);
  assert.equal(ROOM_706C_RESTOCK_HOST_VA, 0x008158a0);
  assert.equal(ROOM_706C_9E5960_VA, 0x009e5960);
  assert.equal(ROOM_706C_9E5960_THIS_OFF, 0x266e4);
  assert.equal(ROOM_706C_GREED_VA, 0x006f8120);
  assert.equal(ROOM_706C_9BB840_VA, 0x009bb840);
  assert.equal(ROOM_706C_9BB840_THIS_OFF, 0x1baa8);
  assert.equal(ROOM_706C_7FB250_VA, 0x007fb250);
  assert.equal(ROOM_706C_571170_VA, 0x00571170);
  assert.equal(ROOM_706C_571170_THIS_OFF, 0x74);
  assert.equal(ROOM_706C_GAME_GLOBAL, 0x00c71678);
  assert.equal(ROOM_706C_STAGE_EXPECT, -3);
  assert.equal(ROOM_706C_F706C_OFF, 0x706c);
  assert.equal(ROOM_706C_F11EC_OFF, 0x11ec);
  assert.equal(ROOM_706C_N44_OFF, 0x44);
  assert.equal(ROOM_706C_N4A_OFF, 0x4a);
  assert.equal(ROOM_706C_BOMB_TIMER_MAX, 7);

  const { memory, room706cHeadVa, room706cHeadRetVa,
          room706cHeadGates: wHeadGates } = loadExports();
  assert.equal(room706cHeadVa() >>> 0, 0x007efa50, "wasm head VA");
  assert.equal(room706cHeadRetVa() >>> 0, 0x007eff48, "wasm ret VA");

  const view = new DataView(memory.buffer);
  const HS = MEM + 0x8c00, HO = MEM + 0x8c40;
  const headJL = (label, src) => {
    const want = room706cHeadGates(src);
    v62WriteHeadSrc(view, HS, src);
    wHeadGates(HS, HO);
    const got = v62ReadHeadOut(view, HO);
    for (const k of Object.keys(V62_HEAD_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: head.${k}`);
    }
    return got;
  };

  {
    /* RESTOCK GATE: f706c SIGNED jle. 0xffffffff (-1) -> NO restock;
       2 -> fires, store 0xffffffff. */
    const g = headJL("restockNeg",
      { f706c: -1, game_18304: 0, this4_40: 1, f11ec: 1, this4_44: 0,
        this4_4a: 0, this4_10_48: 0, this_f8: 0, greed1: 0, greed2: 0,
        game_18334: 0x1234 });
    assert.equal(g.restock_fire, 0, "f706c -1 -> no restock (SIGNED)");
    assert.equal(g.restock_store_706c, 0, "no store when not firing");
  }
  {
    const g = headJL("restockPos",
      { f706c: 2, game_18304: 0, this4_40: 1, f11ec: 1, this4_44: 0,
        this4_4a: 0, this4_10_48: 0, this_f8: 0, greed1: 0, greed2: 0,
        game_18334: 0x1234 });
    assert.equal(g.restock_fire, 1, "f706c 2 -> restock");
    assert.equal(g.restock_store_706c, 0xffffffff, "store 0xffffffff");
    assert.equal(g.restock_host_va, 0x008158a0, "ShopRestockPartial");
  }
  {
    /* STAGE/SLOT: FULL-dword gates. game_18304 == -3 -> early;
       0x10000fd low byte 0xfd but NOT -3 -> NOT early. */
    const g = headJL("stageEarly",
      { f706c: 2, game_18304: -3, this4_40: 1, f11ec: 1, this4_44: 0,
        this4_4a: 0, this4_10_48: 0, this_f8: 0, greed1: 0, greed2: 0,
        game_18334: 0x1234 });
    assert.equal(g.stage_early, 1, "-3 full dword early");
    assert.equal(g.bomb_fire, 0, "early skips bomb block");
    assert.equal(g.call_571170_fire, 0, "early skips 0x571170");
  }
  {
    const g = headJL("stageLowByte",
      { f706c: 2, game_18304: 0x10000fd, this4_40: 1, f11ec: 1,
        this4_44: 0, this4_4a: 0, this4_10_48: 0, this_f8: 0,
        greed1: 0, greed2: 0, game_18334: 0x1234 });
    assert.equal(g.stage_early, 0, "0x10000fd != -3 (FULL dword)");
  }
  {
    const g = headJL("slotEarly",
      { f706c: 2, game_18304: 0, this4_40: 0, f11ec: 1, this4_44: 0,
        this4_4a: 0, this4_10_48: 0, this_f8: 0, greed1: 0, greed2: 0,
        game_18334: 0x1234 });
    assert.equal(g.slot_early, 1, "this4_40 0 early");
    assert.equal(g.bomb_fire, 0, "early skips bomb");
  }
  {
    /* BOMB TIMER: UNSIGNED ja; f11ec=0 -> (u32)(0-1)=0xffffffff > 7 ->
       NO fire; f11ec=8 -> 7 -> fire; f11ec=9 -> 8 -> no fire. */
    const g0 = headJL("bombZero",
      { f706c: 2, game_18304: 0, this4_40: 1, f11ec: 0, this4_44: 0,
        this4_4a: 0, this4_10_48: 0, this_f8: 0, greed1: 0, greed2: 0,
        game_18334: 0x1234 });
    assert.equal(g0.bomb_fire, 0, "f11ec 0 unsigned skip");
    const g8 = headJL("bombEight",
      { f706c: 2, game_18304: 0, this4_40: 1, f11ec: 8, this4_44: 0,
        this4_4a: 0, this4_10_48: 0, this_f8: 0, greed1: 0, greed2: 0,
        game_18334: 0x1234 });
    assert.equal(g8.bomb_fire, 1, "f11ec 8 fires");
    const g9 = headJL("bombNine",
      { f706c: 2, game_18304: 0, this4_40: 1, f11ec: 9, this4_44: 0,
        this4_4a: 0, this4_10_48: 0, this_f8: 0, greed1: 0, greed2: 0,
        game_18334: 0x1234 });
    assert.equal(g9.bomb_fire, 0, "f11ec 9 unsigned skip");
  }
  {
    /* BYTE BIT0 GATE: this4_44 = 1 -> skip; 0x101 (bit0 set) -> skip;
       0x100 (bit0 clear) -> fire, and the OR store is DWORD (0x101). */
    const g1 = headJL("bombBit0",
      { f706c: 2, game_18304: 0, this4_40: 1, f11ec: 1, this4_44: 1,
        this4_4a: 0, this4_10_48: 0, this_f8: 0, greed1: 0, greed2: 0,
        game_18334: 0x1234 });
    assert.equal(g1.bomb_fire, 0, "bit0 set skips bomb");
    const gw = headJL("bombWide",
      { f706c: 2, game_18304: 0, this4_40: 1, f11ec: 1, this4_44: 0x100,
        this4_4a: 0xffff, this4_10_48: 0x55, this_f8: 0, greed1: 0,
        greed2: 0, game_18334: 0x1234 });
    assert.equal(gw.bomb_fire, 1, "0x100 bit0 clear fires");
    assert.equal(gw.store_44, 0x101, "DWORD or store 0x100|1");
    assert.equal(gw.store_4a, 0, "WORD inc wrap 0xffff+1 -> 0");
    assert.equal(gw.arg_word4a, 0, "movzx zero-ext post-inc");
    assert.equal(gw.arg_bit10, 0, "bit10 of (0x101>>10) = 0");
    assert.equal(gw.arg_10_48, 0x55, "arg [this4_10+0x48]");
    assert.equal(gw.call_9e5960_fire, 1, "9e5960 fires");
    assert.equal(gw.call_9e5960_this_off, 0x266e4, "this Game+0x266e4");
  }
  {
    /* BIT10 post-or: this4_44 = 0x400 -> post-or 0x401 -> bit10 = 1. */
    const g = headJL("bombBit10",
      { f706c: 2, game_18304: 0, this4_40: 1, f11ec: 1, this4_44: 0x400,
        this4_4a: 2, this4_10_48: 0, this_f8: 0, greed1: 0, greed2: 0,
        game_18334: 0x1234 });
    assert.equal(g.bomb_fire, 1, "0x400 bit0 clear fires");
    assert.equal(g.arg_bit10, 1, "(0x401>>10)&1 = 1");
    assert.equal(g.store_44, 0x401, "post-or dword");
  }
  {
    /* GREED gates (INVERTED vs the store): fire_9bb840 iff greed1==0 ||
       this_f8!=1; store_18368 iff greed2!=0 && this_f8==1. */
    const g = headJL("greedBoth",
      { f706c: 2, game_18304: 0, this4_40: 1, f11ec: 1, this4_44: 0,
        this4_4a: 0, this4_10_48: 0, this_f8: 1, greed1: 1, greed2: 1,
        game_18334: 0xabcdef });
    assert.equal(g.fire_9bb840, 0, "greed1!=0 && f8==1 -> no 9bb840");
    assert.equal(g.store_18368_fire, 1, "greed2!=0 && f8==1 -> store");
    assert.equal(g.dst_18368, 0xabcdef, "dst = [Game+0x18334]");
    assert.equal(g.store_18368_src_off, 0x18334, "src off");
    assert.equal(g.store_18368_dst_off, 0x18368, "dst off");
    const g2 = headJL("greedFire",
      { f706c: 2, game_18304: 0, this4_40: 1, f11ec: 1, this4_44: 0,
        this4_4a: 0, this4_10_48: 0, this_f8: 0, greed1: 0, greed2: 0,
        game_18334: 0x1 });
    assert.equal(g2.fire_9bb840, 1, "greed1==0 -> 9bb840 fires");
    assert.equal(g2.store_18368_fire, 0, "greed2==0 -> no store");
  }
  {
    /* 0x571170 fires whenever stage/slot pass (bomb skip included). */
    const g = headJL("bombSkipStill571170",
      { f706c: 2, game_18304: 0, this4_40: 1, f11ec: 0, this4_44: 0,
        this4_4a: 0, this4_10_48: 0, this_f8: 0, greed1: 0, greed2: 0,
        game_18334: 0x1234 });
    assert.equal(g.bomb_fire, 0, "bomb skipped");
    assert.equal(g.call_571170_fire, 1, "571170 still fires");
    assert.equal(g.call_571170_this_off, 0x74, "this4+0x74");
  }
});

test("room v62: FUN_007efa50 grid copy (PE 0x7efb66..0x7efbfd)", () => {
  const { memory, room706cGridCopy: wGridCopy } = loadExports();
  const view = new DataView(memory.buffer);
  const GSRC = MEM + 0x8c80, GOUT = MEM + 0x8cc0;
  const SRCARR = MEM + 0x8d00; /* 8 dwords of src pointers */
  const SRCBUF = MEM + 0x8d40; /* 8 * 36-byte payload buffers */
  const DST = MEM + 0x8f40;    /* total*32 dst bytes */

  /* helper: fill src array + payloads; srcFlags[i]=1 -> payload pointer
     with bytes payload[i] opened at +0..+35; slot data at +4..+0x23. */
  const setupGrid = (srcFlags, payloads) => {
    for (let i = 0; i < 8; i++) {
      if (srcFlags[i] === 1) {
        const p = payloads[i];
        const buf = SRCBUF + i * 36;
        view.setUint32(SRCARR + i * 4, buf, true);
        for (let k = 0; k < 36; k++) {
          view.setUint8(buf + k, p[k]);
        }
      } else {
        view.setUint32(SRCARR + i * 4, 0, true);
      }
    }
  };
  const gridJL = (label, src, srcFlags, payloads) => {
    const want = room706cGridCopy(src.f0c, src.f10, src.garbage, srcFlags);
    setupGrid(srcFlags, payloads);
    v62WriteGridSrc(view, GSRC, src);
    wGridCopy(GSRC, GOUT);
    const got = v62ReadGridOut(view, GOUT);
    for (const k of Object.keys(V62_GRID_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: grid.${k}`);
    }
    /* dst bytes: PE-truth reference (the JS oracle cannot deref wasm
       memory, so the copy payloads are supplied by the test — identical
       to what was written at the src pointers). */
    const wantBytes =
      v62GridDstBytes(src.f0c, src.f10, src.garbage, srcFlags, payloads);
    for (let i = 0; i < wantBytes.length; i++) {
      assert.equal(view.getUint8(DST + i), wantBytes[i],
        `${label}: dst byte ${i}`);
    }
    return got;
  };

  const PAY = [];
  for (let i = 0; i < 8; i++) {
    const p = new Uint8Array(36);
    for (let k = 0; k < 36; k++) p[k] = 0x40 + i * 8 + k;
    PAY.push(p);
  }

  {
    /* total 0 -> skipped. */
    const g = gridJL("gridZero", { src_array_ptr: SRCARR, dst_ptr: DST,
      f0c: 0, f10: 5, garbage: 0x11223344 }, [0, 0, 0, 0, 0, 0, 0, 0], PAY);
    assert.equal(g.total, 0, "total 0");
    assert.equal(g.iterations, 0, "no iterations");
  }
  {
    /* total = -2 (SIGNED imul wrap: 0x7ffffffe negative? no: 2 * -1) ->
       jle skips. */
    const g = gridJL("gridNeg", { src_array_ptr: SRCARR, dst_ptr: DST,
      f0c: 2, f10: -1, garbage: 0x11223344 }, [0, 0, 0, 0, 0, 0, 0, 0], PAY);
    assert.equal(g.total, 0xfffffffe, "signed imul wrap -2");
    assert.equal(g.iterations, 0, "negative total jle skip");
  }
  {
    /* total = 2: [ptr, 0] -> copy + default; default slot bytes. */
    const g = gridJL("gridTwo", { src_array_ptr: SRCARR, dst_ptr: DST,
      f0c: 2, f10: 1, garbage: 0x11223344 }, [1, 0, 0, 0, 0, 0, 0, 0], PAY);
    assert.equal(g.total, 2, "total 2");
    assert.equal(g.iterations, 2, "two iterations");
    assert.equal(g.copies, 1, "one copy");
    assert.equal(g.defaults, 1, "one default");
    /* dst[0..31] = PAY[0].subarray(4,36); dst[32..63] = default. */
    for (let k = 0; k < 32; k++) {
      assert.equal(view.getUint8(DST + k), PAY[0][4 + k], "copy byte");
    }
    const dflt = v62DefaultSlot(0x11223344);
    for (let k = 0; k < 32; k++) {
      assert.equal(view.getUint8(DST + 32 + k), dflt[k], "default byte");
    }
    assert.equal(view.getUint8(DST + 57), 0x33, "garbage bits 8..15");
    assert.equal(view.getUint8(DST + 59), 0x11, "garbage bits 24..31");
  }
  {
    /* 32-bit signed wrap: f0c=0x8000, f10=0x10000 -> 0x80000000
       (negative) -> skip; also f0c=-1, f10=1 -> -1 -> skip. */
    const g = gridJL("gridWrap", { src_array_ptr: SRCARR, dst_ptr: DST,
      f0c: 0x8000, f10: 0x10000, garbage: 0 }, [0, 0, 0, 0, 0, 0, 0, 0], PAY);
    assert.equal(g.total, 0x80000000, "imul wrap 0x80000000");
    assert.equal(g.iterations, 0, "negative wrap skips");
  }
  {
    /* stride consts. */
    const g = gridJL("gridConsts", { src_array_ptr: SRCARR, dst_ptr: DST,
      f0c: 1, f10: 1, garbage: 0 }, [0, 0, 0, 0, 0, 0, 0, 0], PAY);
    assert.equal(g.stride, 0x20, "stride 0x20");
    assert.equal(g.src_off, 0x24, "src off 0x24");
    assert.equal(g.dst_off, 0x68, "dst off 0x68");
    assert.equal(g.magic, 0x16a9de81, "magic");
    assert.equal(g.copy_src_off, 4, "copy src off 4");
    assert.equal(g.grid_head_va, 0x007efb66, "grid head");
    assert.equal(g.grid_done_va, 0x007efbfd, "grid done");
  }
});

test("room v62: FUN_007efa50 entity walk step (PE 0x7efbfd..0x7efc10, "
     + "0x7efcba..0x7efcd0, 0x7eff1e..0x7eff32)", () => {
  const { memory, room706cWalkStep: wWalkStep } = loadExports();
  const view = new DataView(memory.buffer);
  const WO = MEM + 0x8f80;
  const walkJL = (label, count, index, type28, subtype2c) => {
    const want = room706cWalkStep(count, index, type28, subtype2c);
    wWalkStep(count >>> 0, index >>> 0, type28 >>> 0,
              subtype2c >>> 0, WO);
    const got = v62ReadWalkOut(view, WO);
    for (const k of Object.keys(V62_WALK_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: walk.${k}`);
    }
    return got;
  };
  {
    /* count 0 -> jbe skips loop fire; path_a FULL dword 0x3c5/0. */
    const g = walkJL("walkZero", 0, 0, 0x3c5, 0);
    assert.equal(g.loop_fire, 0, "count 0 no loop");
    assert.equal(g.path_a, 1, "0x3c5/0 path a");
  }
  {
    /* count 0xffffffff (UNSIGNED jbe vs 0) -> fires. */
    const g = walkJL("walkHuge", 0xffffffff, 0, 0x2c5, 0);
    assert.equal(g.loop_fire, 1, "count 0xffffffff fires (UNSIGNED)");
    assert.equal(g.path_a, 0, "0x2c5 != 0x3c5 FULL dword");
  }
  {
    /* type low byte 0xc5 (0x2c5) must NOT match 0x3c5 (FULL dword). */
    const g = walkJL("walkLowByte", 3, 0, 0x2c5, 0);
    assert.equal(g.path_a, 0, "0x2c5 low byte 0xc5 but != 0x3c5");
  }
  {
    /* subtype must be 0 FULL dword: 0x100 != 0 -> no path a. */
    const g = walkJL("walkSub", 3, 0, 0x3c5, 0x100);
    assert.equal(g.path_a, 0, "subtype 0x100 != 0");
  }
  {
    /* next_index wrap + UNSIGNED jb continue. */
    const g = walkJL("walkWrap", 3, 0xfffffffe, 0x3c5, 0);
    assert.equal(g.next_index, 0xffffffff, "inc wrap");
    assert.equal(g.continue_loop, 0, "0xffffffff < 3 false (UNSIGNED)");
    const g2 = walkJL("walkContinue", 3, 1, 0x3c5, 0);
    assert.equal(g2.continue_loop, 1, "2 < 3");
    assert.equal(g2.next_index, 2, "next 2");
  }
  {
    /* const annotations. */
    const g = walkJL("walkConsts", 1, 0, 0x3c5, 0);
    assert.equal(g.type_gate, 0x3c5, "type gate");
    assert.equal(g.subtype_gate, 0, "sub gate");
    assert.equal(g.list_off, 0x125c, "list off");
    assert.equal(g.count_off, 0x1264, "count off");
    assert.equal(g.stride, 4, "stride");
    assert.equal(g.magic16_2, 0xffffffff, "magic16");
    assert.equal(g.magic16_3, 0xffffffff, "magic16");
    assert.equal(g.pos_vec_va, 0x00c7b640, "pos vec");
    assert.equal(g.f60_bits, 0x42700000, "60.0f");
    assert.equal(g.f1_bits, 0x3f800000, "1.0f");
    assert.equal(g.byte1, 1, "byte1");
    assert.equal(g.host_7eeeb0_va, 0x007eeeb0, "7eeeb0");
    assert.equal(g.vec_ctor_va, 0x004d3130, "ctor");
    assert.equal(g.vec_grow_va, 0x004d7530, "grow");
    assert.equal(g.vec_stride, 0x78, "vec stride");
    assert.equal(g.vtable_slot, 0xc, "vtable slot");
    assert.equal(g.global_a, 0x00c7e84c, "global a");
    assert.equal(g.global_b, 0x00c7e850, "global b");
    assert.equal(g.entity_type_off, 0x28, "type off");
    assert.equal(g.entity_sub_off, 0x2c, "sub off");
    assert.equal(g.entity_f3c0_off, 0x3c0, "f3c0 off");
    assert.equal(g.head_va, 0x007efa50, "head");
    assert.equal(g.ret_va, 0x007eff48, "ret");
  }
});

test("room v62: FUN_007efa50 head/grid/walk mutation discrimination", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s2) => (crlfFile ? s2.replace(/\n/g, "\r\n") : s2);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, label + ": mutant did not apply");
    writeSourceRetry(toFile(bad));
    let threw = false;
    try { check(); } catch { threw = true; }
    writeSourceRetry(original);
    assert.ok(threw, label + ": mutant survived every assertion");
  };
  const eq = (a, b, m) => { try { assert.equal(a, b, m); } catch { throw new Error(m); } };

  const HSRC = () => {
    const e = loadExports();
    const view = new DataView(e.memory.buffer);
    return { e, view, s: MEM + 0x9000, o: MEM + 0x9040 };
  };
  const callHead = (h, src) => {
    v62WriteHeadSrc(h.view, h.s, src);
    h.e.room706cHeadGates(h.s, h.o);
    return v62ReadHeadOut(h.view, h.o);
  };
  const H0 = { f706c: 2, game_18304: 0, this4_40: 1, f11ec: 1, this4_44: 0,
    this4_4a: 0, this4_10_48: 0, this_f8: 0, greed1: 0, greed2: 0,
    game_18334: 0x1234 };

  try {
    /* (1) RESTOCK GATE UNSIGNED: jle -> jbe accepts 0xffffffff. */
    withMutant("706c restock gate unsigned",
      (s2) => s2.replace(
        "const int32_t restock_fire = (src->f706c > 0) ? 1 : 0;",
        "const int32_t restock_fire =\n        (static_cast<uint32_t>(src->f706c) > 0u) ? 1 : 0;"),
      () => {
        const h = HSRC();
        const g = callHead(h, { ...H0, f706c: -1 });
        eq(g.restock_fire, 0, "f706c -1 -> NO restock (SIGNED)");
      });
    /* (2) BOMB TIMER SIGNED ja: (u32)(f11ec-1) > 7 vs signed -1 < 7. */
    withMutant("706c bomb timer signed ja",
      (s2) => s2.replace(
        "const uint32_t timer_minus_1 = src->f11ec - 1u;",
        "const int32_t timer_minus_1 =\n        static_cast<int32_t>(src->f11ec) - 1;"),
      () => {
        const h = HSRC();
        const g = callHead(h, { ...H0, f11ec: 0 });
        eq(g.bomb_fire, 0, "f11ec 0 -> unsigned skip (u32 0xffffffff > 7)");
      });
    /* (3) BYTE BIT0 GATE DROPPED: fire even when bit0 set. */
    withMutant("706c bomb byte gate dropped",
      (s2) => s2.replace(
        "(src->this4_44 & 1u) == 0u) ? 1u : 0u;",
        "1u) ? 1u : 0u; /* bit0 gate dropped */"),
      () => {
        const h = HSRC();
        const g = callHead(h, { ...H0, this4_44: 1 });
        eq(g.bomb_fire, 0, "byte bit0 set -> skip bomb");
      });
    /* (4) WORD INC FULL DWORD: this4_4a 0xffff -> 0x10000. */
    withMutant("706c word inc full dword",
      (s2) => s2.replace(
        "out->store_4a = static_cast<uint32_t>(\n          static_cast<uint16_t>(src->this4_4a + 1u));",
        "out->store_4a = src->this4_4a + 1u; /* full dword */"),
      () => {
        const h = HSRC();
        const g = callHead(h, { ...H0, this4_4a: 0xffff });
        eq(g.store_4a, 0, "WORD inc wrap 0xffff+1 -> 0");
      });
    /* (5) ARG BIT10 SHIFT POSITION: bit10 of the POST-or dword
        (post44 = this4_44|1); a >>9 mutant reads bit9. Drive this4_44=
        0x400 -> post44=0x401 -> (0x401>>10)&1 = 1. */
    withMutant("706c arg bit10 shift off by one",
      (s2) => s2.replace(
        "out->arg_bit10 = (post44 >> 0xa) & 1u;",
        "out->arg_bit10 = (post44 >> 0x9) & 1u; /* bit9 mutant */"),
      () => {
        const h = HSRC();
        const g = callHead(h, { ...H0, this4_44: 0x400 });
        eq(g.arg_bit10, 1, "(0x401>>10)&1 = 1 (bit10, not bit9)");
      });
    /* (6) 9BB840 GATE EQUAL-ANDED: requires greed1!=0 && f8==1. */
    withMutant("706c 9bb840 gate equal-anded",
      (s2) => s2.replace(
        "out->fire_9bb840 =\n          (src->greed1 == 0u || src->this_f8 != 1u) ? 1u : 0u;",
        "out->fire_9bb840 =\n          (src->greed1 != 0u && src->this_f8 == 1u) ? 1u : 0u;"),
      () => {
        const h = HSRC();
        const g = callHead(h, { ...H0, this_f8: 2, greed1: 0 });
        eq(g.fire_9bb840, 1, "greed1==0 -> 9bb840 fires");
      });
    /* (7) GRID MAGIC: default slot magic 0x16a9de81 -> 0x16a9de80. */
    withMutant("706c grid default magic",
      (s2) => s2.replace(
        "uint32_t low = ISAAC_ROOM_706C_GRID_MAGIC;\n        for (uint32_t k = 0u; k < 4u; ++k) {\n          slot_dst[16u + k] = static_cast<uint8_t>(low & 0xffu);\n          low >>= 8;\n        }",
        "uint32_t low = ISAAC_ROOM_706C_GRID_MAGIC - 1u;\n        for (uint32_t k = 0u; k < 4u; ++k) {\n          slot_dst[16u + k] = static_cast<uint8_t>(low & 0xffu);\n          low >>= 8;\n        }"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const GSRC = MEM + 0x9080, GOUT = MEM + 0x90c0;
        const SRCARR = MEM + 0x9100, DST = MEM + 0x9200;
        for (let i = 0; i < 4; i++) view.setUint32(SRCARR + i * 4, 0, true);
        v62WriteGridSrc(view, GSRC, { src_array_ptr: SRCARR, dst_ptr: DST,
          f0c: 1, f10: 1, garbage: 0 });
        e.room706cGridCopy(GSRC, GOUT);
        eq(view.getUint8(DST + 16), 0x81, "default slot magic byte 0");
      });
    /* (8) GRID GARBAGE LOW BYTE: bytes[25..27] from garbage low byte. */
    withMutant("706c grid garbage low byte",
      (s2) => s2.replace(
        "slot_dst[25u] = static_cast<uint8_t>((g >> 8) & 0xffu);",
        "slot_dst[25u] = static_cast<uint8_t>(g & 0xffu);"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const GSRC = MEM + 0x9240, GOUT = MEM + 0x9280;
        const SRCARR = MEM + 0x92c0, DST = MEM + 0x93c0;
        for (let i = 0; i < 4; i++) view.setUint32(SRCARR + i * 4, 0, true);
        v62WriteGridSrc(view, GSRC, { src_array_ptr: SRCARR, dst_ptr: DST,
          f0c: 1, f10: 1, garbage: 0x11223344 });
        e.room706cGridCopy(GSRC, GOUT);
        eq(view.getUint8(DST + 25), 0x33, "garbage bits 8..15 (0x33), not low byte");
      });
    /* (9) WALK TYPE GATE LOW-BYTE: (type & 0xff) == 0xc5 accepts 0x2c5. */
    withMutant("706c walk type gate low-byte",
      (s2) => s2.replace(
        "(static_cast<int32_t>(type_28) == ISAAC_ROOM_706C_WALK_TYPE_GATE &&",
        "((type_28 & 0xffu) == 0xc5u &&"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const WO = MEM + 0x9400;
        e.room706cWalkStep(1, 0, 0x2c5, 0, WO);
        eq(view.getUint32(WO + 0, true), 0, "0x2c5 != 0x3c5 (FULL dword)");
      });
    /* (10) WALK LOOP GATE SIGNED: count 0xffffffff (-1) jle skips. */
    withMutant("706c walk loop gate signed",
      (s2) => s2.replace(
        "out->loop_fire = (count != 0u) ? 1u : 0u;",
        "out->loop_fire = (static_cast<int32_t>(count) > 0) ? 1u : 0u;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const WO = MEM + 0x9440;
        e.room706cWalkStep(0xffffffff, 0, 0, 0, WO);
        eq(view.getUint32(WO + 4, true), 1, "count 0xffffffff fires (UNSIGNED)");
      });
    /* (11) WALK CONTINUE SIGNED: next < count signed. */
    withMutant("706c walk continue signed",
      (s2) => s2.replace(
        "out->continue_loop = (next < count) ? 1u : 0u;",
        "out->continue_loop =\n        (static_cast<int32_t>(next) < static_cast<int32_t>(count)) ? 1u : 0u;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const WO = MEM + 0x9480;
        e.room706cWalkStep(3, 0xfffffffe, 0, 0, WO);
        eq(view.getUint32(WO + 8, true), 0, "0xffffffff < 3 false UNSIGNED");
      });
    /* (12) GRID COPY SOURCE OFFSET: PE copies [src+4..src+0x23], NOT
        [src+0..0x1f] (rent +4 slot header). */
    withMutant("706c grid copy src offset",
      (s2) => s2.replace(
        "const uint8_t* cs = reinterpret_cast<const uint8_t*>(src_ptr + 4u);",
        "const uint8_t* cs = reinterpret_cast<const uint8_t*>(src_ptr);"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        const GSRC = MEM + 0x94c0, GOUT = MEM + 0x9500;
        const SRCARR = MEM + 0x9540, SRCBUF = MEM + 0x9580;
        const DST = MEM + 0x9600;
        view.setUint32(SRCARR, SRCBUF, true);
        for (let k = 0; k < 36; k++) view.setUint8(SRCBUF + k, k);
        for (let i = 1; i < 4; i++) view.setUint32(SRCARR + i * 4, 0, true);
        v62WriteGridSrc(view, GSRC, { src_array_ptr: SRCARR, dst_ptr: DST,
          f0c: 1, f10: 1, garbage: 0 });
        e.room706cGridCopy(GSRC, GOUT);
        eq(view.getUint8(DST + 0), 4, "copy starts at [src+4] (byte 4)");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});

/* ---- ABI v63: FUN_007eff50 Room::RestoreState ---- */

/* v63 struct layouts (pack 1). */
const V63_CNT_OUT_OFF = {
  entry_store: 0, exit_store: 4, exit_early_store: 8, global_va: 12,
  head_va: 16, ret_va: 20, ret_early_va: 24,
};
const V63_L1_SRC_OFF = {
  cur_ptr: 0, end_ptr: 4, cur_f0: 8, cur_f4: 12, cur_f8: 16,
  cur_f34: 20, cur_f80: 24, cur_fac: 28, cur_f50_bits: 32, cur_w20: 36,
  next_f0: 40, next_f4: 44, room_f0c: 48, cos_r_bits: 52, sin_r_bits: 56,
};
const V63_L1_OUT_OFF = {
  path_a: 0, continue_loop: 4, next_ptr: 8, saved_ptr: 12,
  create_host_va: 16, create_this_va: 20, create_a1: 24, create_a2: 28,
  create_a3: 32, create_a4: 36, create_a5: 40, create_a6: 44,
  create_a7: 48, create_a8: 52, bind_host_va: 56, bind_arg1_fire: 60,
  bind_arg2: 64, local_a_bits: 68, quot: 72, rem: 76, local_d_bits: 80,
  local_e_bits: 84, minecart_va: 88, minecart_this_passthru: 92,
  pos_ptr_off: 96, vel_ptr_off: 100, cos_va: 104, sin_va: 108,
  cos_r_bits: 112, sin_r_bits: 116, stride: 120, type_gate: 124,
  sub_gate: 128, deg2rad_bits: 132, f40_bits: 136, f120_bits: 140,
  head_va: 144, ret_va: 148,
};
const V63_L2_OUT_OFF = {
  dtor_count: 0, store_end: 4, dtor_host_va: 8, stride: 12, head_va: 16,
};
const V63_GATES_OUT_OFF = {
  fire: 0, f4_0_expect: 4, game_0_expect: 8, f4_44_off: 12, byte_bit: 16,
  early_ret_va: 20, head_va: 24, ret_va: 28, grid_head_va: 32,
  grid_done_va: 36,
};
const V63_LOOP8_OUT_OFF = {
  continue_loop: 0, host_va: 4, arg: 8, count: 12,
};
const V63_GRID_SRC_OFF = {
  cols: 0, rows: 4, i: 8, j: 12, src_ptr: 16, src_f4: 20, src_f24: 24,
  dst_ptr: 28, dst_f4: 32,
};
const V63_GRID_OUT_OFF = {
  outer_fire: 0, inner_fire: 4, index: 8, index_ok: 12, i_ok: 16,
  j_ok: 20, src_ok: 24, src_type_ok: 28, target: 32, target_ok: 36,
  dst_ok: 40, dst_type_ok: 44, fire: 48, store_76c_value: 52,
  indirect_fire: 56, indirect_arg: 60, vtable_slot: 64, continue_j: 68,
  continue_i: 72, grid_base_off: 76, cell_stride: 80, type_gate: 84,
  target_max: 88, f76c_off: 92, head_va: 96, ret_va: 100,
};

function v63WriteL1Src(view, base, s) {
  for (const [k, off] of Object.entries(V63_L1_SRC_OFF)) {
    if (k === "room_f0c") view.setInt32(base + off, (s[k] ?? 0) | 0, true);
    else view.setUint32(base + off, (s[k] ?? 0) >>> 0, true);
  }
}
function v63ReadOut(view, base, offmap) {
  const out = {};
  for (const [k, off] of Object.entries(offmap)) {
    out[k] = view.getUint32(base + off, true) >>> 0;
  }
  return out;
}
function v63WriteGridSrc(view, base, s) {
  for (const [k, off] of Object.entries(V63_GRID_SRC_OFF)) {
    if (["cols", "rows", "i", "j"].includes(k)) {
      view.setInt32(base + off, (s[k] ?? 0) | 0, true);
    } else {
      view.setUint32(base + off, (s[k] ?? 0) >>> 0, true);
    }
  }
}

test("room v63: Room::RestoreState counter guard + loop8 (PE 0x7eff50.."
     + "0x7eff6c, 0x7f018d..0x7f019e)", () => {
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.equal(ROOM_RESTORE_VA, 0x007eff50);
  assert.equal(ROOM_RESTORE_RET_VA, 0x007f01aa);
  assert.equal(ROOM_RESTORE_RET_EARLY_VA, 0x007f01b8);
  assert.equal(ROOM_RESTORE_NEXT_VA, 0x007f01c0);
  assert.equal(ROOM_RESTORE_COUNTER_GLOBAL_VA, 0x00c71674);

  const { memory, restoreVa, restoreRetVa, restoreCounters: wCnt,
          restoreLoop8Step: wL8 } = loadExports();
  assert.equal(restoreVa() >>> 0, 0x007eff50, "wasm restore VA");
  assert.equal(restoreRetVa() >>> 0, 0x007f01aa, "wasm ret VA");
  const view = new DataView(memory.buffer);
  const C = MEM + 0xa000;

  const cntJL = (label, counterIn) => {
    const want = roomRestoreCounters(counterIn);
    wCnt(counterIn >>> 0, C);
    const got = v63ReadOut(view, C, V63_CNT_OUT_OFF);
    for (const k of Object.keys(V63_CNT_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: cnt.${k}`);
    }
    return got;
  };
  {
    const g = cntJL("cntPlain", 5);
    assert.equal(g.entry_store, 6, "entry c+1");
    assert.equal(g.exit_store, 5, "normal exit restores c");
    assert.equal(g.exit_early_store, 5, "early exit restores c");
    assert.equal(g.global_va, 0x00c71674, "counter global");
  }
  {
    /* u32 wrap: 0xffffffff + 1 -> 0. */
    const g = cntJL("cntWrap", 0xffffffff);
    assert.equal(g.entry_store, 0, "entry wrap to 0");
    assert.equal(g.exit_store, 0xffffffff, "exit restores original");
  }
  {
    /* counters at 0. */
    const g = cntJL("cntZero", 0);
    assert.equal(g.entry_store, 1, "0+1");
    assert.equal(g.ret_va, 0x007f01aa, "normal ret");
    assert.equal(g.ret_early_va, 0x007f01b8, "early ret");
    assert.equal(g.head_va, 0x007eff50, "head");
  }

  /* LOOP8: k=0..7 host 0x8167e0(this=room, arg=k); UNSIGNED jb. */
  const L8 = MEM + 0xa040;
  const l8JL = (label, k) => {
    const want = roomRestoreLoop8Step(k);
    wL8(k >>> 0, L8);
    const got = v63ReadOut(view, L8, V63_LOOP8_OUT_OFF);
    for (const kk of Object.keys(V63_LOOP8_OUT_OFF)) {
      assert.equal(got[kk], want[kk] >>> 0, `${label}: l8.${kk}`);
    }
    return got;
  };
  {
    const g = l8JL("l8first", 0);
    assert.equal(g.continue_loop, 1, "k0: 1 < 8");
    assert.equal(g.arg, 0, "arg k");
    const g7 = l8JL("l8last", 7);
    assert.equal(g7.continue_loop, 0, "k7: 8 < 8 false");
    assert.equal(g7.host_va, 0x008167e0, "host");
    assert.equal(g7.count, 8, "8 iterations");
  }
});

test("room v63: Room::RestoreState list1 walk step (PE 0x7eff76.."
     + "0x7f00b4)", () => {
  assert.equal(ROOM_RESTORE_WALK_TYPE_GATE, 0x3c5);
  assert.equal(ROOM_RESTORE_CREATE_HOST_VA, 0x006fe410);
  assert.equal(ROOM_RESTORE_BIND_HOST_VA, 0x007ef420);
  assert.equal(ROOM_RESTORE_MINECART_HOST_VA, 0x006b7be0);
  assert.equal(ROOM_RESTORE_COS_HOST_VA, 0x0041d540);
  assert.equal(ROOM_RESTORE_SIN_HOST_VA, 0x0041d520);
  /* 0xbaa088 PE bytes = 0x3c8efa35 = deg2rad (NOT 22.5f). */
  assert.equal(ROOM_RESTORE_DEG2RAD_BITS, 0x3c8efa35);
  assert.equal(ROOM_RESTORE_DEG2RAD_VA, 0x00baa088);
  assert.equal(ROOM_RESTORE_F40_BITS, 0x42200000);
  assert.equal(ROOM_RESTORE_F120_BITS, 0x42f00000);
  assert.equal(ROOM_RESTORE_LIST_STRIDE, 0x78);

  const { memory, restoreList1Step: wL1 } = loadExports();
  const view = new DataView(memory.buffer);
  const S = MEM + 0xa080, O = MEM + 0xa0c0;
  const l1JL = (label, src) => {
    const want = roomRestoreList1Step(src);
    v63WriteL1Src(view, S, src);
    wL1(S, O);
    const got = v63ReadOut(view, O, V63_L1_OUT_OFF);
    for (const k of Object.keys(V63_L1_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: l1.${k}`);
    }
    return got;
  };

  {
    /* PATH_B: cur.f0 != 0x3c5. cur=0x1000 end=0x1000+3*0x78 (3 elems);
       k=0 -> continue (next 0x1078 != end). Create args from the
       CURRENT element; no float section. */
    const g = l1JL("l1PathB",
      { cur_ptr: 0x1000, end_ptr: 0x1168, cur_f0: 0x12, cur_f4: 1,
        cur_f8: 0x21, cur_f34: 0x43, cur_f80: 0x81, cur_fac: 0xac1,
        cur_f50_bits: 0x40400000, cur_w20: 0x80, next_f0: 0x999,
        next_f4: 0xaaa, room_f0c: 8, cos_r_bits: 0x11223344,
        sin_r_bits: 0x55667788 });
    assert.equal(g.path_a, 0, "not path a");
    assert.equal(g.continue_loop, 1, "next != end");
    assert.equal(g.next_ptr, 0x1078, "cur + 0x78");
    assert.equal(g.saved_ptr, 0x1028, "cur + 0x28");
    assert.equal(g.create_a1, 0x12, "B a1 = cur.f0");
    assert.equal(g.create_a2, 1, "B a2 = cur.f4");
    assert.equal(g.create_a3, 0x1028, "B a3 = cur+0x28");
    assert.equal(g.create_a4, 0x00c7b640, "B a4 const");
    assert.equal(g.create_a5, 0, "B a5 0");
    assert.equal(g.create_a6, 0x21, "B a6 = cur.f8");
    assert.equal(g.create_a7, 0x43, "B a7 = cur.f34");
    assert.equal(g.create_a8, 0, "B a8 0");
    assert.equal(g.create_this_va, 0x00c71678, "this = Game");
    assert.equal(g.bind_arg2, 0x1000, "B bind arg2 = cur");
    assert.equal(g.bind_arg1_fire, 1, "bind fires");
    assert.equal(g.local_a_bits, 0, "no float on path B");
    assert.equal(g.local_d_bits, 0, "no float on path B");
    assert.equal(g.local_e_bits, 0, "no float on path B");
    assert.equal(g.cos_r_bits, 0x11223344, "vel.x passthrough");
    assert.equal(g.sin_r_bits, 0x55667788, "vel.y passthrough");
  }
  {
    /* PATH_A: create args from the ADVANCED element (next). */
    const g = l1JL("l1PathA",
      { cur_ptr: 0x1000, end_ptr: 0x1168, cur_f0: 0x3c5, cur_f4: 0,
        cur_f8: 0x21, cur_f34: 0x43, cur_f80: 0x81, cur_fac: 0xac1,
        cur_f50_bits: 0x40400000, cur_w20: 0x80, next_f0: 0x55,
        next_f4: 0x66, room_f0c: 8, cos_r_bits: 0x11223344,
        sin_r_bits: 0x55667788 });
    assert.equal(g.path_a, 1, "0x3c5/0 path a");
    assert.equal(g.create_a1, 0x55, "A a1 = NEXT.f0 (advanced)");
    assert.equal(g.create_a2, 0x66, "A a2 = NEXT.f4");
    assert.equal(g.create_a3, 0x10a0, "A a3 = next+0x28 (saved+0x78)");
    assert.equal(g.create_a6, 0x81, "A a6 = cur.f80");
    assert.equal(g.create_a7, 0xac1, "A a7 = cur.fac");
    assert.equal(g.bind_arg2, 0x1078, "A bind arg2 = next ptr");
  }
  {
    /* path_a FULL dword: low byte 0xc5 but 0x2c5 != 0x3c5. */
    const g = l1JL("l1LowByte", { cur_ptr: 0x1000, end_ptr: 0x1168,
      cur_f0: 0x2c5, cur_f4: 0, cur_f8: 0, cur_f34: 0, cur_f80: 0,
      cur_fac: 0, cur_f50_bits: 0, cur_w20: 0, next_f0: 0, next_f4: 0,
      room_f0c: 8, cos_r_bits: 0, sin_r_bits: 0 });
    assert.equal(g.path_a, 0, "0x2c5 != 0x3c5 (FULL dword)");
  }
  {
    /* subtype must be 0 FULL dword. */
    const g = l1JL("l1Sub", { cur_ptr: 0x1000, end_ptr: 0x1168,
      cur_f0: 0x3c5, cur_f4: 0x100, cur_f8: 0, cur_f34: 0, cur_f80: 0,
      cur_fac: 0, cur_f50_bits: 0, cur_w20: 0, next_f0: 0, next_f4: 0,
      room_f0c: 8, cos_r_bits: 0, sin_r_bits: 0 });
    assert.equal(g.path_a, 0, "subtype 0x100 != 0");
  }
  {
    /* Last element: next_ptr == end -> continue 0 (EQUALITY gate). */
    const g = l1JL("l1Last", { cur_ptr: 0x10f0, end_ptr: 0x1168,
      cur_f0: 0x3c5, cur_f4: 0, cur_f8: 0, cur_f34: 0, cur_f80: 0,
      cur_fac: 0, cur_f50_bits: 0, cur_w20: 0, next_f0: 0, next_f4: 0,
      room_f0c: 8, cos_r_bits: 0, sin_r_bits: 0 });
    assert.equal(g.continue_loop, 0, "next == end stops");
    assert.equal(g.next_ptr, 0x1168, "next = end");
  }
  {
    /* FLOAT path A: f50=3.0f * deg2rad; w20=128 / f0c=8 -> q16 r0;
       localD = f32(0)*40+40 = 40.0f; localE = 16*40+120 = 760. */
    const g = l1JL("l1Float",
      { cur_ptr: 0x1000, end_ptr: 0x1168, cur_f0: 0x3c5, cur_f4: 0,
        cur_f8: 0, cur_f34: 0, cur_f80: 0, cur_fac: 0,
        cur_f50_bits: 0x40400000, cur_w20: 0x80, next_f0: 0, next_f4: 0,
        room_f0c: 8, cos_r_bits: 0, sin_r_bits: 0 });
    const want = roomRestoreList1Step(
      { cur_ptr: 0x1000, end_ptr: 0x1168, cur_f0: 0x3c5, cur_f4: 0,
        cur_f8: 0, cur_f34: 0, cur_f80: 0, cur_fac: 0,
        cur_f50_bits: 0x40400000, cur_w20: 0x80, next_f0: 0, next_f4: 0,
        room_f0c: 8, cos_r_bits: 0, sin_r_bits: 0 });
    assert.equal(g.local_a_bits, want.local_a_bits, "f50*deg2rad f32");
    assert.equal(g.quot | 0, 16, "128/8 = 16");
    assert.equal(g.rem | 0, 0, "rem 0");
    assert.equal(g.local_d_bits, 0x42200000, "0*40+40 = 40.0f");
    assert.equal(g.local_e_bits, want.local_e_bits, "16*40+120 f32");
    assert.equal(g.minecart_va, 0x006b7be0, "GiveMinecart");
    assert.equal(g.minecart_this_passthru, 1, "this = create result");
    assert.equal(g.pos_ptr_off, 0x20, "position base [esp+0x20]");
    assert.equal(g.vel_ptr_off, 0x18, "velocity base [esp+0x18]");
    assert.equal(g.cos_va, 0x0041d540, "cos host");
    assert.equal(g.sin_va, 0x0041d520, "sin host");
  }
  {
    /* SIGNED idiv: w20=0x8000 (int16 -32768) / 8 -> q-4096 r0;
       w20=0xffff (int16 -1) / 8 -> q0 r-1 -> localD = -40+40 = 0. */
    const g = l1JL("l1Sxw",
      { cur_ptr: 0x1000, end_ptr: 0x1168, cur_f0: 0x3c5, cur_f4: 0,
        cur_f8: 0, cur_f34: 0, cur_f80: 0, cur_fac: 0,
        cur_f50_bits: 0x40400000, cur_w20: 0x8000, next_f0: 0,
        next_f4: 0, room_f0c: 8, cos_r_bits: 0, sin_r_bits: 0 });
    assert.equal(g.quot | 0, -4096, "movsx -32768 / 8 SIGNED");
    assert.equal(g.rem | 0, 0, "rem 0");
    const want = roomRestoreList1Step(
      { cur_ptr: 0x1000, end_ptr: 0x1168, cur_f0: 0x3c5, cur_f4: 0,
        cur_f8: 0, cur_f34: 0, cur_f80: 0, cur_fac: 0,
        cur_f50_bits: 0x40400000, cur_w20: 0x8000, next_f0: 0,
        next_f4: 0, room_f0c: 8, cos_r_bits: 0, sin_r_bits: 0 });
    assert.equal(g.local_e_bits, want.local_e_bits, "-4096*40+120 f32");
    const g2 = l1JL("l1RemNeg",
      { cur_ptr: 0x1000, end_ptr: 0x1168, cur_f0: 0x3c5, cur_f4: 0,
        cur_f8: 0, cur_f34: 0, cur_f80: 0, cur_fac: 0,
        cur_f50_bits: 0x40400000, cur_w20: 0xffff, next_f0: 0,
        next_f4: 0, room_f0c: 8, cos_r_bits: 0, sin_r_bits: 0 });
    assert.equal(g2.quot | 0, 0, "trunc(-1/8) = 0");
    assert.equal(g2.rem | 0, -1, "rem -1");
    assert.equal(g2.local_d_bits, 0, "-1*40+40 = 0.0f");
  }
});

test("room v63: Room::RestoreState list2 clear + gates (PE 0x7f00ba.."
     + "0x7f0100)", () => {
  assert.equal(ROOM_RESTORE_DTOR_HOST_VA, 0x004d6ee0);
  assert.equal(ROOM_RESTORE_F4_0_EXPECT, -10);
  assert.equal(ROOM_RESTORE_GAME_0_EXPECT, 8);
  assert.equal(ROOM_RESTORE_F4_44_OFF, 0x44);

  const { memory, restoreList2Clear: wL2, restoreGates: wGates } =
    loadExports();
  const view = new DataView(memory.buffer);
  const L = MEM + 0xa100;
  const l2JL = (label, b, e) => {
    const want = roomRestoreList2Clear(b, e);
    wL2(b >>> 0, e >>> 0, L);
    const got = v63ReadOut(view, L, V63_L2_OUT_OFF);
    for (const k of Object.keys(V63_L2_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: l2.${k}`);
    }
    return got;
  };
  {
    const g = l2JL("l2Three", 0x1000, 0x1168); /* 3 * 0x78 */
    assert.equal(g.dtor_count, 3, "3 elements");
    assert.equal(g.store_end, 0x1000, "end := begin");
    assert.equal(g.dtor_host_va, 0x004d6ee0, "EntitySaveState dtor");
    assert.equal(g.stride, 0x78, "stride");
  }
  {
    /* 0x168 = 360 bytes = exactly 3 slots (guard against >>7 -> 2). */
    const g = l2JL("l2ExactDiv", 0x80, 0x1e8);
    assert.equal(g.dtor_count, 3, "360/120 = 3 (not 360>>7=2)");
  }
  {
    /* empty list: begin == end -> 0 dtors, same end:=begin store. */
    const g = l2JL("l2Empty", 0x1000, 0x1000);
    assert.equal(g.dtor_count, 0, "empty list");
    assert.equal(g.store_end, 0x1000, "no-op store");
  }

  const G = MEM + 0xa140;
  const gateJL = (label, f4f0, gamef0, byte44) => {
    const want = roomRestoreGates(f4f0, gamef0, byte44);
    wGates(f4f0 | 0, gamef0 | 0, byte44 >>> 0, G);
    const got = v63ReadOut(view, G, V63_GATES_OUT_OFF);
    for (const k of Object.keys(V63_GATES_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: gates.${k}`);
    }
    return got;
  };
  {
    const g = gateJL("gateFire", -10, 8, 1);
    assert.equal(g.fire, 1, "all three gates pass");
    assert.equal(g.f4_0_expect, 0xfffffff6, "-10 full dword");
    assert.equal(g.early_ret_va, 0x007f01b8, "early ret VA");
    assert.equal(g.grid_head_va, 0x007f0106, "grid head");
    assert.equal(g.grid_done_va, 0x007f018d, "grid done");
    const g2 = gateJL("gateGame", -10, 7, 1);
    assert.equal(g2.fire, 0, "Game.f0 7 != 8");
  }
  {
    /* FULL dword: 0x100000f6 low byte 0xf6 but != -10. */
    const g = gateJL("gateLowByte", 0x100000f6, 8, 1);
    assert.equal(g.fire, 0, "0x100000f6 != -10 (FULL dword)");
  }
  {
    /* byte bit0 gate: dword 0x100 has bit0 CLEAR -> no fire. */
    const g = gateJL("gateByte", -10, 8, 0x100);
    assert.equal(g.fire, 0, "byte bit0 clear -> no fire (dword != 0)");
    const g2 = gateJL("gateByteSet", -10, 8, 3);
    assert.equal(g2.fire, 1, "byte bit0 set -> fire");
  }
});

test("room v63: Room::RestoreState grid fix step (PE 0x7f0106.."
     + "0x7f018d)", () => {
  assert.equal(ROOM_RESTORE_GRID_HEAD_VA, 0x007f0106);
  assert.equal(ROOM_RESTORE_GRID_TYPE_EXPECT, 0xf);
  assert.equal(ROOM_RESTORE_GRID_TARGET_MAX, 0x1bf);
  assert.equal(ROOM_RESTORE_GRID_F76C_VALUE, 0x384);
  assert.equal(ROOM_RESTORE_GRID_VTABLE_SLOT, 0);

  const { memory, restoreGridStep: wGrid } = loadExports();
  const view = new DataView(memory.buffer);
  const S = MEM + 0xa180, O = MEM + 0xa1c0;
  const gridJL = (label, src) => {
    const want = roomRestoreGridStep(src);
    v63WriteGridSrc(view, S, src);
    wGrid(S, O);
    const got = v63ReadOut(view, O, V63_GRID_OUT_OFF);
    for (const k of Object.keys(V63_GRID_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `${label}: grid.${k}`);
    }
    return got;
  };
  const OKCELL = { src_ptr: 0x2000, src_f4: 0xf, src_f24: 0x40,
    dst_ptr: 0x3000, dst_f4: 2 };
  {
    /* All guards pass: fire + stores + indirect annotation. */
    const g = gridJL("gridFire", { cols: 4, rows: 4, i: 1, j: 1,
      ...OKCELL });
    assert.equal(g.outer_fire, 1, "rows 4: (4-1) > 1");
    assert.equal(g.inner_fire, 1, "cols 4: (4-1) > 1");
    assert.equal(g.index | 0, 5, "4*1+1");
    assert.equal(g.fire, 1, "fires");
    assert.equal(g.store_76c_value, 0x384, "f76c store");
    assert.equal(g.indirect_fire, 1, "indirect fires");
    assert.equal(g.indirect_arg, 1, "arg 1 pushed");
    assert.equal(g.vtable_slot, 0, "vtable slot 0");
    assert.equal(g.continue_j, 1, "2 < 3 (jl)");
    assert.equal(g.continue_i, 1, "2 < 3 (jl)");
    assert.equal(g.grid_base_off, 0x24, "grid base");
    assert.equal(g.target, 0x40, "target from src_f24");
  }
  {
    /* rows/cols entry gates SIGNED: rows=2 -> no outer fire even with
       matching cells. */
    const g = gridJL("gridRows2", { cols: 4, rows: 2, i: 1, j: 1,
      ...OKCELL });
    assert.equal(g.outer_fire, 0, "rows 2: (2-1)<=1 skips");
    assert.equal(g.fire, 0, "no fire");
    const g2 = gridJL("gridCols2", { cols: 2, rows: 4, i: 1, j: 1,
      ...OKCELL });
    assert.equal(g2.inner_fire, 0, "cols 2 skips inner");
    assert.equal(g2.fire, 0, "no fire");
  }
  {
    /* rows = 0x80000000: dec -> 0x7fffffff > 1 -> outer fires. */
    const g = gridJL("gridHugeRows", { cols: 4, rows: -0x80000000,
      i: 1, j: 1, ...OKCELL });
    assert.equal(g.outer_fire, 1, "signed dec wrap fires");
  }
  {
    /* index wrap: cols=0x40000000 i=3 -> 0xC0000001 signed -> skip
       via js; unsigned mutant would fire. */
    const g = gridJL("gridIndexWrap", { cols: 0x40000000, rows: 5, i: 3,
      j: 1, ...OKCELL });
    assert.equal(g.index | 0, -0x3fffffff, "wrapped signed index");
    assert.equal(g.index_ok, 0, "js guard skips");
    assert.equal(g.fire, 0, "no fire");
  }
  {
    /* target gate UNSIGNED ja: 0x1c0 > 0x1bf skip; 0x80000000 skip. */
    const g = gridJL("gridTargetMax", { cols: 4, rows: 4, i: 1, j: 1,
      src_ptr: 0x2000, src_f4: 0xf, src_f24: 0x1c0, dst_ptr: 0x3000,
      dst_f4: 2 });
    assert.equal(g.target_ok, 0, "0x1c0 > 0x1bf UNSIGNED");
    assert.equal(g.fire, 0, "no fire");
    const g2 = gridJL("gridTargetNeg", { cols: 4, rows: 4, i: 1, j: 1,
      src_ptr: 0x2000, src_f4: 0xf, src_f24: 0x80000000,
      dst_ptr: 0x3000, dst_f4: 2 });
    assert.equal(g2.target_ok, 0, "0x80000000 unsigned > 0x1bf");
  }
  {
    /* cell type + dst type gates. */
    const g = gridJL("gridSrcType", { cols: 4, rows: 4, i: 1, j: 1,
      src_ptr: 0x2000, src_f4: 0xe, src_f24: 0x40, dst_ptr: 0x3000,
      dst_f4: 2 });
    assert.equal(g.src_type_ok, 0, "src.f4 0xe != 0xf");
    const g2 = gridJL("gridDstType", { cols: 4, rows: 4, i: 1, j: 1,
      src_ptr: 0x2000, src_f4: 0xf, src_f24: 0x40, dst_ptr: 0x3000,
      dst_f4: 1 });
    assert.equal(g2.dst_type_ok, 0, "dst.f4 1 skips (je)");
    assert.equal(g2.fire, 0, "no fire");
    const g3 = gridJL("gridNullSrc", { cols: 4, rows: 4, i: 1, j: 1,
      src_ptr: 0, src_f4: 0xf, src_f24: 0x40, dst_ptr: 0x3000,
      dst_f4: 2 });
    assert.equal(g3.src_ok, 0, "null src skips");
  }
  {
    /* per-cell signed bounds guards. */
    const g = gridJL("gridJNeg", { cols: 4, rows: 4, i: 1, j: -1,
      ...OKCELL });
    assert.equal(g.j_ok, 0, "j -1 js skips");
    assert.equal(g.fire, 0, "no fire");
    const g2 = gridJL("gridINeg", { cols: 4, rows: 4, i: -0x80000000,
      j: 1, ...OKCELL });
    assert.equal(g2.i_ok, 0, "i negative skips");
    assert.equal(g2.fire, 0, "no fire");
    const g3 = gridJL("gridIHi", { cols: 4, rows: 4, i: 4, j: 1,
      ...OKCELL });
    assert.equal(g3.i_ok, 0, "i >= rows jge skips");
    assert.equal(g3.fire, 0, "no fire");
    assert.equal(g3.continue_i, 0, "5 < 3 false");
  }
});

test("room v63: Room::RestoreState mutation discrimination", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s2) => (crlfFile ? s2.replace(/\n/g, "\r\n") : s2);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, label + ": mutant did not apply");
    writeSourceRetry(toFile(bad));
    let threw = false;
    try { check(); } catch { threw = true; }
    writeSourceRetry(original);
    assert.ok(threw, label + ": mutant survived every assertion");
  };
  const eq = (a, b, m) => { try { assert.equal(a, b, m); } catch { throw new Error(m); } };

  const GT = () => {
    const e = loadExports();
    const view = new DataView(e.memory.buffer);
    return { e, view, g: MEM + 0xa200, o: MEM + 0xa240 };
  };
  const callGates = (h, f4f0, gamef0, byte44) => {
    h.e.restoreGates(f4f0 | 0, gamef0 | 0, byte44 >>> 0, h.g);
    return v63ReadOut(h.view, h.g, V63_GATES_OUT_OFF);
  };

  try {
    /* (1) COUNTER EXIT STORE: normal exit must restore c, not c+1. */
    withMutant("restore counter exit +1",
      (s2) => s2.replace(
        "out->exit_store = counter_in;",
        "out->exit_store = counter_in + 1u;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        e.restoreCounters(5, MEM + 0xa280);
        eq(view.getUint32(MEM + 0xa280 + 4, true), 5,
          "normal exit restores c (dec [mem])");
      });
    /* (2) LIST1 path_a LOW-BYTE: 0x2c5 must NOT match 0x3c5. */
    withMutant("restore list1 path_a low-byte",
      (s2) => s2.replace(
        "(static_cast<int32_t>(src->cur_f0) == ISAAC_ROOM_RESTORE_WALK_TYPE_GATE &&",
        "((src->cur_f0 & 0xffu) == 0xc5u &&"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        v63WriteL1Src(view, MEM + 0xa2c0,
          { cur_ptr: 0x1000, end_ptr: 0x1168, cur_f0: 0x2c5, cur_f4: 0,
            cur_f8: 0, cur_f34: 0, cur_f80: 0, cur_fac: 0,
            cur_f50_bits: 0, cur_w20: 0, next_f0: 0, next_f4: 0,
            room_f0c: 8, cos_r_bits: 0, sin_r_bits: 0 });
        e.restoreList1Step(MEM + 0xa2c0, MEM + 0xa300);
        eq(view.getUint32(MEM + 0xa300 + 0, true), 0,
          "0x2c5 != 0x3c5 (FULL dword)");
      });
    /* (3) DEG2RAD CONSTANT: 0xbaa088 = 0x3c8efa35 (deg2rad); the
        handoff's "22.5f" (0x41b40000) would round differently. */
    withMutant("restore deg2rad mislabeled 22.5f",
      (s2) => s2.replace(
        "ISAAC_ROOM_RESTORE_DEG2RAD_BITS);",
        "0x41b40000u); /* wrong 22.5f constant */"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        v63WriteL1Src(view, MEM + 0xa340,
          { cur_ptr: 0x1000, end_ptr: 0x1168, cur_f0: 0x3c5, cur_f4: 0,
            cur_f8: 0, cur_f34: 0, cur_f80: 0, cur_fac: 0,
            cur_f50_bits: 0x40400000, cur_w20: 0x80, next_f0: 0,
            next_f4: 0, room_f0c: 8, cos_r_bits: 0, sin_r_bits: 0 });
        e.restoreList1Step(MEM + 0xa340, MEM + 0xa380);
        const want = roomRestoreList1Step(
          { cur_ptr: 0x1000, end_ptr: 0x1168, cur_f0: 0x3c5, cur_f4: 0,
            cur_f8: 0, cur_f34: 0, cur_f80: 0, cur_fac: 0,
            cur_f50_bits: 0x40400000, cur_w20: 0x80, next_f0: 0,
            next_f4: 0, room_f0c: 8, cos_r_bits: 0, sin_r_bits: 0 });
        eq(view.getUint32(MEM + 0xa380 + 68, true), want.local_a_bits,
          "localA = f50 * deg2rad (0x3c8efa35), not 22.5f");
      });
    /* (4) SXW MOVZX: w20 is movsx int16 (SIGNED); a movzx mutant flips
        quot/rem for 0x8000. */
    withMutant("restore w20 movzx unsigned",
      (s2) => s2.replace(
        "const int32_t w20 = static_cast<int32_t>(static_cast<int16_t>(src->cur_w20));",
        "const int32_t w20 = static_cast<int32_t>(src->cur_w20 & 0xffffu); /* movzx */"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        v63WriteL1Src(view, MEM + 0xa3c0,
          { cur_ptr: 0x1000, end_ptr: 0x1168, cur_f0: 0x3c5, cur_f4: 0,
            cur_f8: 0, cur_f34: 0, cur_f80: 0, cur_fac: 0,
            cur_f50_bits: 0x40400000, cur_w20: 0x8000, next_f0: 0,
            next_f4: 0, room_f0c: 8, cos_r_bits: 0, sin_r_bits: 0 });
        e.restoreList1Step(MEM + 0xa3c0, MEM + 0xa400);
        eq(view.getInt32(MEM + 0xa400 + 72, true), -4096,
          "movsx -32768 / 8 = -4096 (SIGNED idiv)");
      });
    /* (5) GRID INDEX js guard dropped: 0xC0000001 must skip. */
    withMutant("restore grid index js dropped",
      (s2) => s2.replace(
        "out->index_ok = (index >= 0) ? 1u : 0u;",
        "out->index_ok = 1u; /* js guard dropped */"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        v63WriteGridSrc(view, MEM + 0xa440,
          { cols: 0x40000000, rows: 5, i: 3, j: 1, src_ptr: 0x2000,
            src_f4: 0xf, src_f24: 0x40, dst_ptr: 0x3000, dst_f4: 2 });
        e.restoreGridStep(MEM + 0xa440, MEM + 0xa480);
        eq(view.getUint32(MEM + 0xa480 + 48, true), 0,
          "wrapped negative index skips (js)");
      });
    /* (6) GRID TARGET SIGNED: (u32)target <= 0x1bf — ja UNSIGNED. */
    withMutant("restore grid target signed",
      (s2) => s2.replace(
        "out->target_ok = (src->src_f24 <= ISAAC_ROOM_RESTORE_GRID_TARGET_MAX)",
        "out->target_ok = (static_cast<int32_t>(src->src_f24) <= ISAAC_ROOM_RESTORE_GRID_TARGET_MAX)"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        v63WriteGridSrc(view, MEM + 0xa4c0,
          { cols: 4, rows: 4, i: 1, j: 1, src_ptr: 0x2000, src_f4: 0xf,
            src_f24: 0x80000000, dst_ptr: 0x3000, dst_f4: 2 });
        e.restoreGridStep(MEM + 0xa4c0, MEM + 0xa500);
        eq(view.getUint32(MEM + 0xa500 + 48, true), 0,
          "target 0x80000000 unsigned > 0x1bf skips");
      });
    /* (7) GATES BYTE vs DWORD: byte bit0 gate; dword 0x100 must NOT
        fire. */
    withMutant("restore gates byte test widened",
      (s2) => s2.replace(
        "(f4_44_byte & ISAAC_ROOM_RESTORE_F4_44_BIT) != 0u)",
        "(f4_44_byte != 0u) /* full dword mutant */"),
      () => {
        const h = GT();
        const g = callGates(h, -10, 8, 0x100);
        eq(g.fire, 0, "byte bit0 clear -> no fire (dword 0x100)");
      });
    /* (8) LOOP8 UNSIGNED jb: (u32)(k+1) < 8; a <= mutant continues at
        k=7. */
    withMutant("restore loop8 jbe",
      (s2) => s2.replace(
        "out->continue_loop = (next < ISAAC_ROOM_RESTORE_LOOP8_COUNT) ? 1u : 0u;",
        "out->continue_loop = (next <= ISAAC_ROOM_RESTORE_LOOP8_COUNT) ? 1u : 0u;"),
      () => {
        const e = loadExports();
        const view = new DataView(e.memory.buffer);
        e.restoreLoop8Step(7, MEM + 0xa540);
        eq(view.getUint32(MEM + 0xa540 + 0, true), 0,
          "k7: 8 < 8 false (jb)");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});

/* ----------------------------------------------------------------- v64 --- */
test("room v64 ambient 7f01c0 pure islands (helpers ABI v64)", () => {
  /* FUN_007f01c0 body pure islands: position math (SIGNED idiv
     [slot+0x24]/room_f0c, quot*40+120+laneA / rem*40+40+laneB, lane=
     edi&3), main distance (CROSSED slot_x-p340 / slot_y-p33c, dist2,
     CRT sqrt 0x435a50), special step (s13c0==0x23, len2>4.0f, 4-quadrant
     dir law incl. NaN direction), adjusted distance (crossed vs
     p340+2b / p33c+2a), tail decision (byte gates + ecx provenance +
     bind 0x710480), bounds chain (this.f8==0x10, 120/110/100/140 +
     f1c/f20+20, dest VAs). JS oracle vs Wasm for every new law. */
  const { abi, memory,
    ambient7f01c0Va, ambient7f01c0RetVa,
    ambient7f01c0LaneOffQuot, ambient7f01c0LaneOffRem,
    ambient7f01c0PosStep, ambient7f01c0Dist, ambient7f01c0SpecialStep,
    ambient7f01c0AdjDist, ambient7f01c0TailDecision,
    ambient7f01c0Bounds } = loadExports();
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.match(readFileSync(header, "utf8"),
    /ISAAC_ROOM_PURE_HELPERS_ABI_VERSION = 88/);
  assert.equal(ambient7f01c0Va() >>> 0, ROOM_AMBIENT_7F01C0_VA);
  assert.equal(ambient7f01c0RetVa() >>> 0, ROOM_AMBIENT_7F01C0_RET_VA);
  const view = new DataView(memory.buffer);
  const P = MEM + 0x7c00;
  const S = MEM + 0x7d00;
  const f32bits = (v) => {
    const f = new Float32Array(1);
    f[0] = Math.fround(v);
    return new Uint32Array(f.buffer)[0] >>> 0;
  };
  const f32v = (bits) => {
    const u = new Uint32Array([bits >>> 0]);
    return new Float32Array(u.buffer)[0];
  };
  const cmp = (wm, j, tag) => { /* wm: wasm object, j: model object */
    assert.deepEqual(wm, j, `v64 ${tag}`);
  };

  /* ---- lane offset getters (PE displacement indexing) ---- */
  const expectQuot = [0, -18, 0, 18];
  const expectRem = [-18, 0, 18, 0];
  for (let k = 0; k < 4; k++) {
    assert.equal(f32bits(ambient7f01c0LaneOffQuot(k)),
      f32bits(expectQuot[k]), `laneA[${k}] bits`);
    assert.equal(f32bits(ambient7f01c0LaneOffRem(k)),
      f32bits(expectRem[k]), `laneB[${k}] bits`);
    /* wide lane inputs: only low 2 bits matter (and eax,3). */
    assert.equal(f32bits(ambient7f01c0LaneOffQuot(0x100 | k)),
      f32bits(expectQuot[k]), `laneA wide ${k}`);
  }

  /* ---- position step: pinned (quot=1,rem=1 for 41/40) ---- */
  const pos = (f24, f0c, lane) => {
    view.setInt32(S + 0, f24 | 0, true);
    view.setInt32(S + 4, f0c | 0, true);
    view.setUint32(S + 8, lane >>> 0, true);
    ambient7f01c0PosStep(S, P);
    const wm = {
      quot: view.getInt32(P + 0, true),
      rem: view.getInt32(P + 4, true),
      div_ok: view.getUint32(P + 8, true),
      lane: view.getUint32(P + 12, true),
      slot_x_bits: view.getUint32(P + 16, true),
      slot_y_bits: view.getUint32(P + 20, true),
      f40_bits: view.getUint32(P + 24, true),
      f120_bits: view.getUint32(P + 28, true),
      lane_quot_va: view.getUint32(P + 32, true),
      lane_rem_va: view.getUint32(P + 36, true),
    };
    const j = roomAmbient7f01c0PosStep({ slot_f24: f24 | 0,
      room_f0c: f0c | 0, lane: lane >>> 0 });
    cmp(wm, j, `pos ${f24}/${f0c}/${lane}`);
    return wm;
  };
  /* 41/40 -> quot 1 rem 1: slot_x = 160+laneA, slot_y = 80+laneB. */
  assert.equal(pos(41, 40, 0).slot_x_bits, f32bits(160), "lane0 x=160");
  assert.equal(pos(41, 40, 0).slot_y_bits, f32bits(62), "lane0 y=80-18");
  assert.equal(pos(41, 40, 1).slot_x_bits, f32bits(142), "lane1 x=160-18");
  assert.equal(pos(41, 40, 2).slot_y_bits, f32bits(98), "lane2 y=80+18");
  assert.equal(pos(41, 40, 3).slot_x_bits, f32bits(178), "lane3 x=160+18");
  /* negative dividend: -41/40 -> quot -1 rem -1 (toward zero). */
  assert.equal(pos(-41, 40, 0).quot, -1, "neg quot -1");
  assert.equal(pos(-41, 40, 0).rem, -1, "neg rem -1");
  assert.equal(pos(-41, 40, 0).slot_x_bits, f32bits(80), "neg x=(-40)+120");
  assert.equal(pos(-41, 40, 0).slot_y_bits, f32bits(-18),
    "neg y=(-40)+40+laneB[0]=-18");
  /* idiv fault cases. */
  assert.equal(pos(5, 0, 0).div_ok, 0, "divisor 0 faults");
  assert.equal(pos(0x80000000 | 0, -1, 0).div_ok, 0, "INT_MIN/-1 faults");

  /* ---- distance: CROSSED axes ---- */
  const dist = (sx, sy, p0, p1) => {
    view.setUint32(S + 0, f32bits(sx), true);
    view.setUint32(S + 4, f32bits(sy), true);
    view.setUint32(S + 8, f32bits(p0), true);
    view.setUint32(S + 12, f32bits(p1), true);
    ambient7f01c0Dist(S, P);
    const wm = {
      d0_bits: view.getUint32(P + 0, true),
      d1_bits: view.getUint32(P + 4, true),
      dist2_bits: view.getUint32(P + 8, true),
      dist_bits: view.getUint32(P + 12, true),
      sqrt_va: view.getUint32(P + 16, true),
      sqrt_primitive: view.getUint32(P + 20, true),
    };
    const j = roomAmbient7f01c0Dist({ slot_x_bits: f32bits(sx),
      slot_y_bits: f32bits(sy), p33c_bits: f32bits(p0),
      p340_bits: f32bits(p1) });
    cmp(wm, j, `dist ${sx}/${sy}/${p0}/${p1}`);
    return wm;
  };
  /* slot (160,62), player (130,42): d0 = 160-42 = 118, d1 = 62-130 = -68;
     dist2 = 118^2+68^2 = 18548. */
  assert.equal(dist(160, 62, 130, 42).d0_bits, f32bits(118), "d0 crossed x-p340");
  assert.equal(dist(160, 62, 130, 42).d1_bits, f32bits(-68), "d1 crossed y-p33c");
  assert.equal(dist(160, 62, 130, 42).dist2_bits, f32bits(18548), "dist2 exact");
  assert.equal(dist(160, 62, 130, 42).dist_bits,
    f32bits(Math.sqrt(18548)), "dist sqrt");
  assert.equal(dist(160, 62, 130, 42).sqrt_va, ROOM_AMBIENT_7F01C0_SQRT_VA);
  assert.equal(dist(160, 62, 130, 42).sqrt_primitive, 1);
  /* NaN player coord: d0 NaN -> NaN path through sqrt. */
  assert.equal(dist(160, 62, NaN, 42).dist_bits, f32bits(NaN), "NaN p0 dist NaN");
  assert.equal(dist(160, 62, 130, NaN).d0_bits, f32bits(NaN), "NaN p1 d0 NaN");

  /* ---- special step: len2 gate + dir law ---- */
  const sp = (s13c0, a, b) => {
    view.setUint32(S + 0, s13c0 >>> 0, true);
    view.setUint32(S + 4, f32bits(a), true);
    view.setUint32(S + 8, f32bits(b), true);
    ambient7f01c0SpecialStep(S, P);
    const wm = {
      special_active: view.getUint32(P + 0, true),
      len2_bits: view.getUint32(P + 4, true),
      len2_gt_4: view.getUint32(P + 8, true),
      dir: view.getUint32(P + 12, true),
      dir_ok: view.getUint32(P + 16, true),
      gate4_bits: view.getUint32(P + 20, true),
      gate4_va: view.getUint32(P + 24, true),
      sqrt_va: view.getUint32(P + 28, true),
      head_va: view.getUint32(P + 32, true),
      epilogue_va: view.getUint32(P + 36, true),
    };
    const j = roomAmbient7f01c0SpecialStep({ s13c0: s13c0 >>> 0,
      a_bits: f32bits(a), b_bits: f32bits(b) });
    cmp(wm, j, `special ${s13c0}/${a}/${b}`);
    return wm;
  };
  assert.equal(sp(0x23, 3, -4).dir, 1, "|3|<|4|, b<0 -> 1");
  assert.equal(sp(0x23, -3, 4).dir, 3, "|3|<|4|, b>=0 -> 3");
  assert.equal(sp(0x23, 4, 3).dir, 2, "|4|>|3|, a>=0 -> 2");
  assert.equal(sp(0x23, -4, 3).dir, 0, "|4|>|3|, a<0 -> 0");
  assert.equal(sp(0x23, 3, 3).dir, 3, "equal |a|==|b| -> b arm");
  assert.equal(sp(0x23, -3, -3).dir, 1, "equal, b<0 -> 1");
  assert.equal(sp(0x23, 0, 0).dir, 3, "zeros: b arm, setbe(0,0)=1 -> 3");
  assert.equal(sp(0x23, 5, NaN).dir, 3, "NaN b -> setbe arm -> 3");
  assert.equal(sp(0x23, NaN, 5).dir, 3, "NaN a -> setbe arm (cl=1) -> 3");
  assert.equal(sp(0x23, 0.5, 0).len2_gt_4, 0, "len2 0.25 <= 4");
  assert.equal(sp(0x23, 0.5, 0).dir_ok, 0, "dir not wired when len2<=4");
  assert.equal(sp(0x23, 3, -4).len2_gt_4, 1, "len2 25 > 4");
  assert.equal(sp(0x23, 3, -4).special_active, 1, "s13c0 0x23");
  assert.equal(sp(0x22, 3, -4).special_active, 0, "s13c0 != 0x23");
  assert.equal(sp(0x23, 3, -4).dir_ok, 1, "dir wired");
  assert.equal(sp(0x23, 2, 2).len2_bits, f32bits(8), "len2 8 exact");

  /* ---- adjusted distance (crossed vs p340+2b / p33c+2a) ---- */
  const adj = (sx, sy, p0, p1, a, b) => {
    view.setUint32(S + 0, f32bits(sx), true);
    view.setUint32(S + 4, f32bits(sy), true);
    view.setUint32(S + 8, f32bits(p0), true);
    view.setUint32(S + 12, f32bits(p1), true);
    view.setUint32(S + 16, f32bits(a), true);
    view.setUint32(S + 20, f32bits(b), true);
    ambient7f01c0AdjDist(S, P);
    const wm = {
      d0_bits: view.getUint32(P + 0, true),
      d1_bits: view.getUint32(P + 4, true),
      dist2_bits: view.getUint32(P + 8, true),
      dist_bits: view.getUint32(P + 12, true),
      sqrt_va: view.getUint32(P + 16, true),
    };
    const j = roomAmbient7f01c0AdjDist({ slot_x_bits: f32bits(sx),
      slot_y_bits: f32bits(sy), p33c_bits: f32bits(p0),
      p340_bits: f32bits(p1), a_bits: f32bits(a), b_bits: f32bits(b) });
    cmp(wm, j, `adj ${sx}/${sy}/${p0}/${p1}/${a}/${b}`);
    return wm;
  };
  /* slot (160,62), player (130,42), a=3,b=4: nx=42+8=50, ny=130+6=136;
     d0=160-50=110, d1=62-136=-74; dist2 = 12100+5476=17576. */
  assert.equal(adj(160, 62, 130, 42, 3, 4).d0_bits, f32bits(110),
    "adj d0 = slot_x - (p340+2b)");
  assert.equal(adj(160, 62, 130, 42, 3, 4).d1_bits, f32bits(-74),
    "adj d1 = slot_y - (p33c+2a)");
  assert.equal(adj(160, 62, 130, 42, 3, 4).dist2_bits, f32bits(17576),
    "adj dist2 exact");

  /* ---- tail decision ---- */
  const tail = (s) => {
    view.setUint32(S + 0, s.special_active >>> 0, true);
    view.setUint32(S + 4, s.len2_gt_4 >>> 0, true);
    view.setUint32(S + 8, s.dir >>> 0, true);
    view.setUint32(S + 12, s.player_f1624 >>> 0, true);
    view.setUint32(S + 16, s.slot_type8 >>> 0, true);
    view.setInt32(S + 20, s.slot_f0c | 0, true);
    view.setUint32(S + 24, s.slot_f3a0_byte >>> 0, true);
    view.setUint32(S + 28, s.this_f4_44_byte >>> 0, true);
    view.setUint32(S + 32, f32bits(s.dist), true);
    view.setUint32(S + 36, s.lane >>> 0, true);
    ambient7f01c0TailDecision(S, P);
    const wm = {
      ecx_gate: view.getUint32(P + 0, true),
      ecx_is_dir: view.getUint32(P + 4, true),
      compare_enable: view.getUint32(P + 8, true),
      flag_bit_set: view.getUint32(P + 12, true),
      range_dest: view.getUint32(P + 16, true),
      type_ok: view.getUint32(P + 20, true),
      this_gate_ok: view.getUint32(P + 24, true),
      dist60_ok: view.getUint32(P + 28, true),
      dir_eq_lane: view.getUint32(P + 32, true),
      bind_fire: view.getUint32(P + 36, true),
      bind_host_va: view.getUint32(P + 40, true),
      bind_arg0: view.getUint32(P + 44, true),
      range_gate_bits: view.getUint32(P + 48, true),
      bind_gate_bits: view.getUint32(P + 52, true),
      dest_544_va: view.getUint32(P + 56, true),
      dest_485_va: view.getUint32(P + 60, true),
      head_va: view.getUint32(P + 64, true),
      epilogue_va: view.getUint32(P + 68, true),
    };
    const j = roomAmbient7f01c0TailDecision({
      special_active: s.special_active >>> 0,
      len2_gt_4: s.len2_gt_4 >>> 0,
      dir: s.dir >>> 0,
      player_f1624: s.player_f1624 >>> 0,
      slot_type8: s.slot_type8 >>> 0,
      slot_f0c: s.slot_f0c | 0,
      slot_f3a0_byte: s.slot_f3a0_byte >>> 0,
      this_f4_44_byte: s.this_f4_44_byte >>> 0,
      dist_bits: f32bits(s.dist),
      lane: s.lane >>> 0,
    });
    cmp(wm, j, `tail ${JSON.stringify(s)}`);
    return wm;
  };
  const base = {
    special_active: 0, len2_gt_4: 0, dir: 0,
    player_f1624: 0x1234, slot_type8: 1, slot_f0c: 2,
    slot_f3a0_byte: 0, this_f4_44_byte: 1, dist: 40, lane: 0,
  };
  /* flag clear -> enable iff f0c == 2. */
  assert.equal(tail(base).compare_enable, 1, "flag clear, f0c==2 enables");
  assert.equal(tail({ ...base, slot_f0c: 3 }).compare_enable, 0,
    "flag clear, f0c!=2 disables");
  /* flag set -> enable iff f0c != 2. */
  assert.equal(tail({ ...base, slot_f3a0_byte: 0x10, slot_f0c: 3 })
    .compare_enable, 1, "flag set, f0c!=2 enables");
  /* wide byte inputs: 0x100 low byte 0 (bit 0x10 clear), 0x1ff set. */
  assert.equal(tail({ ...base, slot_f3a0_byte: 0x100, slot_f0c: 2 })
    .flag_bit_set, 0, "f3a0 0x100 low byte: bit clear");
  assert.equal(tail({ ...base, slot_f3a0_byte: 0x1ff, slot_f0c: 3 })
    .flag_bit_set, 1, "f3a0 0x1ff bit set");
  assert.equal(tail({ ...base, slot_f3a0_byte: 0xffffffff, slot_f0c: 3 })
    .compare_enable, 1, "f3a0 all ones enables");
  assert.equal(tail({ ...base, this_f4_44_byte: 0x100 })
    .this_gate_ok, 0, "f4+0x44 0x100 low byte 0");
  assert.equal(tail({ ...base, this_f4_44_byte: 0x1ff })
    .this_gate_ok, 1, "f4+0x44 0x1ff bit0 set");
  /* type family {1,2,3,4,5} full dword. */
  for (const t of [1, 2, 3, 4, 5]) {
    assert.equal(tail({ ...base, slot_type8: t }).type_ok, 1, `type ${t}`);
  }
  for (const t of [0, 6, 7, 0x10, 0x23, -1, 0xffffffff]) {
    assert.equal(tail({ ...base, slot_type8: t >>> 0 }).type_ok, 0,
      `type ${t >>> 0} out`);
  }
  /* range gate: dist 24 -> 25>24 dest; dist 25/26/NaN -> none. */
  assert.equal(tail({ ...base, dist: 24 }).range_dest, 1, "dist<25 range");
  assert.equal(tail({ ...base, dist: 25 }).range_dest, 0, "dist==25 no range");
  assert.equal(tail({ ...base, dist: 26 }).range_dest, 0, "dist>25 no range");
  assert.equal(tail({ ...base, dist: NaN }).range_dest, 0, "NaN no range");
  /* bind 60 gate: dist 59 ok, 60/61/NaN not. */
  assert.equal(tail({ ...base, dist: 59 }).dist60_ok, 1, "dist<60 ok");
  assert.equal(tail({ ...base, dist: 60 }).dist60_ok, 0, "dist==60 no");
  assert.equal(tail({ ...base, dist: 61 }).dist60_ok, 0, "dist>60 no");
  assert.equal(tail({ ...base, dist: NaN }).dist60_ok, 0, "NaN no");
  /* ecx provenance: special&&gt -> dir; else player_f1624. */
  const wired = tail({ ...base, special_active: 1, len2_gt_4: 1, dir: 2 });
  assert.equal(wired.ecx_is_dir, 1, "dir wired");
  assert.equal(wired.ecx_gate, 2, "ecx = dir");
  assert.equal(tail({ ...base, dir: 2 }).ecx_gate, 0x1234,
    "ecx = f1624 when not wired");
  /* bind fires only when ALL gates pass (lane == ecx). */
  assert.equal(tail({ ...base, lane: 0x1234 }).bind_fire, 1,
    "f1624==lane binds");
  assert.equal(tail({ ...base, lane: 0x1234, dist: 70 }).bind_fire, 0,
    "dist>60 blocks bind");
  assert.equal(tail({ ...base, lane: 0x1234, dist: 24 }).bind_fire, 0,
    "range hit blocks bind");
  assert.equal(tail({ ...base, lane: 0x1234, slot_type8: 9 }).bind_fire, 0,
    "type out blocks bind");
  assert.equal(tail({ ...base, lane: 0x1234, this_f4_44_byte: 0 }).bind_fire,
    0, "this gate blocks bind");
  assert.equal(tail({ ...base, lane: 0x1234, slot_f0c: 5 }).bind_fire, 0,
    "enable gate blocks bind");
  assert.equal(tail({ ...base, lane: 7 }).bind_fire, 0, "lane mismatch");
  /* wired dir must equal the lane to bind. */
  assert.equal(tail({ ...base, special_active: 1, len2_gt_4: 1, dir: 2,
    lane: 2 }).bind_fire, 1, "dir==lane binds");
  /* dest VAs pinned. */
  assert.equal(tail(base).bind_host_va, ROOM_AMBIENT_7F01C0_BIND_HOST_VA);
  assert.equal(tail(base).dest_544_va, ROOM_AMBIENT_7F01C0_RANGE_TAIL_VA);
  assert.equal(tail(base).dest_485_va, ROOM_AMBIENT_7F01C0_TAIL_CONTINUE_VA);
  assert.equal(tail(base).head_va, ROOM_AMBIENT_7F01C0_VA);
  assert.equal(tail(base).epilogue_va, ROOM_AMBIENT_7F01C0_EPILOGUE_VA);

  /* ---- bounds chain ---- */
  const bnd = (f8, p0, p1, f1c, f20) => {
    view.setUint32(S + 0, f8 >>> 0, true);
    view.setUint32(S + 4, f32bits(p0), true);
    view.setUint32(S + 8, f32bits(p1), true);
    view.setUint32(S + 12, f32bits(f1c), true);
    view.setUint32(S + 16, f32bits(f20), true);
    ambient7f01c0Bounds(S, P);
    const wm = {
      chain_active: view.getUint32(P + 0, true),
      gate_a: view.getUint32(P + 4, true),
      gate_b: view.getUint32(P + 8, true),
      gate_c: view.getUint32(P + 12, true),
      gate_d: view.getUint32(P + 16, true),
      gate_e: view.getUint32(P + 20, true),
      gate_f: view.getUint32(P + 24, true),
      gate_g: view.getUint32(P + 28, true),
      dest: view.getUint32(P + 32, true),
      dest_va: view.getUint32(P + 36, true),
      cont_va: view.getUint32(P + 40, true),
      sqrt_va: view.getUint32(P + 84, true),
    };
    const j = roomAmbient7f01c0Bounds({ this_f8: f8 >>> 0,
      p33c_bits: f32bits(p0), p340_bits: f32bits(p1),
      room_f1c_bits: f32bits(f1c), room_f20_bits: f32bits(f20) });
    for (const k of ["chain_active", "gate_a", "gate_b", "gate_c",
      "gate_d", "gate_e", "gate_f", "gate_g", "dest", "dest_va",
      "cont_va", "sqrt_va"]) {
      assert.equal(wm[k], j[k], `bounds ${k} ${f8}/${p0}/${p1}/${f1c}/${f20}`);
    }
    return wm;
  };
  assert.equal(bnd(0x10, 50, 119, 0, 0).dest, 1, "p1 119 < 120 -> 6f4");
  assert.equal(bnd(0x10, 50, 119, 0, 0).dest_va, ROOM_AMBIENT_7F01C0_DEST_6F4_VA);
  assert.equal(bnd(0x11, 50, 119, 0, 0).chain_active, 0, "f8!=0x10 chain off");
  assert.equal(bnd(0x11, 50, 119, 0, 0).dest, 0, "chain off -> continue");
  /* p1 120: A fails; B (110>120) fails -> E: p0 50 > 0+20 -> 6ac. */
  assert.equal(bnd(0x10, 50, 120, 0, 0).dest, 2, "B fail -> E -> 6ac");
  assert.equal(bnd(0x10, 50, 120, 0, 0).dest_va, ROOM_AMBIENT_7F01C0_DEST_6AC_VA);
  /* p1 120, p0 50, f1c 100: E: 50 > 120 false -> F: 0>50 false -> G:
     p1 120 > f20+20 (f20=0 -> 20)? yes -> 678. */
  assert.equal(bnd(0x10, 50, 120, 100, 0).dest, 4, "E/F fail -> G -> 678");
  /* p1 50 (A fires first: 120>50) -> 6f4; the C/D gates are only
     REACHED when A fails (p1 >= 120 OR NaN p1), and then B (110>p1)
     also fails — so the B&&C&&D arm is dead machine code; pin the
     individual gates instead. */
  assert.equal(bnd(0x10, 105, 50, 0, 0).dest, 1, "p1 50 -> A -> 6f4");
  assert.equal(bnd(0x10, 101, 130, 0, 0).gate_d, 1, "gate_d 140>101");
  assert.equal(bnd(0x10, 141, 130, 0, 0).gate_d, 0, "gate_d 140>141 no");
  assert.equal(bnd(0x10, 101, 130, 0, 0).gate_c, 1, "gate_c 101>100");
  assert.equal(bnd(0x10, 99, 130, 0, 0).gate_c, 0, "gate_c 99>100 no");
  /* p1 130: A fails, B fails -> E: 200>20 -> 6ac. */
  assert.equal(bnd(0x10, 200, 130, 0, 0).dest, 2, "B fail -> E -> 6ac");
  /* p1 130, p0 0: E fail, F: 0>0 no, G: 130>20 -> 678. */
  assert.equal(bnd(0x10, 0, 130, 0, 0).dest, 4, "F -0.0 excluded -> G");
  /* p0 -5, p1 130: E fail (f1c 0 -> -5>20 no), F: 0>-5 -> 692. */
  assert.equal(bnd(0x10, -5, 130, 0, 0).dest, 3, "p0<0 -> 692");
  assert.equal(bnd(0x10, -5, 130, 0, 0).dest_va, ROOM_AMBIENT_7F01C0_DEST_692_VA);
  /* p0 -0.0: gate_f must NOT fire (0 > -0.0 is false). */
  const nz = bnd(0x10, -0.0, 130, 0, 0);
  assert.equal(nz.gate_f, 0, "-0.0 not < 0");
  /* NaN p0: C fails, E fails, F fails -> G decides. */
  assert.equal(bnd(0x10, NaN, 200, 0, 0).dest, 4, "NaN p0 -> G");
  assert.equal(bnd(0x10, NaN, 50, 0, 0).gate_c, 0, "NaN p0 not > 100");
  /* NaN p1: A fails, B fails -> E decides. */
  assert.equal(bnd(0x10, 50, NaN, 0, 0).dest, 2, "NaN p1 -> E");
  /* f1c/f20 gates use the ADDSS rounding: p0 exactly f1c+20. */
  assert.equal(bnd(0x10, 20, 50, 0, 0).gate_e, 0, "p0==bound no E");
  assert.equal(bnd(0x10, 20.5, 50, 0, 0).gate_e, 1, "p0>bound E");
  assert.equal(bnd(0x10, 50, 119, 0, 0).cont_va,
    ROOM_AMBIENT_7F01C0_CONTINUE_VA);
  assert.equal(bnd(0x10, 50, 119, 0, 0).sqrt_va, ROOM_AMBIENT_7F01C0_SQRT_VA);

  /* ---- randomized differential (LCG high bits) ---- */
  let lcg = 0x1b873593;
  const rnd = () => ((lcg = (Math.imul(lcg, 1664525) + 1013904223) >>> 0), lcg);
  const hi = (n) => Math.floor(rnd() / 2 ** 23) % n;
  const rf32 = () => {
    const kind = hi(100);
    if (kind === 0) return NaN;
    if (kind === 1) return hi(2) ? Infinity : -Infinity;
    if (kind === 2) return -0.0;
    return Math.fround((hi(400001) - 200000) / 1000);
  };
  for (let k = 0; k < 400; k++) {
    const lane = hi(8);
    pos((rnd() | 0), hi(200) - 50, lane);
    pos(rf32() | 0, 0, lane); /* div fault path */
    const sx = rf32(), sy = rf32(), p0 = rf32(), p1 = rf32();
    dist(sx, sy, p0, p1);
    adj(sx, sy, p0, p1, rf32(), rf32());
    sp((hi(2) ? 0x23 : 0x99), rf32(), rf32());
    sp(0x23, rf32(), 0); /* b==0 setbe edge */
    const s = {
      special_active: hi(2), len2_gt_4: hi(2), dir: hi(4),
      player_f1624: rnd() >>> 0,
      slot_type8: [1, 2, 3, 4, 5, 6, 9, 0x10, 0x23, 0xffffffff][hi(10)],
      slot_f0c: hi(5) - 2,
      slot_f3a0_byte: [0, 0x10, 0x100, 0x1ff, 0xffffffff][hi(5)],
      this_f4_44_byte: [0, 1, 0x100, 0x1ff, 0xffffffff][hi(5)],
      dist: rf32(),
      lane: hi(8),
    };
    tail(s);
    bnd([0x10, 0x11, 0][hi(3)], rf32(), rf32(), rf32(), rf32());
  }
});

test("room v64 mutation checks (helpers ABI v64)", () => {
  /* Each mutant must change behaviour AND a pinned assertion must catch
     it: the test itself FAILS on the mutated build. */
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const P = MEM + 0x7c00;
  const S = MEM + 0x7d00;
  const f32bits = (v) => {
    const f = new Float32Array(1);
    f[0] = Math.fround(v);
    return new Uint32Array(f.buffer)[0] >>> 0;
  };
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* (1) laneA/laneB swapped in the position law: slot_x must use the
       QUOT lane table {0,-18,0,18}; lane0 x = 160 stays, but must FAIL
       when the rem table {-18,0,18,0} is used instead. */
    withMutant("v64 lane tables swapped",
      (s) => s.replace(
        "const float lane_a = isaac_room_ambient_7f01c0_lane_off_quot(lane);\n  const float lane_b = isaac_room_ambient_7f01c0_lane_off_rem(lane);",
        "const float lane_a = isaac_room_ambient_7f01c0_lane_off_rem(lane);\n  const float lane_b = isaac_room_ambient_7f01c0_lane_off_quot(lane);",
      ),
      () => {
        const { memory, ambient7f01c0PosStep } = loadExports();
        const view = new DataView(memory.buffer);
        view.setInt32(S + 0, 41, true);
        view.setInt32(S + 4, 40, true);
        view.setUint32(S + 8, 1, true);
        ambient7f01c0PosStep(S, P);
        assert.equal(view.getUint32(P + 16, true), f32bits(142),
          "lane1 x = 160 + laneA[1] = 160-18");
      });
    /* (2) distance axes uncrossed: d0 must be slot_x - p340. */
    withMutant("v64 distance axes uncrossed",
      (s) => s.replace(
        "float d0 = sx - p1;\n  float d1 = sy - p0;",
        "float d0 = sx - p0;\n  float d1 = sy - p1;",
      ),
      () => {
        const { memory, ambient7f01c0Dist } = loadExports();
        const view = new DataView(memory.buffer);
        view.setUint32(S + 0, f32bits(160), true);
        view.setUint32(S + 4, f32bits(62), true);
        view.setUint32(S + 8, f32bits(130), true);
        view.setUint32(S + 12, f32bits(42), true);
        ambient7f01c0Dist(S, P);
        assert.equal(view.getUint32(P + 0, true), f32bits(118),
          "d0 = slot_x - p340 (crossed)");
      });
    /* (3) bounds gate B strictness: >= instead of > (jbe skips on the
       equality; the mutant would pass B at p1 == 110). */
    withMutant("v64 bounds gate B >= instead of >",
      (s) => s.replace(
        "const uint32_t gate_b = (f110 > p1) ? 1u : 0u;",
        "const uint32_t gate_b = (f110 >= p1) ? 1u : 0u;",
      ),
      () => {
        const { memory, ambient7f01c0Bounds } = loadExports();
        const view = new DataView(memory.buffer);
        view.setUint32(S + 0, 0x10, true);
        view.setUint32(S + 4, f32bits(101), true);
        view.setUint32(S + 8, f32bits(110), true);
        view.setUint32(S + 12, f32bits(0), true);
        view.setUint32(S + 16, f32bits(0), true);
        ambient7f01c0Bounds(S, P);
        /* PE: p1==110 -> jbe skips to E -> p0 101 > 20 -> 6ac. */
        assert.equal(view.getUint32(P + 32, true), 2, "p1==110 -> E -> 6ac");
      });
    /* (4) tail ecx provenance: dir used even when the special path did
       NOT run (must fall back to player_f1624). */
    withMutant("v64 tail ecx provenance ignores f1624",
      (s) => s.replace(
        "const uint32_t ecx_gate = ecx_is_dir != 0u ? src->dir : src->player_f1624;",
        "const uint32_t ecx_gate = src->dir;",
      ),
      () => {
        const { memory, ambient7f01c0TailDecision } = loadExports();
        const view = new DataView(memory.buffer);
        view.setUint32(S + 0, 0, true);  /* special_inactive */
        view.setUint32(S + 4, 0, true);
        view.setUint32(S + 8, 0, true);
        view.setUint32(S + 12, 0x1234, true); /* player_f1624 */
        view.setUint32(S + 16, 1, true); /* type 1 */
        view.setInt32(S + 20, 2, true);
        view.setUint32(S + 24, 0, true);
        view.setUint32(S + 28, 1, true);
        view.setUint32(S + 32, f32bits(40), true);
        view.setUint32(S + 36, 0x1234, true); /* lane == f1624 */
        ambient7f01c0TailDecision(S, P);
        assert.equal(view.getUint32(P + 0, true), 0x1234,
          "non-special ecx = player_f1624 (not stale dir)");
      });
    /* (5) tail flag gate: full-dword test instead of byte bit 0x10. */
    withMutant("v64 tail flag gate full-dword",
      (s) => s.replace(
        "((src->slot_f3a0_byte & ISAAC_ROOM_AMBIENT_7F01C0_SLOT_F3A0_BIT) != 0u)",
        "(src->slot_f3a0_byte != 0u)",
      ),
      () => {
        const { memory, ambient7f01c0TailDecision } = loadExports();
        const view = new DataView(memory.buffer);
        view.setUint32(S + 0, 0, true);
        view.setUint32(S + 4, 0, true);
        view.setUint32(S + 8, 0, true);
        view.setUint32(S + 12, 0, true);
        view.setUint32(S + 16, 1, true);
        view.setInt32(S + 20, 3, true); /* enable iff flag set && f0c!=2 */
        view.setUint32(S + 24, 0x100, true); /* bit 0x10 CLEAR in low byte */
        view.setUint32(S + 28, 1, true);
        view.setUint32(S + 32, f32bits(40), true);
        view.setUint32(S + 36, 0, true);
        ambient7f01c0TailDecision(S, P);
        assert.equal(view.getUint32(P + 8, true), 0,
          "0x100 low byte bit 0x10 clear -> enable off");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});

/* ------------------------------- v25r ---------------------------------- */
test("room v25r ambient 7f01c0 outer-loop count/continue law (helpers ABI v64)", () => {
  /* FUN_007f01c0 outer-loop CF pure laws: count = SAR((s32)([Game+
     0x1baac]-[Game+0x1baa8]),2); entry gate ZERO-ONLY (test/jz — a
     negative count ENTERS); continue tail 0x7f051b RE-READS Game
     [0x1baac]/[0x1baa8] EVERY iteration (0x7f0528/0x7f052e), then
     cmp/jb UNSIGNED (u32)idx_next < (u32)count_fresh; per-iteration
     decision = [player+0x2c]!=0 -> skip inner (Game::GetPlayer
     0x417870 stays HOST). v25r banner; ABI unchanged (64). */
  const {
    abi, memory,
    ambient7f01c0Va, ambient7f01c0RetVa,
    ambient7f01c0OuterCount, ambient7f01c0OuterContinue,
    ambient7f01c0OuterPlayerGate,
  } = loadExports();
  assert.equal(abi(), ROOM_PURE_ABI_VERSION, "v25r pinned to the current family ABI (74)");
  assert.equal(ambient7f01c0Va() >>> 0, ROOM_AMBIENT_7F01C0_VA);
  assert.equal(ambient7f01c0RetVa() >>> 0, ROOM_AMBIENT_7F01C0_RET_VA);
  assert.equal(ROOM_AMBIENT_7F01C0_GETPLAYER_VA, 0x00417870, "GetPlayer host VA pin");
  assert.equal(ROOM_AMBIENT_7F01C0_LOOP_HEAD_VA, 0x007f0250, "outer loop head VA pin");
  assert.equal(ROOM_AMBIENT_7F01C0_OUTER_COUNT_END_OFF, 0x1baac, "count end offset pin");
  assert.equal(ROOM_AMBIENT_7F01C0_OUTER_COUNT_START_OFF, 0x1baa8, "count start offset pin");
  assert.equal(ROOM_AMBIENT_7F01C0_PLAYER_2C_OFF, 0x2c, "player f2c offset pin");
  const view = new DataView(memory.buffer);
  const S = MEM + 0x7e00; /* v25r src scratch (distinct from v64 S/P) */
  const P = MEM + 0x7e40; /* v25r out scratch */
  const u = (v) => v >>> 0;
  const s = (v) => v | 0;
  /* count law: src {g1baac@0, g1baa8@4} -> out {count_s32@0,
     count_u32@4, entry@8}. Expected values from the model oracle. */
  const countRow = (a, b, countS32, countU32, entry) => {
    view.setUint32(S + 0, u(a), true);
    view.setUint32(S + 4, u(b), true);
    ambient7f01c0OuterCount(S, P);
    assert.equal(view.getInt32(P + 0, true), s(countS32), `count_s32(${a},${b})`);
    assert.equal(view.getUint32(P + 4, true), u(countU32), `count_u32(${a},${b})`);
    assert.equal(view.getUint32(P + 8, true), entry, `entry(${a},${b})`);
  };
  countRow(0, 0, 0, 0, 0);                    /* empty roster: no loop */
  countRow(0x100, 0, 64, 64, 1);              /* 4 players */
  countRow(0xfffffffc, 0, -1, 0xffffffff, 1); /* WIDE: negative count ENTERS (zero-only test/jz) */
  countRow(0xffffffff, 0xffffffff, 0, 0, 0);  /* zero diff */
  countRow(0x1ff, 0, 127, 127, 1);            /* WIDE: 511 >> 2 = 127 */
  countRow(0x400, 0x100, 192, 192, 1);        /* 0x300 >> 2 = 192 */
  /* continue law: src {idx@0, g1baac@4, g1baa8@8} -> out
     {count_fresh_s32@0, count_fresh_u32@4, idx_next@8, continue_loop@12}. */
  const contRow = (idx, a, b, cS32, cU32, idxNext, cont) => {
    view.setUint32(S + 0, u(idx), true);
    view.setUint32(S + 4, u(a), true);
    view.setUint32(S + 8, u(b), true);
    ambient7f01c0OuterContinue(S, P);
    assert.equal(view.getInt32(P + 0, true), s(cS32), `cont count_s32(${idx},${a},${b})`);
    assert.equal(view.getUint32(P + 4, true), u(cU32), `cont count_u32(${idx},${a},${b})`);
    assert.equal(view.getUint32(P + 8, true), u(idxNext), `cont idx_next(${idx},${a},${b})`);
    assert.equal(view.getUint32(P + 12, true), cont, `cont continue_loop(${idx},${a},${b})`);
  };
  contRow(0, 0x100, 0, 64, 64, 1, 1);          /* first iteration continues */
  contRow(63, 0x100, 0, 64, 64, 64, 0);        /* last iteration exits */
  contRow(0xffffffff, 0x100, 0, 64, 64, 0, 1); /* WIDE: idx u32 wrap */
  contRow(1, 0xfffffff8, 0, -2, 0xfffffffe, 2, 1); /* WIDE: negative fresh count, UNSIGNED jb */
  contRow(3, 0x100, 0, 64, 64, 4, 1);          /* FRESH re-read (entry count 4 -> folded would exit) */
  contRow(3, 0x4, 0, 1, 1, 4, 0);              /* roster shrank: exits */
  /* player gate law: src {player_f2c@0} -> out {skip_inner@0}. */
  const gateRow = (f2c, skip) => {
    view.setUint32(S + 0, u(f2c), true);
    ambient7f01c0OuterPlayerGate(S, P);
    assert.equal(view.getUint32(P + 0, true), skip, `skip_inner(${f2c})`);
  };
  gateRow(0, 0);          /* eligible player -> run inner loop */
  gateRow(1, 1);          /* [player+0x2c] != 0 -> outer continue */
  gateRow(0xffffffff, 1); /* WIDE: full dword, not low byte */
  gateRow(0x100, 1);      /* WIDE: full dword, not low byte */
});

test("room v25r mutation checks (helpers ABI v64)", () => {
  /* Each mutant must change behaviour AND a pinned assertion must catch
     it: the test itself FAILS on the mutated build. Source is restored
     byte-identical afterwards. */
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const P = MEM + 0x7e00;
  const S = MEM + 0x7e40;
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* (1) entry gate signed (< 0) instead of ZERO-ONLY test/jz: PE
       ENTERS with a negative count (0xfffffffc -> count -1); the
       signed mutant exits -> pinned entry==1 row fails. */
    withMutant("v25r entry gate signed instead of zero-only",
      (s) => s.replace(
        "out->entry = (count != 0) ? 1u : 0u;",
        "out->entry = (count < 0) ? 1u : 0u;",
      ),
      () => {
        const { memory, ambient7f01c0OuterCount } = loadExports();
        const view = new DataView(memory.buffer);
        view.setUint32(S + 0, 2, true);
        view.setUint32(S + 4, 0, true);
        ambient7f01c0OuterCount(S, P);
        assert.equal(view.getUint32(P + 8, true), 1,
          "positive count ENTERS the loop (test/jz zero-only gate; the "
          + "signed <0 mutant exits)");
      });
    /* (2) continue FOLDS the count (loop bound folded once) instead of
       RE-READING [Game+0x1baac]/[Game+0x1baa8] per iteration: entry
       count 4 (0x10,0) vs fresh 64 (0x100,0); idx=3 -> fresh law
       continues (4 < 64), folded exits (4 < 4) -> pinned row fails. */
    withMutant("v25r continue folds entry count (no per-iter re-read)",
      (s) => s.replace(
        "  const int32_t count = diff >> 2; /* SAR */\n  out->count_fresh_s32 = count;",
        "  const int32_t count = 4; /* FOLDED entry count */\n  out->count_fresh_s32 = count;",
      ),
      () => {
        const { memory, ambient7f01c0OuterContinue } = loadExports();
        const view = new DataView(memory.buffer);
        view.setUint32(S + 0, 3, true);       /* idx */
        view.setUint32(S + 4, 0x100, true);   /* FRESH end (64 players) */
        view.setUint32(S + 8, 0, true);       /* FRESH start */
        ambient7f01c0OuterContinue(S, P);
        assert.equal(view.getUint32(P + 12, true), 1,
          "fresh re-read 64 -> idx 4 continues (folded 4 would exit)");
      });
    /* (3) continue compare SIGNED (jl semantics) instead of UNSIGNED
       cmp/jb: fresh count -2 (u32 0xfffffffe), idx 1 -> unsigned
       2 < 0xfffffffe continues; signed 2 < -2 exits -> pinned row
       fails. */
    withMutant("v25r continue compare signed instead of unsigned jb",
      (s) => s.replace(
        "out->continue_loop = (idx_next < count_u32) ? 1u : 0u;",
        "out->continue_loop = (static_cast<int32_t>(idx_next) < out->count_fresh_s32) ? 1u : 0u;",
      ),
      () => {
        const { memory, ambient7f01c0OuterContinue } = loadExports();
        const view = new DataView(memory.buffer);
        view.setUint32(S + 0, 1, true);           /* idx */
        view.setUint32(S + 4, 0xfffffff8, true);  /* diff -8 -> count -2 */
        view.setUint32(S + 8, 0, true);
        ambient7f01c0OuterContinue(S, P);
        assert.equal(view.getUint32(P + 12, true), 1,
          "unsigned 2 < 0xfffffffe continues (signed 2 < -2 would exit)");
      });
    /* (4) player gate reads the LOW BYTE ([player+0x2c]&0xff) instead
       of the FULL dword: row player_f2c=0x100 -> PE jne fires (skip
       inner); low-byte mutant sees 0 -> pinned skip==1 row fails. */
    withMutant("v25r player gate low-byte instead of full dword",
      (s) => s.replace(
        "out->skip_inner = (src->player_f2c != 0) ? 1u : 0u;",
        "out->skip_inner = ((src->player_f2c & 0xffu) != 0) ? 1u : 0u;",
      ),
      () => {
        const { memory, ambient7f01c0OuterPlayerGate } = loadExports();
        const view = new DataView(memory.buffer);
        view.setUint32(S + 0, 0x100, true); /* low byte 0, full dword != 0 */
        ambient7f01c0OuterPlayerGate(S, P);
        assert.equal(view.getUint32(P + 0, true), 1,
          "full-dword [player+0x2c] != 0 -> skip inner (low byte would be 0)");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});

/* --------------------------------------------------------------- v25s --- */
test("room v25s payload-shape tail arg-prep (helpers ABI stays 64)", () => {
  /* FUN_007f01c0 0x7f0673..0x7f072e: the four bounds-dest shapes
     0x7f0678 (G) / 0x7f0692 (F) / 0x7f06ac (E) / 0x7f06f4 (A/D)
     assemble the exact 5-arg stdcall frame (ret 0x14, thiscall
     ecx=Game) for host 0x6fd7c0 at call site 0x7f070c. dest = the v64
     bounds enum (0 none); edx_in echoed verbatim as arg4; dest-2 tail
     arg1 = -0xf (f4 tag -14) | -6 (bit2 set) | -2 (bit2 clear);
     [Game+0x18318] stores 3/0/2/none. JS oracle vs Wasm, ABI stays
     64. */
  const { abi, memory, ambient7f01c0PayloadBounds } = loadExports();
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.match(readFileSync(header, "utf8"),
    /ISAAC_ROOM_PURE_HELPERS_ABI_VERSION = 88/);
  assert.equal(ROOM_AMBIENT_7F01C0_PAYLOAD_CALL_VA, 0x007f070c);
  assert.equal(ROOM_AMBIENT_7F01C0_PAYLOAD_HOST_VA, 0x006fd7c0);
  assert.equal(ROOM_AMBIENT_7F01C0_PAYLOAD_HOST_RET, 0x14);
  const view = new DataView(memory.buffer);
  const P = MEM + 0x8e00, S = MEM + 0x8e40;
  const run = (src) => {
    view.setUint32(S + 0, src.dest >>> 0, true);
    view.setUint32(S + 4, src.edx_in >>> 0, true);
    view.setUint32(S + 8, src.game_1831c >>> 0, true);
    view.setUint32(S + 12, src.game_18328 >>> 0, true);
    view.setInt32(S + 16, src.f4_f0 | 0, true);
    view.setUint32(S + 20, src.f4_10_38 >>> 0, true);
    ambient7f01c0PayloadBounds(S, P);
    const j = roomAmbient7f01c0PayloadBounds(src);
    const got = {
      fired: view.getUint32(P + 0, true),
      shape: view.getUint32(P + 4, true),
      arg1: view.getUint32(P + 8, true),
      arg2: view.getUint32(P + 12, true),
      arg3: view.getUint32(P + 16, true),
      arg4: view.getUint32(P + 20, true),
      arg5: view.getUint32(P + 24, true),
      store_val: view.getUint32(P + 28, true),
      store_off: view.getUint32(P + 32, true),
      call_va: view.getUint32(P + 36, true),
      host_va: view.getUint32(P + 40, true),
      cont_va: view.getUint32(P + 44, true),
      epilogue_va: view.getUint32(P + 48, true),
      ret_va: view.getUint32(P + 52, true),
    };
    assert.deepEqual(got, j, `v25s payload_bounds dest ${src.dest}`);
    return got;
  };

  /* dest 4 (0x7f0678, gate G): pushes -1,edx,0,3,-2 ; store 3. */
  const g4 = run({ dest: 4, edx_in: 0x12345678, game_1831c: 0,
    game_18328: 0, f4_f0: 0, f4_10_38: 0 });
  assert.equal(g4.fired, 1);
  assert.equal(g4.arg1 >>> 0, 0xfffffffe, "dest4 arg1 = -2");
  assert.equal(g4.arg2, 3, "dest4 arg2 = 3");
  assert.equal(g4.arg3, 0, "dest4 arg3 = 0");
  assert.equal(g4.arg4, 0x12345678, "dest4 arg4 = edx verbatim");
  assert.equal(g4.arg5 >>> 0, 0xffffffff, "dest4 arg5 = -1");
  assert.equal(g4.store_val, 3, "dest4 store 3");
  assert.equal(g4.store_off, 0x18318);
  /* wide edx echoes verbatim */
  const g4w = run({ dest: 4, edx_in: 0xffffffff, game_1831c: 0,
    game_18328: 0, f4_f0: 0, f4_10_38: 0 });
  assert.equal(g4w.arg4 >>> 0, 0xffffffff, "wide edx verbatim");

  /* dest 3 (0x7f0692, gate F): pushes -1,edx,0,0,-2 ; store 0. */
  const g3 = run({ dest: 3, edx_in: 7, game_1831c: 0, game_18328: 0,
    f4_f0: 0, f4_10_38: 0 });
  assert.equal(g3.arg1 >>> 0, 0xfffffffe, "dest3 arg1 = -2");
  assert.equal(g3.arg2, 0, "dest3 arg2 = 0");
  assert.equal(g3.store_val, 0, "dest3 store 0");

  /* dest 2 (0x7f06ac, gate E): f4 tag -14 (FULL dword) -> -0xf. */
  const eEq = run({ dest: 2, edx_in: 9, game_1831c: 0, game_18328: 0,
    f4_f0: -14, f4_10_38: 0x104 });
  assert.equal(eEq.arg1 >>> 0, 0xfffffff1, "dest2 tag -14 -> arg1 -0xf (tag wins)");
  assert.equal(eEq.arg2, 2, "dest2 arg2 = 2");
  assert.equal(eEq.store_val, 2, "dest2 store 2");
  /* bit2 of f4_10_38 (shr 2 ; test al,1) */
  const eBit = run({ dest: 2, edx_in: 9, game_1831c: 0, game_18328: 0,
    f4_f0: 0, f4_10_38: 0x104 });
  assert.equal(eBit.arg1 >>> 0, 0xfffffffa, "dest2 bit2 set -> arg1 -6");
  const eNo = run({ dest: 2, edx_in: 9, game_1831c: 0, game_18328: 0,
    f4_f0: 0, f4_10_38: 0x100 });
  assert.equal(eNo.arg1 >>> 0, 0xfffffffe, "dest2 bit2 clear -> arg1 -2");
  /* WIDE byte-gate drives: 0x1ff / 0xffffffff -> low-byte bit2 SET. */
  assert.equal(run({ dest: 2, edx_in: 9, game_1831c: 0, game_18328: 0,
    f4_f0: 0, f4_10_38: 0x1ff }).arg1 >>> 0, 0xfffffffa, "wide 0x1ff bit2 set");
  assert.equal(run({ dest: 2, edx_in: 9, game_1831c: 0, game_18328: 0,
    f4_f0: 0, f4_10_38: 0xffffffff }).arg1 >>> 0, 0xfffffffa,
    "wide 0xffffffff bit2 set");
  /* tag -14 beats the bit sub-branch (jne only on non-equal tag). */
  assert.equal(run({ dest: 2, edx_in: 9, game_1831c: 0, game_18328: 0,
    f4_f0: -14, f4_10_38: 0x100 }).arg1 >>> 0, 0xfffffff1,
    "tag -14 wins regardless of bit2");

  /* dest 1 (0x7f06f4, gates A/D): pushes -1,edx,2,[G+1831c],[G+18328];
     NO [Game+0x18318] store. */
  const g1 = run({ dest: 1, edx_in: 0xbeef, game_1831c: 0xaaaa,
    game_18328: 0xbbbb, f4_f0: 0, f4_10_38: 0 });
  assert.equal(g1.arg1, 0xbbbb, "dest1 arg1 = [Game+0x18328]");
  assert.equal(g1.arg2, 0xaaaa, "dest1 arg2 = [Game+0x1831c]");
  assert.equal(g1.arg3, 2, "dest1 arg3 = 2");
  assert.equal(g1.arg4, 0xbeef, "dest1 arg4 = edx");
  assert.equal(g1.arg5 >>> 0, 0xffffffff, "dest1 arg5 = -1");
  assert.equal(g1.store_val, 0, "dest1 no store value");
  assert.equal(g1.store_off, 0, "dest1 store_off 0 (no 0x18318 store)");

  /* dest 0: no payload call (continue 0x7f051b). */
  const g0 = run({ dest: 0, edx_in: 0x1234, game_1831c: 0, game_18328: 0,
    f4_f0: 0, f4_10_38: 0 });
  assert.equal(g0.fired, 0, "dest0 not fired");
  assert.equal(g0.shape, 0);
  assert.equal(g0.arg1, 0, "dest0 zeroed args");
  assert.equal(g0.store_off, 0);
  assert.equal(g0.cont_va, 0x007f051b);

  /* constant echo on every fired shape */
  assert.equal(g4.call_va, 0x007f070c, "call site 0x7f070c");
  assert.equal(g4.host_va, 0x006fd7c0, "host 0x6fd7c0");
  assert.equal(g4.epilogue_va, 0x007f0711, "SEH teardown 0x7f0711");
  assert.equal(g4.ret_va, 0x007f072e, "ret 0x7f072e");
});

test("room v25s mutation checks (helpers ABI stays 64)", () => {
  /* Each mutant changes behaviour AND a pinned assertion catches it: the
     test FAILS on the mutated build (loadExports rebuilds the wasm from
     the current cpp every call), then the source is restored
     byte-identical. */
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      check();
    } catch {
      threw = true;
    }
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  const P = MEM + 0x8f00, S = MEM + 0x8f40;
  const drive = (src) => {
    const { memory, ambient7f01c0PayloadBounds } = loadExports();
    const view = new DataView(memory.buffer);
    view.setUint32(S + 0, src.dest >>> 0, true);
    view.setUint32(S + 4, src.edx_in >>> 0, true);
    view.setUint32(S + 8, src.game_1831c >>> 0, true);
    view.setUint32(S + 12, src.game_18328 >>> 0, true);
    view.setInt32(S + 16, src.f4_f0 | 0, true);
    view.setUint32(S + 20, src.f4_10_38 >>> 0, true);
    ambient7f01c0PayloadBounds(S, P);
    return {
      arg1: view.getUint32(P + 8, true),
      arg2: view.getUint32(P + 12, true),
      arg4: view.getUint32(P + 20, true),
      store_val: view.getUint32(P + 28, true),
      store_off: view.getUint32(P + 32, true),
    };
  };
  try {
    /* (1) dest-4 arg1 swapped to the -1 trailing arg (order law). */
    withMutant("v25s dest-4 arg1/arg5 swapped",
      (s) => s.replace(
        "a1 = static_cast<uint32_t>(ISAAC_ROOM_AMBIENT_7F01C0_PAYLOAD_678_ARG1);",
        "a1 = static_cast<uint32_t>(ISAAC_ROOM_AMBIENT_7F01C0_PAYLOAD_ARG5); /*SWAP*/",
      ),
      () => {
        assert.equal(drive({ dest: 4, edx_in: 0x12345678, game_1831c: 0,
          game_18328: 0, f4_f0: 0, f4_10_38: 0 }).arg1 >>> 0, 0xfffffffe,
          "dest4 arg1 must be -2 (not the -1 trailing arg)");
      });
    /* (2) dest-2 bit tested at bit1 instead of bit2 (shr 2). */
    withMutant("v25s dest-2 bit shift off-by-one",
      (s) => s.replace(
        "const uint32_t bit = (src->f4_10_38 >> 2u) & 1u;",
        "const uint32_t bit = (src->f4_10_38 >> 1u) & 1u;",
      ),
      () => {
        assert.equal(drive({ dest: 2, edx_in: 9, game_1831c: 0, game_18328: 0,
          f4_f0: 0, f4_10_38: 0x104 }).arg1 >>> 0, 0xfffffffa,
          "0x104 bit2 set -> -6 (bit1 would be clear)");
      });
    /* (3) dest-2 tag -14 branch dropped (walks the bit path instead). */
    withMutant("v25s dest-2 tag eq branch dropped",
      (s) => s.replace(
        "if (src->f4_f0 == ISAAC_ROOM_AMBIENT_7F01C0_F4_F0_NEG14) {",
        "if (false) {",
      ),
      () => {
        assert.equal(drive({ dest: 2, edx_in: 9, game_1831c: 0, game_18328: 0,
          f4_f0: -14, f4_10_38: 0x104 }).arg1 >>> 0, 0xfffffff1,
          "tag -14 must select arg1 -0xf");
      });
    /* (4) dest-1 invents a 0x18318 store. */
    withMutant("v25s dest-1 store invented",
      (s) => s.replace(
        "store_val = 0u;\n      store_off = 0u; /* no store on this shape */",
        "store_val = 2u;\n      store_off = ISAAC_ROOM_AMBIENT_7F01C0_GAME_18318_OFF;",
      ),
      () => {
        const r = drive({ dest: 1, edx_in: 7, game_1831c: 0xaaaa,
          game_18328: 0xbbbb, f4_f0: 0, f4_10_38: 0 });
        assert.equal(r.store_val, 0, "dest1 must NOT store 0x18318");
        assert.equal(r.store_off, 0, "dest1 store_off 0");
      });
    /* (5) edx folded to zero instead of echoed verbatim (dest 4). */
    withMutant("v25s edx folded to zero",
      (s) => s.replace(
        "a2 = ISAAC_ROOM_AMBIENT_7F01C0_PAYLOAD_678_STORE;\n      a3 = 0u;\n      a4 = edx;",
        "a2 = ISAAC_ROOM_AMBIENT_7F01C0_PAYLOAD_678_STORE;\n      a3 = 0u;\n      a4 = 0u;",
      ),
      () => {
        assert.equal(drive({ dest: 4, edx_in: 0x12345678, game_1831c: 0,
          game_18328: 0, f4_f0: 0, f4_10_38: 0 }).arg4, 0x12345678,
          "arg4 must echo host edx verbatim");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});

/* -------------------- v65r: Game::GetPlayer 0x00417870 BODY ------------ */
test("room v65r get player 417870 body (helpers ABI v64)", () => {
  /* Game::GetPlayer: thiscall (ecx=Game), ONE stack arg (index), ret 4.
     count = SAR((u32)([Game+0x1baac]-[Game+0x1baa8]),2); empty (count==0)
     -> HOST fatal 0xa112c0 (args 0x10 / 0xb7e6bc) then RE-READ
     begin/end (defect-class-1 recapture: post-call values feed count_used
     and the slot load); (u32)index < (u32)count_used ? [begin_used+
     index*4] : [begin_used] (0x4178b4 jae UNSIGNED). ret
     0x4178bd / 0x4178c6. Pure laws + body plan; host fatal leaf stays. */
  const { abi, memory,
    getPlayer417870Va, getPlayer417870RetVa, getPlayer417870ClampRetVa,
    getPlayer417870GameBeginOff, getPlayer417870GameEndOff,
    getPlayer417870FatalVa, getPlayer417870FatalArg0,
    getPlayer417870FatalArg1Va,
    getPlayer417870Count, getPlayer417870Empty, getPlayer417870InBounds,
    getPlayer417870SlotAddr, getPlayer417870Plan } = loadExports();
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  const h = readFileSync(header, "utf8");
  assert.match(h, /v65r: Game::GetPlayer 0x00417870 BODY/);
  assert.match(h, /ISAAC_ROOM_GET_PLAYER_417870_VA = 0x00417870u/);
  assert.match(h, /ISAAC_ROOM_GET_PLAYER_417870_FATAL_VA = 0x00a112c0u/);
  assert.match(h, /IsaacRoomGetPlayer417870Out/);
  assert.match(h, /isaac_room_get_player_417870_plan/);
  /* constants */
  assert.equal(getPlayer417870Va() >>> 0, ROOM_GET_PLAYER_417870_VA);
  assert.equal(getPlayer417870RetVa() >>> 0, ROOM_GET_PLAYER_417870_RET_VA);
  assert.equal(getPlayer417870ClampRetVa() >>> 0,
    ROOM_GET_PLAYER_417870_CLAMP_RET_VA);
  assert.equal(getPlayer417870GameBeginOff() >>> 0,
    ROOM_GET_PLAYER_417870_GAME_BEGIN_OFF);
  assert.equal(getPlayer417870GameEndOff() >>> 0,
    ROOM_GET_PLAYER_417870_GAME_END_OFF);
  assert.equal(getPlayer417870FatalVa() >>> 0, ROOM_GET_PLAYER_417870_FATAL_VA);
  assert.equal(getPlayer417870FatalArg0() >>> 0, ROOM_GET_PLAYER_417870_FATAL_ARG0);
  assert.equal(getPlayer417870FatalArg1Va() >>> 0,
    ROOM_GET_PLAYER_417870_FATAL_ARG1_VA);
  /* count: u32 wrap + SAR */
  assert.equal(getPlayer417870Count(0x1000, 0x1010),
    roomGetPlayer417870Count(0x1000, 0x1010));
  assert.equal(getPlayer417870Count(0x1000, 0x1010), 4,
    "4 slots: (0x10)>>2");
  assert.equal(getPlayer417870Count(0x80000000, 0x4) | 0,
    roomGetPlayer417870Count(0x80000000, 0x4) | 0,
    "u32 wrap then SAR matches oracle");
  assert.equal(getPlayer417870Count(0x1000, 0x1000), 0, "empty list");
  /* empty gate (test/jne: fatal iff count==0) */
  assert.equal(getPlayer417870Empty(0), roomGetPlayer417870Empty(0));
  assert.equal(getPlayer417870Empty(0), 1);
  assert.equal(getPlayer417870Empty(4), roomGetPlayer417870Empty(4));
  assert.equal(getPlayer417870Empty(4), 0);
  /* in_bounds UNSIGNED (jae): WIDE drove byte/word gates */
  assert.equal(getPlayer417870InBounds(0, 4), roomGetPlayer417870InBounds(0, 4));
  assert.equal(getPlayer417870InBounds(0, 4), 1);
  assert.equal(getPlayer417870InBounds(4, 4),
    roomGetPlayer417870InBounds(4, 4));
  assert.equal(getPlayer417870InBounds(4, 4), 0, "index==count clamps");
  assert.equal(getPlayer417870InBounds(0xffffffff, 4),
    roomGetPlayer417870InBounds(0xffffffff, 4));
  assert.equal(getPlayer417870InBounds(0xffffffff, 4), 0,
    "0xffffffff unsigned >= count -> clamp");
  assert.equal(getPlayer417870InBounds(0x100, 4),
    roomGetPlayer417870InBounds(0x100, 4));
  assert.equal(getPlayer417870InBounds(0x100, 4), 0);
  assert.equal(getPlayer417870InBounds(0x1ff, 4),
    roomGetPlayer417870InBounds(0x1ff, 4));
  assert.equal(getPlayer417870InBounds(0x1ff, 4), 0);
  assert.equal(getPlayer417870InBounds(0x100, -1),
    roomGetPlayer417870InBounds(0x100, -1));
  assert.equal(getPlayer417870InBounds(0x100, -1), 1,
    "count -1 as u32 is huge -> in bounds");
  /* slot_addr: [begin+index*4] in-bounds; [begin] clamp */
  assert.equal(getPlayer417870SlotAddr(0x1000, 1, 4),
    roomGetPlayer417870SlotAddr(0x1000, 1, 4));
  assert.equal(getPlayer417870SlotAddr(0x1000, 1, 4), 0x1004);
  assert.equal(getPlayer417870SlotAddr(0x1000, 4, 4),
    roomGetPlayer417870SlotAddr(0x1000, 4, 4));
  assert.equal(getPlayer417870SlotAddr(0x1000, 4, 4), 0x1000, "clamp");
  assert.equal(getPlayer417870SlotAddr(0x1000, 0xffffffff, 4),
    roomGetPlayer417870SlotAddr(0x1000, 0xffffffff, 4));
  assert.equal(getPlayer417870SlotAddr(0x1000, 0xffffffff, 4), 0x1000,
    "0xffffffff clamps to slot 0");
  /* plan: non-empty path keeps ORIGINAL begin/end (no re-read site) */
  const view = new DataView(memory.buffer);
  const OUT = MEM + 0x1f000;
  getPlayer417870Plan(0x1000, 0x1010, 2, 0x9000, 0x9020, 0xaa, 0xbb, OUT);
  const rd = (o) => view.getUint32(OUT + o, true);
  assert.equal(rd(0), roomGetPlayer417870Plan({ begin: 0x1000, end: 0x1010,
    index: 2, re_read_begin: 0x9000, re_read_end: 0x9020,
    slot0_sample: 0xaa, slot_idx_sample: 0xbb }).count_pre);
  assert.equal(rd(0), 4, "count_pre");
  assert.equal(rd(4), 0, "empty");
  assert.equal(rd(8), 0, "host_fatal");
  assert.equal(rd(12), 0x1000, "begin_used = original (no fatal)");
  assert.equal(rd(16), 0x1010, "end_used = original");
  assert.equal(rd(20), 4, "count_used");
  assert.equal(rd(24), 1, "in_bounds");
  assert.equal(rd(28), 0x1008, "slot_addr begin+2*4");
  assert.equal(rd(32), 0xbb, "result = slot_idx_sample");
  assert.equal(rd(36), 1, "result_known");
  assert.equal(rd(40), ROOM_GET_PLAYER_417870_RET_VA, "ret_va in-bounds");
  assert.equal(rd(44), ROOM_GET_PLAYER_417870_VA, "head_va");
  assert.equal(rd(48), ROOM_GET_PLAYER_417870_CLAMP_RET_VA, "clamp_ret_va");
  assert.equal(rd(52), ROOM_GET_PLAYER_417870_FATAL_VA, "fatal_va");
  /* plan: EMPTY path RE-READS begin/end (defect-class-1 recapture). */
  getPlayer417870Plan(0x1000, 0x1000, 1, 0x9000, 0x9008, 0xaa, 0xbb, OUT);
  assert.equal(rd(0), 0, "count_pre 0");
  assert.equal(rd(4), 1, "empty");
  assert.equal(rd(8), 1, "host_fatal");
  assert.equal(rd(12), 0x9000, "begin_used = RE-READ (post-fatal)");
  assert.equal(rd(16), 0x9008, "end_used = RE-READ");
  assert.equal(rd(20), 2, "count_used re-derived from recapture");
  assert.equal(rd(24), 1, "in_bounds");
  assert.equal(rd(28), 0x9004, "slot_addr from recaptured begin");
  assert.equal(rd(32), 0xbb, "result");
  /* plan: EMPTY + clamp (0xffffffff >= count_used) */
  getPlayer417870Plan(0x1000, 0x1000, 0xffffffff, 0x9000, 0x9008, 0xaa,
    0xbb, OUT);
  assert.equal(rd(24), 0, "0xffffffff clamps");
  assert.equal(rd(28), 0x9000, "clamp reads [recaptured begin]");
  assert.equal(rd(32), 0xaa, "result = slot0_sample on clamp");
  assert.equal(rd(40), ROOM_GET_PLAYER_417870_CLAMP_RET_VA, "clamp ret_va");
});

test("room v65r get player 417870 mutants (3 caught)", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      check();
    } catch {
      threw = true;
    }
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* (1) SIGNED compare instead of UNSIGNED jae: 0xffffffff < 4 signed
       passes, PE unsigned clamps. */
    withMutant("v65r signed in_bounds",
      (s) => s.replace(
        "return index < static_cast<uint32_t>(count) ? 1 : 0;",
        "return static_cast<int32_t>(index) < count ? 1 : 0;",
      ),
      () => {
        const { getPlayer417870InBounds } = loadExports();
        assert.equal(getPlayer417870InBounds(0xffffffff, 4), 0,
          "0xffffffff must NOT be in-bounds (unsigned jae)");
      });
    /* (2) count LSR instead of SAR: 0x80000000..0x4 wraps to 0x80000004;
       SAR -> 0xE0000001, LSR -> 0x20000001. */
    withMutant("v65r count LSR",
      (s) => s.replace(
        "return static_cast<int32_t>(end - begin) >> 2;",
        "return static_cast<int32_t>((end - begin) >> 2);",
      ),
      () => {
        const { getPlayer417870Count } = loadExports();
        assert.equal(getPlayer417870Count(0x80000000, 0x4) | 0,
          0xe0000001 | 0, "SAR after u32 wrap");
      });
    /* (3) plan FOLDS pre-call begin/end on the EMPTY path (defect-1:
       must recapture post-fatal reads). */
    withMutant("v65r plan folds pre-call reads",
      (s) => s.replace(
        "const uint32_t begin_used = empty != 0 ? re_read_begin : begin;\n  const uint32_t end_used = empty != 0 ? re_read_end : end;",
        "const uint32_t begin_used = begin;\n  const uint32_t end_used = end;",
      ),
      () => {
        const { memory, getPlayer417870Plan } = loadExports();
        const view = new DataView(memory.buffer);
        const OUT = MEM + 0x1f000;
        getPlayer417870Plan(0x1000, 0x1000, 1, 0x9000, 0x9008, 0xaa, 0xbb,
          OUT);
        assert.equal(view.getUint32(OUT + 12, true), 0x9000,
          "empty path must use RE-READ begin (post-fatal)");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});
