test("room v25q range-hit tail 7f0544 (helpers ABI 64)", () => {
  /* FUN_007f01c0 range-hit tail (PE 0x7f0544..0x7f0673, reached from the
     v64 tail-decision `ja 0x7f0544` when 25.0f > dist): head host
     0x705ee0(lane) ret 4; clamp(edi,-1,7) SIGNED -> [Game+0x18318];
     slot.f394 == -1 FULL-dword gate; fs:[0x2c] TLS check (s32
     [0xc8108c] > (s32)[[fs:0x2c]+0xc], jg SIGNED -> host 0x7f072f);
     sel gate ((u32)[Game+0x1830c] >= 3 jae UNSIGNED ? 0xc810a0 :
     Game+0x16c8c, *sel == 0 FULL dword); devil/angel 0x7499a0 arg laws
     (sete/setne FULL dword f160==0xf) + [0x2654c] self-store +
     [0x26548] |= 1|0x20; f394<=-100 / >-100 SIGNED split (jg): shape A
     (GetRoomByIdx 0x740bc0 ret 8) -> 5-arg 0x6fd7c0 (room_f00, lane,
     cmov, player, room_f0c) with cmov = (POST-call f394 == -100) ? 0x12
     : 0; shape B = 5 slots (f394_split, lane, 0, player, -1 dangling
     hoisted push); [Game+0x68d70] = 0 byte store (suppressed on the
     TLS-fail path). JS oracle vs Wasm for every law. */
  const { abi, memory,
    rangeHit7f0544Va, rangeHit7f0544Eval } = loadExports();
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.match(readFileSync(header, "utf8"),
    /ISAAC_ROOM_PURE_HELPERS_ABI_VERSION = 88/);
  assert.equal(rangeHit7f0544Va() >>> 0, ROOM_RANGE_HIT_7F0544_VA);
  assert.equal(ROOM_RANGE_HIT_7F0544_VA, 0x7f0544);
  const view = new DataView(memory.buffer);
  const P = MEM + 0x8c00;
  const S = MEM + 0x8d00;
  const evalH = (s) => {
    view.setUint32(S + 0, s.lane >>> 0, true);
    view.setInt32(S + 4, s.f394_gate | 0, true);
    view.setInt32(S + 8, s.f394_split | 0, true);
    view.setInt32(S + 12, s.f394_post | 0, true);
    view.setUint32(S + 16, s.slot_f160 >>> 0, true);
    view.setUint32(S + 20, s.player >>> 0, true);
    view.setUint32(S + 24, s.game_1830c >>> 0, true);
    view.setUint32(S + 28, s.sel_a >>> 0, true);
    view.setUint32(S + 32, s.sel_b >>> 0, true);
    view.setInt32(S + 36, s.tls_global | 0, true);
    view.setInt32(S + 40, s.tls_peb | 0, true);
    view.setUint32(S + 44, s.room_f00 >>> 0, true);
    view.setUint32(S + 48, s.room_f0c >>> 0, true);
    rangeHit7f0544Eval(S, P);
    const wm = {
      clamp_value: view.getInt32(P + 0, true),
      gate_minus1: view.getUint32(P + 4, true),
      tls_fail: view.getUint32(P + 8, true),
      fail_va: view.getUint32(P + 12, true),
      sel_low: view.getUint32(P + 16, true),
      sel_zero: view.getUint32(P + 20, true),
      devil_fire: view.getUint32(P + 24, true),
      force_angel: view.getUint32(P + 28, true),
      force_devil: view.getUint32(P + 32, true),
      devil_va: view.getUint32(P + 36, true),
      st2654c_flag: view.getUint32(P + 40, true),
      st26548_mask: view.getUint32(P + 44, true),
      split_direct: view.getUint32(P + 48, true),
      shape_a: view.getUint32(P + 52, true),
      getroom_va: view.getUint32(P + 56, true),
      getroom_arg1: view.getUint32(P + 60, true),
      getroom_arg2: view.getUint32(P + 64, true),
      cmov_arg3: view.getUint32(P + 68, true),
      payload_va: view.getUint32(P + 72, true),
      payload_a1: view.getUint32(P + 76, true),
      payload_a2: view.getUint32(P + 80, true),
      payload_a3: view.getUint32(P + 84, true),
      payload_a4: view.getUint32(P + 88, true),
      payload_a5: view.getUint32(P + 92, true),
      payload_count: view.getUint32(P + 96, true),
      st68d70_flag: view.getUint32(P + 100, true),
      head_va: view.getUint32(P + 104, true),
      head_arg: view.getUint32(P + 108, true),
      end_va: view.getUint32(P + 112, true),
      epilogue_va: view.getUint32(P + 116, true),
    };
    const j = roomRangeHit7f0544Eval(s);
    assert.deepEqual(wm, j, `v25q ${JSON.stringify(s)}`);
    return wm;
  };
  const base = {
    lane: 3, f394_gate: -1, f394_split: -150, f394_post: -100,
    slot_f160: 0xf, player: 0x1234, game_1830c: 2, sel_a: 0, sel_b: 0,
    tls_global: 0, tls_peb: 0, room_f00: 0xaaaa, room_f0c: 0xbbbb,
  };
  /* ---- clamp (SIGNED jle/jl) ---- */
  assert.equal(evalH({ ...base, lane: 3 }).clamp_value, 3, "clamp 3");
  assert.equal(evalH({ ...base, lane: 0 }).clamp_value, 0, "clamp 0");
  assert.equal(evalH({ ...base, lane: 0xffffffff }).clamp_value, -1,
    "clamp s32 -1 floor");
  assert.equal(evalH({ ...base, lane: 0xfffffffe }).clamp_value, -1,
    "clamp -2 -> -1 (SIGNED jle)");
  assert.equal(evalH({ ...base, lane: 7 }).clamp_value, 7, "clamp 7");
  assert.equal(evalH({ ...base, lane: 8 }).clamp_value, 7,
    "clamp 8 -> 7 (SIGNED jl)");
  assert.equal(evalH({ ...base, lane: 0x100 }).clamp_value, 7,
    "clamp 0x100 -> 7 (WIDE)");
  /* ---- f394 gate (FULL dword) ---- */
  assert.equal(evalH(base).gate_minus1, 1, "gate -1");
  assert.equal(evalH({ ...base, f394_gate: 0 }).gate_minus1, 0, "gate 0");
  assert.equal(evalH({ ...base, f394_gate: 0xffffffff }).gate_minus1, 1,
    "gate 0xffffffff == -1");
  /* ---- TLS check (SIGNED jg) ---- */
  assert.equal(evalH(base).tls_fail, 0, "tls equal 0 no fail");
  assert.equal(evalH({ ...base, tls_global: 1, tls_peb: 0 }).tls_fail, 1,
    "tls 1 > 0 fail");
  assert.equal(evalH({ ...base, tls_global: 0x7fffffff, tls_peb: 0x80000000 })
    .tls_fail, 1, "INT_MAX > INT_MIN signed fail");
  assert.equal(evalH({ ...base, tls_global: 0x80000000, tls_peb: 0x7fffffff })
    .tls_fail, 0, "INT_MIN > INT_MAX false (SIGNED)");
  assert.equal(evalH({ ...base, tls_global: 0xffffffff, tls_peb: 0 }).tls_fail,
    0, "s32 -1 > 0 false (SIGNED)");
  assert.equal(evalH(base).fail_va, ROOM_RANGE_HIT_7F0544_FAIL_VA);
  /* ---- sel gate (UNSIGNED jae >= 3; *sel == 0 FULL dword) ---- */
  assert.equal(evalH(base).sel_low, 0, "1830c 2 < 3 -> low");
  assert.equal(evalH({ ...base, game_1830c: 3, sel_a: 0, sel_b: 9 })
    .sel_zero, 1, "1830c 3 -> sel_a (0xc810a0) zero");
  assert.equal(evalH({ ...base, game_1830c: 2, sel_a: 9, sel_b: 0 })
    .sel_zero, 1, "1830c 2 -> sel_b (16c8c) zero");
  assert.equal(evalH({ ...base, game_1830c: 0x100, sel_a: 0, sel_b: 9 })
    .sel_zero, 1, "1830c 0x100 -> sel_a (UNSIGNED jae)");
  assert.equal(evalH({ ...base, game_1830c: 0xffffffff, sel_a: 0, sel_b: 9 })
    .sel_zero, 1, "1830c u32 max -> sel_a (UNSIGNED)");
  assert.equal(evalH({ ...base, game_1830c: 3, sel_a: 7, sel_b: 0 })
    .sel_zero, 0, "sel_a nonzero blocks");
  assert.equal(evalH({ ...base, game_1830c: 2, sel_a: 0, sel_b: 7 })
    .sel_zero, 0, "sel_b nonzero blocks");
  /* ---- devil/angel block ---- */
  assert.equal(evalH(base).devil_fire, 1, "gate+tls+sel all pass");
  assert.equal(evalH({ ...base, f394_gate: 0 }).devil_fire, 0,
    "gate fail skips devil");
  assert.equal(evalH({ ...base, tls_global: 1, tls_peb: 0 }).devil_fire, 0,
    "tls fail blocks devil");
  assert.equal(evalH({ ...base, game_1830c: 3, sel_a: 5 }).devil_fire, 0,
    "sel nonzero blocks devil");
  assert.equal(evalH(base).force_angel, 1, "f160 0xf -> angel");
  assert.equal(evalH(base).force_devil, 0, "not devil");
  assert.equal(evalH({ ...base, slot_f160: 0x10 }).force_angel, 0,
    "f160 != 0xf");
  assert.equal(evalH({ ...base, slot_f160: 0x10 }).force_devil, 1,
    "f160 != 0xf -> devil");
  assert.equal(evalH({ ...base, slot_f160: 0x100 }).force_angel, 0,
    "f160 0x100 (FULL dword, not byte)");
  assert.equal(evalH({ ...base, slot_f160: 0x100 }).force_devil, 1,
    "f160 0x100 != 0xf");
  assert.equal(evalH(base).devil_va, ROOM_RANGE_HIT_7F0544_HOST_7499A0_VA);
  assert.equal(evalH(base).st2654c_flag, 1, "self-store fired");
  assert.equal(evalH({ ...base, f394_gate: 0 }).st2654c_flag, 0,
    "no self-store outside devil block");
  assert.equal(evalH(base).st26548_mask, ROOM_RANGE_HIT_7F0544_OR_MASK_1,
    "angel -> |1");
  assert.equal(evalH({ ...base, slot_f160: 0x10 }).st26548_mask,
    ROOM_RANGE_HIT_7F0544_OR_MASK_20, "devil -> |0x20");
  assert.equal(evalH({ ...base, f394_gate: 0 }).st26548_mask, 0,
    "no OR store outside devil block");
  /* ---- f394 split (SIGNED jg -100) ---- */
  assert.equal(evalH(base).shape_a, 1, "-150 <= -100 -> shape A");
  assert.equal(evalH({ ...base, f394_split: -100 }).shape_a, 1,
    "-100 == split -> shape A");
  assert.equal(evalH({ ...base, f394_split: -99 }).shape_a, 0,
    "-99 > -100 -> shape B");
  assert.equal(evalH({ ...base, f394_split: 0xffffffff }).shape_a, 0,
    "s32 -1 > -100 -> shape B (SIGNED)");
  assert.equal(evalH({ ...base, f394_split: 0xffffff9c }).shape_a, 1,
    "s32 -100 exact -> shape A (WIDE)");
  assert.equal(evalH({ ...base, f394_split: 0xffffff9b }).shape_a, 1,
    "s32 -101 <= -100 -> shape A");
  /* ---- GetRoomByIdx args (ret 8) ---- */
  assert.equal(evalH(base).getroom_va, ROOM_RANGE_HIT_7F0544_HOST_740BC0_VA);
  assert.equal(evalH(base).getroom_arg1, 0xffffff6a, "-150 bits");
  assert.equal(evalH(base).getroom_arg2, 0xffffffff, "-1 hoisted");
  /* ---- cmov: POST-call f394 (defect-class-1) ---- */
  assert.equal(evalH(base).cmov_arg3, ROOM_RANGE_HIT_7F0544_CMOV_TRUE,
    "post == -100 -> 0x12");
  assert.equal(evalH({ ...base, f394_post: -99 }).cmov_arg3, 0,
    "post != -100 -> 0 (POST, not split!)");
  assert.equal(evalH({ ...base, f394_split: -150, f394_post: -50 })
    .cmov_arg3, 0, "split -150 post -50 -> 0");
  assert.equal(evalH({ ...base, f394_split: -99, f394_post: -100 })
    .cmov_arg3, ROOM_RANGE_HIT_7F0544_CMOV_TRUE,
    "split -99 (shape B) post -100 -> cmov still 0x12 (value law)");
  /* ---- payload shapes ---- */
  assert.equal(evalH(base).payload_va, ROOM_RANGE_HIT_7F0544_HOST_6FD7C0_VA);
  assert.equal(evalH(base).payload_count, ROOM_RANGE_HIT_7F0544_PAYLOAD_ARITY);
  assert.equal(evalH(base).payload_a1, 0xaaaa, "shape A a1 room_f00");
  assert.equal(evalH(base).payload_a2, 3, "shape A a2 lane3");
  assert.equal(evalH(base).payload_a3, 0x12, "shape A a3 cmov");
  assert.equal(evalH(base).payload_a4, 0x1234, "shape A a4 player");
  assert.equal(evalH(base).payload_a5, 0xbbbb, "shape A a5 room_f0c");
  assert.equal(evalH({ ...base, lane: 0x104 }).payload_a2, 0,
    "lane 0x104 & 3 = 0 (lane3 masked in body)");
  const b = evalH({ ...base, f394_split: -99, lane: 0x103,
    f394_post: -99 });
  assert.equal(b.shape_a, 0, "shape B");
  assert.equal(b.payload_a1, 0xffffff9d, "shape B a1 = -99 bits");
  assert.equal(b.payload_a2, 3, "shape B a2 lane 0x103&3");
  assert.equal(b.payload_a3, 0, "shape B a3 0");
  assert.equal(b.payload_a4, 0x1234, "shape B a4 player");
  assert.equal(b.payload_a5, 0xffffffff, "shape B a5 dangling -1");
  /* ---- tail 68d70 store ---- */
  assert.equal(evalH(base).st68d70_flag, 1, "store fires shape A");
  assert.equal(evalH({ ...base, f394_split: -99 }).st68d70_flag, 1,
    "store fires shape B");
  assert.equal(evalH({ ...base, tls_global: 1, tls_peb: 0 }).st68d70_flag, 0,
    "TLS fail path suppresses the store");
  assert.equal(evalH({ ...base, f394_gate: 0 }).st68d70_flag, 1,
    "gate fail still fires store (join path)");
  /* ---- head + VA pins ---- */
  assert.equal(evalH(base).head_va, ROOM_RANGE_HIT_7F0544_HOST_705EE0_VA);
  assert.equal(evalH(base).head_arg, 3, "head arg = FULL lane");
  assert.equal(evalH({ ...base, lane: 0x100 }).head_arg, 0x100,
    "head arg FULL lane (not masked)");
  assert.equal(evalH(base).end_va, ROOM_RANGE_HIT_7F0544_END_VA);
  assert.equal(evalH(base).epilogue_va, ROOM_RANGE_HIT_7F0544_EPILOGUE_VA);
  assert.equal(evalH(base).fail_va, ROOM_RANGE_HIT_7F0544_FAIL_VA);
  /* ---- randomized differential (LCG high bits) ---- */
  let lcg = 0x41c64e6d;
  const rnd = () => ((lcg = (Math.imul(lcg, 1664525) + 1013904223) >>> 0), lcg);
  const hi = (n) => Math.floor(rnd() / 2 ** 23) % n;
  for (let k = 0; k < 200; k++) {
    const s = {
      lane: [0, 1, 2, 3, 4, 5, 6, 7, 0x100, 0x1ff, 0xffffffff][hi(11)],
      f394_gate: [0, -1, 5, -150, 0xffffffff, 0xffffff9c][hi(6)],
      f394_split: [-101, -100, -99, -150, 0, 0xffffffff, 0xffffff9b][hi(7)],
      f394_post: [-100, -99, 0, -150, 0xffffffff][hi(5)],
      slot_f160: [0, 0xf, 0x10, 0x100, 0xffffffff][hi(5)],
      player: rnd() >>> 0,
      game_1830c: [0, 1, 2, 3, 4, 0x100, 0xffffffff][hi(7)],
      sel_a: [0, 1, 7, 0x100, 0xffffffff][hi(5)],
      sel_b: [0, 1, 7, 0x100, 0xffffffff][hi(5)],
      tls_global: [0, 1, -1, 0x7fffffff, 0x80000000, 0xffffffff][hi(6)],
      tls_peb: [0, 1, -1, 0x7fffffff, 0x80000000, 0xffffffff][hi(6)],
      room_f00: rnd() >>> 0,
      room_f0c: rnd() >>> 0,
    };
    evalH(s);
  }
});

test("room v25q mutation checks (helpers ABI 64)", () => {
  /* Each mutant must change behaviour AND a pinned assertion must catch
     it: the test itself FAILS on the mutated build. */
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const P = MEM + 0x8c00;
  const S = MEM + 0x8d00;
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* (1) cmov folds the PRE-call split value instead of the POST-call
       re-read (defect-class-1): split -150 (shape A), post -50 must
       give cmov 0; a fold would give 0x12. */
    withMutant("v25q cmov folds pre-call f394",
      (s) => s.replace(
        "const uint32_t cmov_arg3 =\n      (src->f394_post == ISAAC_ROOM_RANGE_HIT_7F0544_SPLIT)",
        "const uint32_t cmov_arg3 =\n      (src->f394_split == ISAAC_ROOM_RANGE_HIT_7F0544_SPLIT)",
      ),
      () => {
        const { memory, rangeHit7f0544Eval } = loadExports();
        const view = new DataView(memory.buffer);
        view.setUint32(S + 0, 3, true);
        view.setInt32(S + 4, -1, true);
        view.setInt32(S + 8, -150, true);   /* f394_split */
        view.setInt32(S + 12, -100, true);  /* f394_post (POST-call):
                                               == SPLIT -> correct cmov
                                               0x12; the pre-call fold
                                               reads -150 -> 0, so the
                                               mutant DIVERGES here */
        view.setUint32(S + 16, 0xf, true);
        view.setUint32(S + 20, 0x1234, true);
        view.setUint32(S + 24, 2, true);
        view.setUint32(S + 28, 0, true);
        view.setUint32(S + 32, 0, true);
        view.setInt32(S + 36, 0, true);
        view.setInt32(S + 40, 0, true);
        view.setUint32(S + 44, 0xaaaa, true);
        view.setUint32(S + 48, 0xbbbb, true);
        rangeHit7f0544Eval(S, P);
        assert.equal(view.getUint32(P + 68, true), 0x12,
          "post -100 == -100 -> cmov 0x12 (POST-call value; a pre-call "
          + "fold of -150 gives 0)");
      });
    /* (2) cmov true-value: 0x12 vs 0x13. */
    withMutant("v25q cmov magic 0x12 -> 0x13",
      (s) => s.replace(
        "static_cast<uint32_t>(ISAAC_ROOM_RANGE_HIT_7F0544_CMOV_TRUE)",
        "0x13u",
      ),
      () => {
        const { memory, rangeHit7f0544Eval } = loadExports();
        const view = new DataView(memory.buffer);
        view.setUint32(S + 0, 3, true);
        view.setInt32(S + 4, -1, true);
        view.setInt32(S + 8, -150, true);
        view.setInt32(S + 12, -100, true);  /* post == -100 -> 0x12 */
        view.setUint32(S + 16, 0xf, true);
        view.setUint32(S + 20, 0x1234, true);
        view.setUint32(S + 24, 2, true);
        view.setUint32(S + 28, 0, true);
        view.setUint32(S + 32, 0, true);
        view.setInt32(S + 36, 0, true);
        view.setInt32(S + 40, 0, true);
        view.setUint32(S + 44, 0xaaaa, true);
        view.setUint32(S + 48, 0xbbbb, true);
        rangeHit7f0544Eval(S, P);
        assert.equal(view.getUint32(P + 68, true), 0x12,
          "cmov true = 0x12 (PE mov edx,0x12)");
      });
    /* (3) shape B drops the dangling -1 arg5 (uses 0): payload_a5 must
       be 0xffffffff, not 0. */
    withMutant("v25q shape B arg5 drops dangling -1",
      (s) => s.replace(
        "out->payload_a5 = 0xffffffffu;       /* dangling hoisted push */",
        "out->payload_a5 = 0u;                /* dangling hoisted push */",
      ),
      () => {
        const { memory, rangeHit7f0544Eval } = loadExports();
        const view = new DataView(memory.buffer);
        view.setUint32(S + 0, 1, true);
        view.setInt32(S + 4, 0, true);
        view.setInt32(S + 8, -99, true);    /* > -100 -> shape B */
        view.setInt32(S + 12, 0, true);
        view.setUint32(S + 16, 0, true);
        view.setUint32(S + 20, 0x1234, true);
        view.setUint32(S + 24, 2, true);
        view.setUint32(S + 28, 0, true);
        view.setUint32(S + 32, 0, true);
        view.setInt32(S + 36, 0, true);
        view.setInt32(S + 40, 0, true);
        view.setUint32(S + 44, 0, true);
        view.setUint32(S + 48, 0, true);
        rangeHit7f0544Eval(S, P);
        assert.equal(view.getUint32(P + 92, true), 0xffffffff,
          "shape B arg5 = hoisted -1 (0xffffffff)");
      });
    /* (4) clamp floor: == -1 instead of <= -1 (jle SIGNED): s32 -2
       must clamp to -1, the mutant keeps -2. */
    withMutant("v25q clamp floor == instead of <=",
      (s) => s.replace(
        "if (lane_s <= ISAAC_ROOM_RANGE_HIT_7F0544_CLAMP_MIN) {",
        "if (lane_s == ISAAC_ROOM_RANGE_HIT_7F0544_CLAMP_MIN) {",
      ),
      () => {
        const { memory, rangeHit7f0544Eval } = loadExports();
        const view = new DataView(memory.buffer);
        view.setUint32(S + 0, 0xfffffffe, true); /* s32 -2 */
        view.setInt32(S + 4, 0, true);
        view.setInt32(S + 8, 0, true);
        view.setInt32(S + 12, 0, true);
        view.setUint32(S + 16, 0, true);
        view.setUint32(S + 20, 0, true);
        view.setUint32(S + 24, 0, true);
        view.setUint32(S + 28, 0, true);
        view.setUint32(S + 32, 0, true);
        view.setInt32(S + 36, 0, true);
        view.setInt32(S + 40, 0, true);
        view.setUint32(S + 44, 0, true);
        view.setUint32(S + 48, 0, true);
        rangeHit7f0544Eval(S, P);
        assert.equal(view.getInt32(P + 0, true), -1,
          "lane s32 -2 -> clamp -1 (jle SIGNED floor)");
      });
    /* (5) TLS compare UNSIGNED (jb/jae instead of jg): 0xffffffff vs 0
       must NOT fail (s32 -1 > 0 false). */
    withMutant("v25q TLS compare unsigned",
      (s) => s.replace(
        "const uint32_t tls_fail =\n      (src->tls_global > src->tls_peb) ? 1u : 0u;",
        "const uint32_t tls_fail =\n      (static_cast<uint32_t>(src->tls_global) > static_cast<uint32_t>(src->tls_peb)) ? 1u : 0u;",
      ),
      () => {
        const { memory, rangeHit7f0544Eval } = loadExports();
        const view = new DataView(memory.buffer);
        view.setUint32(S + 0, 3, true);
        view.setInt32(S + 4, -1, true);
        view.setInt32(S + 8, -150, true);
        view.setInt32(S + 12, -100, true);
        view.setUint32(S + 16, 0xf, true);
        view.setUint32(S + 20, 0x1234, true);
        view.setUint32(S + 24, 2, true);
        view.setUint32(S + 28, 0, true);
        view.setUint32(S + 32, 0, true);
        view.setInt32(S + 36, -1, true);    /* 0xffffffff */
        view.setInt32(S + 40, 0, true);
        view.setUint32(S + 44, 0xaaaa, true);
        view.setUint32(S + 48, 0xbbbb, true);
        rangeHit7f0544Eval(S, P);
        assert.equal(view.getUint32(P + 8, true), 0,
          "TLS jg SIGNED: s32 -1 > 0 false");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});

/* ----------------------------------------------------------------- v25t - */
test("room v25t TLS-fail re-entry 7f072f (helpers ABI 67)", () => {
  /* FUN_007f01c0 TLS-fail re-entry (PE 0x7f072f..0x7f077b; entered from
     the v25q TLS check `jg 0x7f072f` @0x7f0598): push &[0xc8108c];
     call host 0xaef29d (TLS claim/sync); RE-CHECK 0x7f073c
     cmp [0xc8108c],-1 ; jne 0x7f05a0 — FULL dword on the POST-call
     snapshot; == -1 -> fail tail: SEH funclet state [ebp-4] = 0
     (ENTER), ecx = 0xc81090 call 0x6ef590 (RoomDescriptor::
     constructor), push 0xb15b30 call 0xaef5af (validate), [ebp-4] =
     0xffffffff (LEAVE), push &[0xc8108c] call 0xaef253 (release/
     advance), jmp 0x7f05a0 (edx = Game reload). The SEH transport
     0x7f0711..0x7f072e stays typed-host; the state stores are LAWS. */
  const { abi, memory,
    failReentryVa, failReentry } = loadExports();
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.match(readFileSync(header, "utf8"),
    /ISAAC_ROOM_PURE_HELPERS_ABI_VERSION = 88/);
  assert.equal(failReentryVa() >>> 0, ROOM_AMBIENT_7F01C0_FAIL_REENTRY_VA);
  assert.equal(ROOM_AMBIENT_7F01C0_FAIL_REENTRY_VA, 0x7f072f);
  const view = new DataView(memory.buffer);
  const P = MEM + 0x8e00;
  const S = MEM + 0x8f00;
  const evalH = (s) => {
    view.setInt32(S + 0, s.tls_pre | 0, true);
    view.setInt32(S + 4, s.tls_post | 0, true);
    failReentry(S, P);
    const wm = {
      claim: view.getUint32(P + 0, true),
      fail_tail: view.getUint32(P + 4, true),
      state_enter: view.getUint32(P + 8, true),
      state_exit: view.getUint32(P + 12, true),
      fail_va: view.getUint32(P + 16, true),
      recheck_va: view.getUint32(P + 20, true),
      claim_va: view.getUint32(P + 24, true),
      claim_arg: view.getUint32(P + 28, true),
      ctor_va: view.getUint32(P + 32, true),
      ctor_ecx: view.getUint32(P + 36, true),
      validate_va: view.getUint32(P + 40, true),
      validate_arg: view.getUint32(P + 44, true),
      release_va: view.getUint32(P + 48, true),
      cont_va: view.getUint32(P + 52, true),
      rejoin_edx_game_va: view.getUint32(P + 56, true),
      end_va: view.getUint32(P + 60, true),
    };
    const j = roomAmbient7f01c0FailReentry(s);
    assert.deepEqual(wm, j, `v25t ${JSON.stringify(s)}`);
    return wm;
  };
  /* ---- claim law (cmp [0xc8108c],0 ; jne — FULL dword) ---- */
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).claim, 1,
    "pre 0 claims (-1 set by 0xaef29d)");
  assert.equal(evalH({ tls_pre: 1, tls_post: -1 }).claim, 0,
    "pre 1 no claim");
  assert.equal(evalH({ tls_pre: 0xffffffff, tls_post: -1 }).claim, 0,
    "pre 0xffffffff (s32 -1) no claim (FULL dword)");
  assert.equal(evalH({ tls_pre: 0x100, tls_post: -1 }).claim, 0,
    "pre 0x100 no claim (low byte 0 is not tested)");
  /* ---- re-check gate (0x7f073c FULL dword, POST-call snapshot) ---- */
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).fail_tail, 1,
    "post -1 -> fail tail");
  assert.equal(evalH({ tls_pre: 0, tls_post: 0 }).fail_tail, 0,
    "post 0 -> skip (jne 0x7f05a0)");
  assert.equal(evalH({ tls_pre: 0, tls_post: 1 }).fail_tail, 0,
    "post 1 -> skip");
  assert.equal(evalH({ tls_pre: 0, tls_post: 0xffffffff }).fail_tail, 1,
    "post 0xffffffff == -1 -> tail");
  assert.equal(evalH({ tls_pre: 0, tls_post: 0x1ff }).fail_tail, 0,
    "post 0x1ff != -1 (FULL dword: low byte 0xff not tested)");
  assert.equal(evalH({ tls_pre: 0, tls_post: 0x100 }).fail_tail, 0,
    "post 0x100 != -1 (WIDE)");
  assert.equal(evalH({ tls_pre: 0, tls_post: 0x7fffffff }).fail_tail, 0,
    "post INT_MAX != -1");
  assert.equal(evalH({ tls_pre: 0, tls_post: 0x80000000 }).fail_tail, 0,
    "post INT_MIN != -1");
  /* ---- fail-tail stores (SEH funclet state, typed-host) ---- */
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).state_enter, 0,
    "state ENTER = 0 (@0x7f074e)");
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).state_exit, 0xffffffff,
    "state LEAVE = -1 (@0x7f0767)");
  assert.equal(evalH({ tls_pre: 0, tls_post: 0 }).state_exit, 0,
    "no exit store when the tail is skipped");
  assert.equal(evalH({ tls_pre: 0, tls_post: 0xffffffff }).state_exit,
    0xffffffff, "exit store fires iff the tail runs");
  /* ---- host call arg pins (typed-host contracts) ---- */
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).claim_va,
    ROOM_AMBIENT_7F01C0_FAIL_CLAIM_VA);
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).claim_arg,
    ROOM_AMBIENT_7F01C0_FAIL_TLS_GLOBAL_VA, "push 0xc8108c @0x7f072f");
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).ctor_va,
    ROOM_AMBIENT_7F01C0_FAIL_CTOR_VA);
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).ctor_ecx,
    ROOM_AMBIENT_7F01C0_FAIL_CTOR_ECX, "thiscall this = 0xc81090");
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).validate_va,
    ROOM_AMBIENT_7F01C0_FAIL_VALIDATE_VA);
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).validate_arg,
    ROOM_AMBIENT_7F01C0_FAIL_VALIDATE_ARG_VA, "push 0xb15b30 @0x7f075a");
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).release_va,
    ROOM_AMBIENT_7F01C0_FAIL_RELEASE_VA);
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).cont_va,
    ROOM_AMBIENT_7F01C0_FAIL_CONT_VA, "rejoin 0x7f05a0 (tail path)");
  assert.equal(evalH({ tls_pre: 0, tls_post: 0 }).cont_va,
    ROOM_AMBIENT_7F01C0_FAIL_CONT_VA, "jne path rejoins 0x7f05a0 too");
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).rejoin_edx_game_va,
    ROOM_AMBIENT_7F01C0_FAIL_REJOIN_GAME_VA, "edx = Game reload @0x7f05a0");
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).fail_va,
    ROOM_AMBIENT_7F01C0_FAIL_REENTRY_VA);
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).recheck_va,
    ROOM_AMBIENT_7F01C0_FAIL_RECHECK_VA);
  assert.equal(evalH({ tls_pre: 0, tls_post: -1 }).end_va,
    ROOM_AMBIENT_7F01C0_FAIL_END_VA);
  /* ---- randomized differential (LCG high bits) ---- */
  let lcg = 0x9e3779b9;
  const rnd = () => ((lcg = (Math.imul(lcg, 1664525) + 1013904223) >>> 0), lcg);
  const hi = (n) => Math.floor(rnd() / 2 ** 23) % n;
  for (let k = 0; k < 200; k++) {
    evalH({
      tls_pre: [0, 1, -1, 0x100, 0x1ff, 0xffffffff, 0x7fffffff, 0x80000000][hi(8)],
      tls_post: [0, 1, -1, 0x100, 0x1ff, 0xffffffff, 0x7fffffff, 0x80000000][hi(8)],
    });
  }
});

test("room v25t mutation checks (helpers ABI 67)", () => {
  /* Each mutant must change behaviour AND a pinned assertion must catch
     it: the test itself FAILS on the mutated build. */
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const P = MEM + 0x9200;
  const S = MEM + 0x9300;
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry(toFile(bad));
    let threw = false;
    try {
      check();
    } catch {
      threw = true;
    }
    writeSourceRetry(original);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    /* (1) re-check folds the PRE-call value (defect-class-1): the
       machine's cmp at 0x7f073c reads the POST-call snapshot; with
       tls_pre 1 / tls_post -1 the tail must fire. */
    withMutant("v25t recheck folds pre-call tls",
      (s) => s.replace(
        "const uint32_t fail_tail = (src->tls_post == -1) ? 1u : 0u;",
        "const uint32_t fail_tail = (src->tls_pre == -1) ? 1u : 0u;",
      ),
      () => {
        const { memory, failReentry } = loadExports();
        const view = new DataView(memory.buffer);
        view.setInt32(S + 0, 1, true);   /* tls_pre 1 (no claim) */
        view.setInt32(S + 4, -1, true);  /* tls_post -1 (claimed) */
        failReentry(S, P);
        assert.equal(view.getUint32(P + 4, true), 1,
          "re-check reads the POST-call snapshot: post -1 -> tail");
      });
    /* (2) re-check LOW-BYTE test instead of FULL dword: 0x1ff must NOT
       be -1. */
    withMutant("v25t recheck low-byte test",
      (s) => s.replace(
        "const uint32_t fail_tail = (src->tls_post == -1) ? 1u : 0u;",
        "const uint32_t fail_tail = ((src->tls_post & 0xff) == 0xff) ? 1u : 0u;",
      ),
      () => {
        const { memory, failReentry } = loadExports();
        const view = new DataView(memory.buffer);
        view.setInt32(S + 0, 0, true);
        view.setInt32(S + 4, 0x1ff, true); /* low byte 0xff */
        failReentry(S, P);
        assert.equal(view.getUint32(P + 4, true), 0,
          "cmp [0xc8108c],-1 is FULL dword: 0x1ff != -1");
      });
    /* (3) fail-tail LEAVE store: 0 instead of 0xffffffff. */
    withMutant("v25t state exit store 0",
      (s) => s.replace(
        "out->state_exit = (fail_tail != 0u) ? 0xffffffffu : 0u;",
        "out->state_exit = (fail_tail != 0u) ? 0u : 0u;",
      ),
      () => {
        const { memory, failReentry } = loadExports();
        const view = new DataView(memory.buffer);
        view.setInt32(S + 0, 0, true);
        view.setInt32(S + 4, -1, true);
        failReentry(S, P);
        assert.equal(view.getUint32(P + 12, true), 0xffffffff,
          "[ebp-4] = 0xffffffff LEAVE store (@0x7f0767)");
      });
    /* (4) ctor this ecx off-by-4: 0xc81094 instead of 0xc81090. */
    withMutant("v25t ctor ecx off-by-4",
      (s) => s.replace(
        "out->ctor_ecx = ISAAC_ROOM_AMBIENT_7F01C0_FAIL_CTOR_ECX;",
        "out->ctor_ecx = 0x00c81094u;",
      ),
      () => {
        const { memory, failReentry } = loadExports();
        const view = new DataView(memory.buffer);
        view.setInt32(S + 0, 0, true);
        view.setInt32(S + 4, -1, true);
        failReentry(S, P);
        assert.equal(view.getUint32(P + 36, true), 0xc81090,
          "ctor this = 0xc81090 (mov ecx,0xc81090 @0x7f0749)");
      });
    /* (5) claim law LOW-BYTE test: tls_pre 0x100 must NOT claim. */
    withMutant("v25t claim low-byte test",
      (s) => s.replace(
        "const uint32_t claim = (src->tls_pre == 0) ? 1u : 0u;",
        "const uint32_t claim = ((src->tls_pre & 0xff) == 0) ? 1u : 0u;",
      ),
      () => {
        const { memory, failReentry } = loadExports();
        const view = new DataView(memory.buffer);
        view.setInt32(S + 0, 0x100, true); /* low byte 0 */
        view.setInt32(S + 4, -1, true);
        failReentry(S, P);
        assert.equal(view.getUint32(P + 0, true), 0,
          "cmp [0xc8108c],0 FULL dword: 0x100 != 0");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});

test("room v95 water-b16 grid/spray laws (record idx 36, FUN_00823540 chain)", () => {
  /* PE-truth references transcribed from the instruction stream:
     FUN_0074efd0 (0x74efd0..0x74f02e) room-callsite gate; FUN_00823370
     (0x823370..0x823536) grid math; FUN_00823540 wrapper al gate (bytes
     0x183a0/0x269e9); FUN_007067c0 (0x7067c0..0x7068be) spray math. The
     float32 constants are the hash-bound exe bit patterns. */
  const f = Math.fround;
  const bits2f32 = (b) => new Float32Array(new Uint32Array([b >>> 0]).buffer)[0];
  const PE_003 = bits2f32(0x3cf5c28f);  /* DAT_00baa0a0 = 0.03f */
  const PE_040 = bits2f32(0x3ecccccd);  /* DAT_00baa280 = 0.4f */
  const PE_045 = bits2f32(0x3ee66666);  /* DAT_00baa2b8 = 0.45f */
  const PE_020 = bits2f32(0x3e4ccccd);  /* DAT_00baa198 = 0.2f */

  /* --- FUN_0074efd0 mineshaft gate: every PE branch + WIDE values --- */
  assert.equal(roomB16MineshaftGate(2, 3, 4, 0, 0), 0, "difficulty 2 closes");
  assert.equal(roomB16MineshaftGate(3, 3, 4, 0, 0), 0, "difficulty 3 closes");
  assert.equal(roomB16MineshaftGate(0x102, 3, 4, 0, 0), 0, "wide difficulty 0x102 closes");
  assert.equal(roomB16MineshaftGate(1, 3, 4, 0x10000, 2), 0, "stage 1..6 flags bit16 closes");
  assert.equal(roomB16MineshaftGate(1, 3, 4, 0, 2), 1, "stage 3 poll bit1 opens");
  assert.equal(roomB16MineshaftGate(1, 3, 4, 0, 0), 0, "stage 3 poll bit1 clear");
  assert.equal(roomB16MineshaftGate(1, 3, 4, 0, 0x4), 0, "poll bit2 not tested (test al,2)");
  assert.equal(roomB16MineshaftGate(1, 3, 4, 0, 0xff), 1, "wide poll byte");
  assert.equal(roomB16MineshaftGate(1, 3, 5, 0, 2), 1, "stage_type 5 opens");
  assert.equal(roomB16MineshaftGate(1, 3, 3, 0, 2), 0, "stage_type 3 closes");
  assert.equal(roomB16MineshaftGate(1, 3, 6, 0, 2), 0, "stage_type 6 closes");
  assert.equal(roomB16MineshaftGate(1, 3, 0x104, 0, 2), 0, "wide stage_type 0x104 closes");
  assert.equal(roomB16MineshaftGate(1, 4, 5, 0, 0), 1, "stage 4 short-circuits");
  assert.equal(roomB16MineshaftGate(1, 4, 5, 0x10000, 0), 0, "stage 4 flags-closed first");
  assert.equal(roomB16MineshaftGate(1, 5, 4, 0, 2), 0, "stage 5 != 3/4 closes");
  assert.equal(roomB16MineshaftGate(1, 0, 4, 0x10000, 2), 0, "stage 0 skips flag test, closes");
  assert.equal(roomB16MineshaftGate(1, 7, 4, 0x10000, 2), 0, "stage 7 skips flag test, closes");
  assert.equal(roomB16MineshaftGate(1, 0x100, 4, 0x10000, 2), 0, "stage 0x100 skips flag test, closes");

  /* --- FUN_00823370 grid math --- */
  const plainIn = [0.5, 0.25, 0.125, 0.0625, 2.0, 4.0];
  const lerpOut = roomB16GridStep(plainIn, 7, 0, 0, 0, 10, 12, 0.5, 0, 0);
  /* gate via room_type 7: out[i] = out[i] + (A - out[i]) * B (A=1, B=0.75). */
  assert.equal(lerpOut[0], f(f(1 - 0.5) * 0.75 + 0.5), "lerp out0");
  assert.equal(lerpOut[1], f(f(1 - 0.25) * 0.75 + 0.25), "lerp out1");
  assert.equal(lerpOut[2], f(f(1 - 0.125) * 0.75 + 0.125), "lerp out2");
  assert.equal(lerpOut[3], f(f(1 - 0.0625) * 0.75 + 0.0625), "lerp out3");
  assert.equal(lerpOut[4], f(f(0 - 2.0) * 0.75 + 2.0), "lerp out4 toward 0 (xorps)");
  assert.equal(lerpOut[5], f(f(1 - 4.0) * 0.75 + 4.0), "lerp out5");
  const pass = roomB16GridStep(plainIn, 1, 0, 0, 0, 10, 12, 0.5, 0, 0);
  assert.deepEqual(pass, plainIn.map((x) => f(x)), "gate closed passthrough");
  assert.deepEqual(
    roomB16GridStep(plainIn, 1, 0, 0, 0, 10, 12, 0.5, 1, 1),
    lerpOut, "mineshaft && 1830c==1 opens the lerp");
  assert.deepEqual(
    roomB16GridStep(plainIn, 1, 0, 0, 0, 10, 12, 0.5, 1, 2),
    pass, "1830c==2 keeps the lerp closed");
  assert.deepEqual(roomB16GridStep(plainIn, 8, 0, 0, 0, 10, 12, 0.5, 0, 0), lerpOut, "room_type 8 lerps");
  assert.deepEqual(roomB16GridStep(plainIn, 0x1d, 0, 0, 0, 10, 12, 0.5, 0, 0), lerpOut, "room_type 0x1d lerps");
  /* bit9 of desc_flags_44: out[4] += 0.03 (runs even with the gate closed). */
  const band = roomB16GridStep(plainIn, 1, 0x200, 0, 0, 10, 12, 0.5, 0, 0);
  assert.equal(band[4], f(plainIn[4] + PE_003), "bit9 band adds 0.03 to out4");
  assert.deepEqual(band.slice(0, 4), pass.slice(0, 4), "bit9 band leaves out0..3");
  assert.equal(band[5], f(plainIn[5]), "bit9 band leaves out5");
  /* lava-band: room_1d18==0x20 && bit5; v = float(desc54)/float((h-2)*(w-2))*lava. */
  const lv = roomB16GridStep(plainIn, 1, 0x20, 400, 0x20, 10, 12, 0.5, 0, 0);
  const v = f(f(f(400) / f(Math.imul(12 - 2, 10 - 2))) * f(0.5)); /* 400/80*0.5 = 2.5 */
  assert.equal(lv[0], f(f(0.5) - v), "lava out0 - v");
  const vc2 = f(v * PE_040);
  assert.equal(lv[1], f(f(0.25) + vc2), "lava out1 + v*0.4");
  assert.equal(lv[2], f(f(0.125) + vc2), "lava out2 + v*0.4");
  const vc3 = f(v * PE_045);
  assert.equal(lv[3], f(f(0.0625) - vc3), "lava out3 - v*0.45");
  const vc4 = f(v * PE_020);
  assert.equal(lv[5], f(f(4.0) + vc4), "lava out5 + v*0.2");
  assert.equal(lv[4], f(plainIn[4]), "lava leaves out4");
  assert.deepEqual(
    roomB16GridStep(plainIn, 1, 0x20, 400, 0x21, 10, 12, 0.5, 0, 0),
    pass, "room_1d18 != 0x20 skips the lava block");
  assert.deepEqual(
    roomB16GridStep(plainIn, 1, 0, 400, 0x20, 10, 12, 0.5, 0, 0),
    pass, "bit5 clear skips the lava block");
  /* WIDE desc54 (int32 wrap) and WIDE dims (int32 wrap product). */
  const wideLava = roomB16GridStep(plainIn, 1, 0x20, 0xffffffff, 0x20, 0x100, 0x1ff, 1.5, 0, 0);
  const prodW = Math.imul(0x1ff - 2, 0x100 - 2);
  const tW = f(f(-1 | 0) / f(prodW)); /* cvtdq2ps of the int32 -1 */
  const vW = f(tW * f(1.5));
  assert.equal(wideLava[0], f(f(0.5) - vW), "wide lava out0");

  /* --- FUN_00823540 wrapper al gate (low-byte tests) --- */
  assert.equal(roomB16SprayGateAl(0, 0), 1);
  assert.equal(roomB16SprayGateAl(0x100, 0), 1, "wide byte low==0");
  assert.equal(roomB16SprayGateAl(0, 0x100), 1, "wide byte low==0");
  assert.equal(roomB16SprayGateAl(0, 1), 0);
  assert.equal(roomB16SprayGateAl(0x1ff, 0), 0, "wide byte low==0xff");
  assert.equal(roomB16SprayGateAl(0xffffffff, 0), 0);

  /* --- FUN_007067c0 spray step --- */
  const prev = [1, 2, 3, 4, 5, 6];
  const cur = [10, 8, 6, 4, 2, 0];
  const act = roomB16SprayStep(prev, cur, 0.015, 1);
  assert.equal(act.gate, 1);
  for (let i = 0; i < 6; ++i) {
    assert.equal(act.vel[i], f(f(Math.abs(f(cur[i] - prev[i]))) * f(0.015)),
      `active vel[${i}] = |cur-prev|*0.015`);
  }
  assert.deepEqual(act.prev, prev.map((x) => f(x)), "active leaves prev untouched");
  const inact = roomB16SprayStep(prev, cur, 0.015, 0);
  assert.equal(inact.gate, 0);
  assert.deepEqual(inact.prev.slice(0, 4), cur.slice(0, 4).map((x) => f(x)),
    "inactive copies 4 floats only");
  assert.equal(inact.prev[4], f(5), "inactive leaves prev[4]");
  assert.equal(inact.prev[5], f(6), "inactive leaves prev[5]");
  assert.equal(roomB16SprayStep(prev, cur, 0.015, 0x100).gate, 0,
    "wide active low byte 0 -> inactive");
  const negPrev = [-1, 1, -2, 2, -3, 3];
  const neg = roomB16SprayStep(negPrev, cur, 0.015, 1);
  for (let i = 0; i < 6; ++i) {
    assert.equal(neg.vel[i], f(f(Math.abs(f(cur[i] - negPrev[i]))) * f(0.015)),
      `negative diff vel[${i}]`);
  }

  /* --- wasm differential --- */
  const { memory, b16Mineshaft, b16GridStep, b16SprayGate, b16SprayStep } =
    loadExports();
  const view = new DataView(memory.buffer);
  const IN = MEM + 0x7000;
  const OUT = MEM + 0x7080;
  const PREV = MEM + 0x7100;
  const CUR = MEM + 0x7180;
  const VEL = MEM + 0x7200;
  for (let i = 0; i < 6; ++i) writeF32(view, IN + i * 4, plainIn[i]);
  const runGrid = (roomType8, descFlags44, desc54, room1d18, gridWc, gridH10,
                   lava7740, msAl, tr1830c) => {
    b16GridStep(OUT, IN, roomType8, descFlags44, desc54, room1d18, gridWc,
                gridH10, lava7740, msAl, tr1830c);
    return [0, 4, 8, 12, 16, 20].map((o) => readF32(view, OUT + o));
  };
  assert.deepEqual(runGrid(7, 0, 0, 0, 10, 12, 0.5, 0, 0), lerpOut,
    "wasm grid lerp via room_type 7");
  assert.deepEqual(runGrid(1, 0x200, 0, 0, 10, 12, 0.5, 0, 0), band,
    "wasm grid bit9 band");
  assert.deepEqual(runGrid(1, 0x20, 400, 0x20, 10, 12, 0.5, 0, 0), lv,
    "wasm grid lava band");
  assert.deepEqual(runGrid(1, 0x20, 0xffffffff, 0x20, 0x100, 0x1ff, 1.5, 0, 0),
    wideLava, "wasm grid wide lava");
  assert.deepEqual(runGrid(1, 0, 0, 0, 10, 12, 0.5, 0, 0), pass,
    "wasm grid passthrough");
  assert.equal(b16Mineshaft(1, 3, 4, 0, 0x2) | 0, 1, "wasm mineshaft poll bit");
  assert.equal(b16Mineshaft(2, 3, 4, 0, 0x2) | 0, 0, "wasm mineshaft difficulty");
  assert.equal(b16Mineshaft(0x102, 3, 4, 0x10000, 0) | 0, 0, "wasm mineshaft wide");
  assert.equal(b16SprayGate(0, 0x100) | 0, 1, "wasm spray gate low byte");
  assert.equal(b16SprayGate(0x1ff, 0) | 0, 0, "wasm spray gate wide");
  for (let i = 0; i < 6; ++i) writeF32(view, PREV + i * 4, prev[i]);
  for (let i = 0; i < 6; ++i) writeF32(view, CUR + i * 4, cur[i]);
  assert.equal(b16SprayStep(PREV, CUR, 0.015, 1, VEL) | 0, 1,
    "wasm spray active gate");
  for (let i = 0; i < 6; ++i) {
    assert.equal(readF32(view, VEL + i * 4), act.vel[i], `wasm vel[${i}]`);
  }
  assert.equal(b16SprayStep(PREV, CUR, 0.015, 0, VEL) | 0, 0,
    "wasm spray inactive gate");
  for (let i = 0; i < 4; ++i) {
    assert.equal(readF32(view, PREV + i * 4), f(cur[i]), `wasm inactive prev[${i}]`);
  }
  assert.equal(readF32(view, PREV + 16), f(prev[4]), "wasm inactive leaves prev[4]");
  assert.equal(readF32(view, PREV + 20), f(prev[5]), "wasm inactive leaves prev[5]");
  assert.equal(b16SprayStep(PREV, CUR, 0.015, 0x100, VEL) | 0, 0,
    "wasm spray wide active low byte 0 -> inactive");

  /* Export presence in source/header. */
  assert.match(readFileSync(source, "utf8"), /isaac_room_b16_mineshaft_gate/);
  assert.match(readFileSync(source, "utf8"), /isaac_room_b16_grid_step/);
  assert.match(readFileSync(source, "utf8"), /isaac_room_b16_spray_gate_al/);
  assert.match(readFileSync(source, "utf8"), /isaac_room_b16_spray_step/);
  assert.match(readFileSync(source, "utf8"), /0x00823370/);
  assert.match(readFileSync(source, "utf8"), /0x007067c0/);
  assert.match(readFileSync(header, "utf8"), /isaac_room_b16_mineshaft_gate/);
});

/* ----------------------------------------------------------------- v67a - */
test("room v67a trigger-clear audio 7f7a40 gates (helpers ABI 67)", () => {
  /* FUN_007f7a40 record-26 census: early aborts, play flag, stage-5/6
     al, success/PLAY gate + typed-host records. PE 0x7f7a40..0x7f7bd5
     (see section-notes/update-v95-7f7a40-audio-census/NOTES.md). */
  const { abi, memory, tca7f7a40Va, tca7f7a40Gates } = loadExports();
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(abi(), ROOM_PURE_ABI_VERSION);
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.match(readFileSync(header, "utf8"),
    /ISAAC_ROOM_PURE_HELPERS_ABI_VERSION = 88/);
  assert.equal(tca7f7a40Va() >>> 0, ROOM_TRIGGER_CLEAR_AUDIO_7F7A40_VA);
  assert.equal(ROOM_TRIGGER_CLEAR_AUDIO_7F7A40_VA, 0x7f7a40);
  const view = new DataView(memory.buffer);
  const P = MEM + 0x9800;
  const S = MEM + 0x9900;
  const slots = (src) => {
    /* GatesSrc: 24 u32 = 96 bytes (pack 1). */
    const f = [
      "a1", "a2", "game_26584", "room_type_8", "desc_f10_f10",
      "h_74ea50", "game_stage_0", "game_2654c", "h_706940_80",
      "obj_2c7", "obj_8", "game_26630", "game_26589", "game_26550",
      "game_c", "h_6f9400", "h_6f95a0", "game_18304", "game_182d0",
      "game_4", "room_728", "room_f10_f8", "r74bba0_f10_f8",
      "game_present",
    ];
    f.forEach((k, i) => view.setUint32(S + i * 4, src[k] >>> 0, true));
  };
  const evalG = (src) => {
    slots(src);
    tca7f7a40Gates(S, P);
    const wm = {
      skip_early: view.getUint32(P + 0, true),
      abort_2c: view.getUint32(P + 4, true),
      type5_59: view.getUint32(P + 8, true),
      fire_74ea50: view.getUint32(P + 12, true),
      abort_74ea50: view.getUint32(P + 16, true),
      stage_gate: view.getUint32(P + 20, true),
      abort_stage_bit: view.getUint32(P + 24, true),
      play: view.getUint32(P + 28, true),
      al: view.getUint32(P + 32, true),
      success: view.getUint32(P + 36, true),
      abort_728: view.getUint32(P + 40, true),
      fail_path: view.getUint32(P + 44, true),
      play_fire: view.getUint32(P + 48, true),
      exit_kind: view.getUint32(P + 52, true),
      call_7eea90_va: view.getUint32(P + 56, true),
      call_7eea90_arg: view.getUint32(P + 60, true),
      call_74bba0_va: view.getUint32(P + 64, true),
      call_74bba0_arg: view.getUint32(P + 68, true),
      store_394_value: view.getUint32(P + 72, true),
      call_710fa0_va: view.getUint32(P + 76, true),
      call_710fa0_arg1: view.getUint32(P + 80, true),
      call_710fa0_arg2: view.getUint32(P + 84, true),
      ret_va: view.getUint32(P + 88, true),
      fail_va: view.getUint32(P + 92, true),
      end_va: view.getUint32(P + 96, true),
    };
    const j = roomTriggerClearAudio7f7a40Gates(src);
    assert.deepEqual(wm, j, `v67a gates ${JSON.stringify(src)}`);
    return wm;
  };
  /* ---- a2 byte gate: 0x100 low byte 0 -> EARLY gates run; a2=1 /
     0x1ff low byte nonzero -> skip. ---- */
  assert.equal(evalG({ a2: 0x100 }).skip_early, 0, "a2 low byte 0");
  assert.equal(evalG({ a2: 0x1ff }).skip_early, 1, "a2 low byte 0xff -> skip");
  assert.equal(evalG({ a2: 1 }).skip_early, 1, "a2=1 skips early gates");
  /* ---- abort_2c FULL dword vs 0x2c (0x1002c must NOT abort) ---- */
  const baseG = {
    a1: 1, a2: 0, game_26584: 0, room_type_8: 1, desc_f10_f10: 0,
    h_74ea50: 0, game_stage_0: 6, game_2654c: 0, h_706940_80: 0,
    obj_2c7: 0, obj_8: 0, game_26630: 0, game_26589: 0, game_26550: 0,
    game_c: 0, h_6f9400: 0, h_6f95a0: 0, game_18304: 1, game_182d0: 1,
    game_4: 6, room_728: 0, room_f10_f8: 0, r74bba0_f10_f8: 0,
    game_present: 1,
  };
  assert.equal(evalG({ ...baseG, game_26584: 0x2c }).abort_2c, 1);
  assert.equal(evalG({ ...baseG, game_26584: 0x1002c }).abort_2c, 0,
    "FULL dword: 0x1002c != 0x2c");
  /* ---- type-5/0x59 gate + 0x74ea50 host-glued abort ---- */
  const t5 = evalG({ ...baseG, room_type_8: 5, desc_f10_f10: 0x59 });
  assert.equal(t5.type5_59, 1);
  assert.equal(t5.fire_74ea50, 1);
  assert.equal(t5.abort_74ea50, 0, "74ea50 result 0 passes");
  assert.equal(evalG({
    ...baseG, room_type_8: 5, desc_f10_f10: 0x59, h_74ea50: 1,
  }).abort_74ea50, 1, "74ea50 nonzero aborts");
  assert.equal(evalG({
    ...baseG, room_type_8: 5, desc_f10_f10: 0x58,
  }).type5_59, 0, "subtype 0x58 no gate");
  /* ---- stage gate + bit-0x10000 abort ---- */
  assert.equal(evalG({ ...baseG, game_stage_0: 7 }).stage_gate, 0);
  assert.equal(evalG({ ...baseG, game_stage_0: 3 }).stage_gate, 1);
  assert.equal(evalG({ ...baseG, game_stage_0: 3, game_2654c: 0x10000 })
    .abort_stage_bit, 1);
  assert.equal(evalG({ ...baseG, game_stage_0: 3, game_2654c: 0x20000 })
    .abort_stage_bit, 0, "bit 0x10000 only");
  /* ---- play flag: r80==3 direct; UNSIGNED 0x26630; byte 0x2c7 ---- */
  assert.equal(evalG({ ...baseG, h_706940_80: 3 }).play, 1);
  assert.equal(evalG({ ...baseG, obj_2c7: 0x1, obj_8: 9 }).play, 1,
    "obj_2c7 byte != 0 -> b03 -> play (26584==0, 26630<=0)");
  assert.equal(evalG({ ...baseG, obj_2c7: 0x100, obj_8: 9 }).play, 0,
    "obj_2c7 WIDE: low byte 0x00 -> byte test fails, obj_8 9 != 2");
  assert.equal(evalG({ ...baseG, obj_8: 2, game_26630: 0, game_26589: 1 })
    .play, 1, "byte 26589 != 0 -> b03 -> play (26630<=0)");
  assert.equal(evalG({ ...baseG, obj_8: 2, game_26630: 1, game_26589: 1 })
    .play, 0, "ja b03 then jbe fails: 26630 1 > 0 -> play 0");
  assert.equal(evalG({ ...baseG, obj_8: 2, game_26630: 0xffffffff,
    game_26589: 1 }).play, 0,
    "26630 UNSIGNED: 0xffffffff > 0u -> ja b03 -> jbe fails -> play 0");
  assert.equal(evalG({ ...baseG, obj_8: 2, game_26630: 0, game_26589: 0,
    game_26584: 0 }).play, 0,
    "26589==0 -> je 0x7f7b15 (play 0); b03 unreachable via 26630==0");
  assert.equal(evalG({ ...baseG, obj_8: 2, game_26630: 0, game_26589: 0,
    game_26584: 1 }).play, 0, "b03: 26584 != 0 -> play 0");
  assert.equal(evalG({ ...baseG, obj_8: 2, game_26630: 4, game_26584: 1 })
    .play, 0, "b03: 26584 != 0 wins over 26630>0");
  /* ---- al: stage 6 -> 1; stage 5 bit-2 law; WIDE inputs ---- */
  assert.equal(evalG({ ...baseG, game_stage_0: 6 }).al, 1);
  assert.equal(evalG({ ...baseG, game_stage_0: 4 }).al, 0);
  assert.equal(evalG({
    ...baseG, game_stage_0: 5, h_6f9400: 0, h_6f95a0: 0xfffffffd,
    game_26550: 2, game_c: 0,
  }).al, 1, "~h6f95a0 = 2, (2|2|0) -> x = 2 -> bit2 set");
  assert.equal(evalG({
    ...baseG, game_stage_0: 5, h_6f9400: 0, h_6f95a0: 0xfffffffd,
  }).al, 0, "x = 2 & 0 = 0 -> bit2 clear (OR set empty)");
  assert.equal(evalG({
    ...baseG, game_stage_0: 5, h_6f9400: 0x100, h_6f95a0: 0,
  }).al, 0, "(0x100|0|0) & 2 == 0 -> al 0 (bit-2 law)");
  assert.equal(evalG({
    ...baseG, game_stage_0: 5, h_6f9400: 0x102, h_6f95a0: 0,
  }).al, 1, "(0x102|0|0) & 2 != 0 -> al 1");
  /* ---- success gate + PLAY/hard-abort/fail classification ---- */
  const win = evalG({ ...baseG, game_stage_0: 6, h_706940_80: 3,
    room_f10_f8: 0x12345678, r74bba0_f10_f8: 0x9abcdef0 });
  assert.equal(win.success, 1);
  assert.equal(win.play_fire, 1);
  assert.equal(win.exit_kind, 1);
  assert.equal(win.call_7eea90_va, ROOM_TRIGGER_CLEAR_AUDIO_7F7A40_HOST_7EEA90_VA);
  assert.equal(win.call_7eea90_arg, 1);
  assert.equal(win.call_74bba0_va, ROOM_TRIGGER_CLEAR_AUDIO_7F7A40_HOST_74BBA0_VA);
  assert.equal(win.call_74bba0_arg, 3);
  assert.equal(win.store_394_value, 0xfffffff6);
  assert.equal(win.call_710fa0_va, ROOM_TRIGGER_CLEAR_AUDIO_7F7A40_HOST_710FA0_VA);
  assert.equal(win.call_710fa0_arg1, 0x12345678);
  assert.equal(win.call_710fa0_arg2, 0x9abcdef0);
  assert.equal(win.ret_va, ROOM_TRIGGER_CLEAR_AUDIO_7F7A40_RET_VA);
  assert.equal(win.fail_va, ROOM_TRIGGER_CLEAR_AUDIO_7F7A40_FAIL_VA);
  assert.equal(win.end_va, ROOM_TRIGGER_CLEAR_AUDIO_7F7A40_END_VA);
  assert.equal(evalG({ ...baseG, room_728: 1, game_stage_0: 6,
    h_706940_80: 3 }).abort_728, 1, "room_728 != 0 hard abort");
  assert.equal(evalG({ ...baseG, game_stage_0: 6, h_706940_80: 3,
    room_728: 1 }).exit_kind, 0, "hard abort -> exit 0");
  assert.equal(evalG({ ...baseG, game_stage_0: 6, h_706940_80: 3,
    game_18304: 5 }).fail_path, 1, "18304 != 182d0 -> fail");
  assert.equal(evalG({ ...baseG, game_stage_0: 6, h_706940_80: 3,
    game_4: 4 }).fail_path, 1, "Game[4]==4 -> fail");
  assert.equal(evalG({ ...baseG, game_stage_0: 6, h_706940_80: 3,
    game_4: 5 }).fail_path, 1, "Game[4]==5 -> fail");
  assert.equal(evalG({ ...baseG, game_stage_0: 4, h_706940_80: 3 })
    .fail_path, 1, "al==0 -> fail");
  /* ---- randomized differential ---- */
  let lcg = 0x9e3779b9;
  const rnd = () => ((lcg = (Math.imul(lcg, 1664525) + 1013904223) >>> 0), lcg);
  const pick = (arr) => arr[Math.floor(rnd() / 2 ** 23) % arr.length];
  for (let k = 0; k < 150; k++) {
    evalG({
      a1: pick([0, 1, 0x100, 0x1ff, 0xffffffff]),
      a2: pick([0, 1, 0x100, 0x1ff, 0xffffffff]),
      game_26584: pick([0, 0x2c, 0x1002c, 0xffffffff]),
      room_type_8: pick([1, 5, 0x105, 0x59]),
      desc_f10_f10: pick([0, 0x59, 0x159, 0xffffffff]),
      h_74ea50: pick([0, 1, 0x100, 0xffffffff]),
      game_stage_0: pick([0, 1, 5, 6, 7, 0xffffffff]),
      game_2654c: pick([0, 0x10000, 0x20000, 0xffffffff]),
      h_706940_80: pick([0, 2, 3, 0xffffffff]),
      obj_2c7: pick([0, 1, 0x100, 0x1ff]),
      obj_8: pick([0, 2, 0x102, 0xffffffff]),
      game_26630: pick([0, 1, 0xffffffff, 0x80000000]),
      game_26589: pick([0, 1, 0x100, 0x1ff]),
      game_26550: pick([0, 1, 0x10000, 0xffffffff]),
      game_c: pick([0, 2, 0x100, 0xffffffff]),
      h_6f9400: pick([0, 1, 0x100, 0xffffffff]),
      h_6f95a0: pick([0, 1, 0xfffffffd, 0xffffffff]),
      game_18304: pick([0, 1, 5, 0xffffffff]),
      game_182d0: pick([0, 1, 5, 0xffffffff]),
      game_4: pick([0, 4, 5, 6]),
      room_728: pick([0, 1, 0xffffffff]),
      room_f10_f8: pick([0, 0x12345678, 0xffffffff]),
      r74bba0_f10_f8: pick([0, 0x9abcdef0, 0xffffffff]),
      game_present: pick([0, 1]),
    });
  }
});

test("room v67a trigger-clear audio 7f7a40 fail path (helpers ABI 67)", () => {
  /* FUN_007f7a40 fail path 0x7f7bd8..0x7f8189: 0x740bc0 POST-call
     snapshot, 706940b/obj/74bae0/74e9b0 gates, PURE slot-hash search,
     PLAY2 records, door-branch A/B, a1 tail gate. */
  const { memory, tca7f7a40Fail } = loadExports();
  const view = new DataView(memory.buffer);
  const P = MEM + 0x9b00;
  const S = MEM + 0x9c00;
  const slots = (src) => {
    const f = [
      "a1", "a2", "game_26584", "game_26630", "game_26589",
      "game_18304", "game_18314", "h_740bc0_ret_8", "h_706940b_80",
      "obj_1e3", "obj_8", "h_74bae0", "h_74e9b0", "slot_seed",
      "bm1", "bm2", "slot_occ0", "slot_occ1", "slot_occ2", "slot_occ3",
      "slot_occ4", "slot_occ5", "slot_occ6", "slot_occ7",
      "r74bba0b_f10_f8", "slot_8", "h_70d360", "genrand_tail",
    ];
    f.forEach((k, i) => view.setUint32(S + i * 4, src[k] >>> 0, true));
  };
  const evalF = (src) => {
    slots(src);
    tca7f7a40Fail(S, P);
    const wm = {
      fire_740bc0: view.getUint32(P + 0, true),
      call_740bc0_va: view.getUint32(P + 4, true),
      abort_740bc0: view.getUint32(P + 8, true),
      gate_706940b: view.getUint32(P + 12, true),
      abort_706940b: view.getUint32(P + 16, true),
      gate_obj: view.getUint32(P + 20, true),
      abort_obj: view.getUint32(P + 24, true),
      abort_74bae0_zero: view.getUint32(P + 28, true),
      gate_74e9b0: view.getUint32(P + 32, true),
      abort_74e9b0: view.getUint32(P + 36, true),
      seed_fatal: view.getUint32(P + 40, true),
      fatal_va: view.getUint32(P + 44, true),
      slot_hash: view.getUint32(P + 48, true),
      slot: view.getUint32(P + 52, true),
      found: view.getUint32(P + 56, true),
      loop_count: view.getUint32(P + 60, true),
      slot_negative: view.getUint32(P + 64, true),
      fire_74bba0b: view.getUint32(P + 68, true),
      call_74bba0b_arg: view.getUint32(P + 72, true),
      fire_7eea90b: view.getUint32(P + 76, true),
      call_7eea90b_arg: view.getUint32(P + 80, true),
      store_394_value: view.getUint32(P + 84, true),
      fire_710fa0b: view.getUint32(P + 88, true),
      call_710fa0b_arg1: view.getUint32(P + 92, true),
      call_710fa0b_arg2: view.getUint32(P + 96, true),
      gate_80: view.getUint32(P + 100, true),
      slot8_gate: view.getUint32(P + 104, true),
      fire_70d360: view.getUint32(P + 108, true),
      gate_70d360_4: view.getUint32(P + 112, true),
      path_b: view.getUint32(P + 116, true),
      fire_417870: view.getUint32(P + 120, true),
      call_417870_arg: view.getUint32(P + 124, true),
      fire_710480: view.getUint32(P + 128, true),
      fire_710dd0: view.getUint32(P + 132, true),
      fire_70fb60: view.getUint32(P + 136, true),
      a1_gate: view.getUint32(P + 140, true),
      tail_fire: view.getUint32(P + 144, true),
      tail_loop_count: view.getUint32(P + 148, true),
      ret: view.getUint32(P + 152, true),
    };
    const j = roomTriggerClearAudio7f7a40Fail(src);
    assert.deepEqual(wm, j, `v67a fail ${JSON.stringify(src)}`);
    return wm;
  };
  /* Helper: a survive-case with a found slot (seed != 0, empty slot,
     bitmap1 bit set, bitmap2 clear). */
  const alive = (over = {}) => {
    const seed = 0x12345678;
    const slot = (() => {
      const t0 = seed ^ (seed >>> 2);
      const u0 = (t0 ^ (t0 << 9)) >>> 0;
      return ((u0 ^ (u0 >>> 15)) >>> 0) & 7;
    })();
    const bm1 = 1 << slot;
    const base = {
      a1: 0, a2: 0, game_26584: 0, game_26630: 0, game_26589: 0,
      game_18304: 0, game_18314: 0, h_740bc0_ret_8: 0,
      h_706940b_80: 2, obj_1e3: 1, obj_8: 2, h_74bae0: 1, h_74e9b0: 0,
      slot_seed: seed, bm1, bm2: 0, r74bba0b_f10_f8: 0xabcdef12,
      slot_8: 3, h_70d360: 1, genrand_tail: 0x12,
    };
    for (let i = 0; i < 8; i++) base[`slot_occ${i}`] = i === slot ? 0 : 1;
    return { ...base, ...over };
  };
  /* ---- 0x740bc0 POST-call snapshot (defect-class-1) ---- */
  const ok0 = evalF(alive());
  assert.equal(ok0.fire_740bc0, 1, "a2==0 fires 740bc0");
  assert.equal(ok0.abort_740bc0, 0, "snapshot == 18314 passes");
  assert.equal(ok0.call_740bc0_va, ROOM_TRIGGER_CLEAR_AUDIO_7F7A40_HOST_740BC0_VA);
  assert.equal(evalF(alive({ h_740bc0_ret_8: 1, game_18314: 0 }))
    .abort_740bc0, 1, "snapshot != 18314 aborts");
  assert.equal(evalF(alive({ a2: 1 })).fire_740bc0, 0, "a2!=0 skips 740bc0");
  assert.equal(evalF(alive({ a2: 0x100 })).fire_740bc0, 1,
    "a2 low byte 0 still fires");
  /* ---- 706940b gate: 80==2 required when 26584!=0 || 26630>0u ---- */
  assert.equal(evalF(alive({ game_26584: 1, h_706940b_80: 2 })).abort_706940b, 0);
  assert.equal(evalF(alive({ game_26584: 1, h_706940b_80: 3 })).abort_706940b, 1);
  assert.equal(evalF(alive({ game_26630: 0xffffffff, h_706940b_80: 3 }))
    .abort_706940b, 1, "26630 UNSIGNED > 0 -> gate fires");
  assert.equal(evalF(alive({ game_26584: 0, game_26630: 0, h_706940b_80: 3 }))
    .gate_706940b, 0, "no gate when 26584==0 && 26630<=0");
  /* ---- obj gate: obj_1e3==0 -> obj_8==2 && (26630>0u || 26589!=0) ---- */
  assert.equal(evalF(alive({ obj_1e3: 0, obj_8: 2, game_26630: 0,
    game_26589: 1 })).abort_obj, 0);
  assert.equal(evalF(alive({ obj_1e3: 0, obj_8: 3 })).abort_obj, 1);
  assert.equal(evalF(alive({ obj_1e3: 0, obj_8: 2, game_26630: 0,
    game_26589: 0 })).abort_obj, 1);
  assert.equal(evalF(alive({ obj_1e3: 0x100 })).gate_obj, 1,
    "obj_1e3 WIDE: low byte 0x00 -> gate fires");
  /* ---- 74bae0/74e9b0 ---- */
  assert.equal(evalF(alive({ h_74bae0: 0 })).abort_74bae0_zero, 1);
  assert.equal(evalF(alive({ h_74bae0: 4, h_74e9b0: 1 })).abort_74e9b0, 1);
  assert.equal(evalF(alive({ h_74bae0: 4, h_74e9b0: 0 })).abort_74e9b0, 0);
  assert.equal(evalF(alive({ h_74bae0: 4 })).gate_74e9b0, 1);
  assert.equal(evalF(alive({ h_74bae0: 5 })).gate_74e9b0, 0);
  /* ---- slot hash PURE law ---- */
  const hh = evalF(alive());
  assert.equal(hh.seed_fatal, 0);
  assert.equal(hh.slot_hash, ((0x12345678 ^ (0x12345678 >>> 2)) |
    0) === 0 ? 0 : hh.slot_hash);
  assert.equal(hh.found, 1);
  assert.equal(hh.slot_negative, 0);
  assert.equal(evalF(alive({ slot_seed: 0 })).seed_fatal, 1);
  assert.equal(evalF(alive({ slot_seed: 0 })).fatal_va,
    ROOM_TRIGGER_CLEAR_AUDIO_7F7A40_HOST_FATAL_VA);
  /* scanning: bitmap1 bit set but occupied -> next slot */
  {
    const s0 = alive();
    const t0 = s0.slot_seed ^ (s0.slot_seed >>> 2);
    const u0 = (t0 ^ (t0 << 9)) >>> 0;
    const slot0 = ((u0 ^ (u0 >>> 15)) >>> 0) & 7;
    const occ = {};
    for (let i = 0; i < 8; i++) occ[`slot_occ${i}`] = 1;
    occ[`slot_occ${slot0}`] = 1; /* target occupied -> scan next */
    occ[`slot_occ${(slot0 + 1) & 7}`] = 0;
    const r = evalF({ ...s0, bm1: 1 << (slot0 + 1), ...occ });
    assert.equal(r.found, 1, "occupied slot -> advance");
    assert.equal(r.slot, (slot0 + 1) & 7);
    assert.equal(r.loop_count, 1);
  }
  {
    const s0 = alive();
    const t0 = s0.slot_seed ^ (s0.slot_seed >>> 2);
    const u0 = (t0 ^ (t0 << 9)) >>> 0;
    const slot0 = ((u0 ^ (u0 >>> 15)) >>> 0) & 7;
    const r = evalF({ ...s0, bm1: 0 });
    assert.equal(r.found, 0, "bitmap1 all clear -> not found");
    assert.equal(r.ret, 0, "slot search failure -> ret 0");
    assert.equal(r.slot, slot0, "not-found wraps to original slot");
  }
  /* ---- PLAY2 records ---- */
  const ok1 = evalF(alive());
  assert.equal(ok1.fire_74bba0b, 1);
  assert.equal(ok1.call_74bba0b_arg, 1 /* h_74bae0 */);
  assert.equal(ok1.fire_7eea90b, 1, "empty slot -> create");
  assert.equal(ok1.call_7eea90b_arg, ok1.slot);
  assert.equal(ok1.store_394_value, 0xfffffff6);
  assert.equal(ok1.fire_710fa0b, 1);
  assert.equal(ok1.call_710fa0b_arg1, 1);
  assert.equal(ok1.call_710fa0b_arg2, 0xabcdef12);
  {
    /* bitmap2 bit set on the START slot -> not found. */
    const t0b = 0x12345678 ^ (0x12345678 >>> 2);
    const u0b = (t0b ^ (t0b << 9)) >>> 0;
    const slot0b = ((u0b ^ (u0b >>> 15)) >>> 0) & 7;
    assert.equal(evalF(alive({ bm2: 1 << slot0b })).found, 0,
      "bitmap2 bit set -> not found");
  }
  /* ---- door branch: gate_80 + slot8 + 70d360 + path A/B ---- */
  const db = evalF(alive({ h_706940b_80: 2, slot_8: 3, h_70d360: 1 }));
  assert.equal(db.gate_80, 1);
  assert.equal(db.slot8_gate, 1);
  assert.equal(db.fire_70d360, 1);
  assert.equal(db.gate_70d360_4, 1);
  assert.equal(db.path_b, 0, "slot_8 3 not in {1,4,2} -> path A");
  assert.equal(db.fire_417870, 1);
  assert.equal(db.call_417870_arg, 0);
  assert.equal(db.fire_710480, 1);
  assert.equal(db.fire_710dd0, 1, "path A fires 710dd0");
  assert.equal(db.fire_70fb60, 1, "path A fires 70fb60");
  const pb = evalF(alive({ h_706940b_80: 2, slot_8: 4, h_70d360: 1 }));
  assert.equal(pb.path_b, 1, "slot_8 4 -> path B");
  assert.equal(pb.fire_710dd0, 0, "path B skips 710dd0");
  assert.equal(pb.fire_70fb60, 0, "path B skips 70fb60");
  assert.equal(evalF(alive({ h_706940b_80: 3 })).gate_80, 0);
  assert.equal(evalF(alive({ h_706940b_80: 2, slot_8: 8 })).slot8_gate, 0);
  assert.equal(evalF(alive({ h_706940b_80: 2, slot_8: 3, h_70d360: 4 }))
    .gate_70d360_4, 0, "70d360 == 4 skips door branch");
  /* ---- a1 gate + tail ---- */
  assert.equal(evalF(alive({ a1: 0 })).a1_gate, 1);
  assert.equal(evalF(alive({ a1: 0 })).tail_fire, 0);
  assert.equal(evalF(alive({ a1: 1 })).tail_fire, 1);
  assert.equal(evalF(alive({ a1: 0x100 })).tail_fire, 0,
    "a1 WIDE: low byte 0x00 -> tail NOT fired (byte test @0x7f7e34)");
  assert.equal(evalF(alive({ a1: 0x1ff })).tail_fire, 1,
    "a1 low byte 0xff -> tail fired");
  assert.equal(evalF(alive({ a1: 0, genrand_tail: 0x123 })).tail_loop_count,
    ((0x123 & 3) + 5), "tail count (genrand&3)+5");
  assert.equal(evalF(alive()).ret, 1, "survive -> ret 1");
  /* ---- randomized differential ---- */
  let lcg = 0x9e3779b9;
  const rnd = () => ((lcg = (Math.imul(lcg, 1664525) + 1013904223) >>> 0), lcg);
  const pick = (arr) => arr[Math.floor(rnd() / 2 ** 23) % arr.length];
  for (let k = 0; k < 150; k++) {
    const seed = pick([0, 0x12345678, 0xffffffff, 1, 0xdeadbeef]);
    const t0 = seed ^ (seed >>> 2);
    const u0 = (t0 ^ (t0 << 9)) >>> 0;
    const slot0 = ((u0 ^ (u0 >>> 15)) >>> 0) & 7;
    const occ = {};
    for (let i = 0; i < 8; i++) occ[`slot_occ${i}`] = pick([0, 1, 0xffffffff]);
    occ[`slot_occ${slot0}`] = 0;
    evalF({
      a1: pick([0, 1, 0x100, 0x1ff]),
      a2: pick([0, 1, 0x100, 0x1ff]),
      game_26584: pick([0, 1, 0xffffffff]),
      game_26630: pick([0, 1, 0xffffffff, 0x80000000]),
      game_26589: pick([0, 1, 0x100, 0x1ff]),
      game_18304: pick([0, 1, 0xffffffff]),
      game_18314: pick([0, 1, 0xffffffff]),
      h_740bc0_ret_8: pick([0, 1, 0xffffffff]),
      h_706940b_80: pick([0, 2, 3, 0xffffffff]),
      obj_1e3: pick([0, 1, 0x100, 0x1ff]),
      obj_8: pick([0, 2, 3, 0xffffffff]),
      h_74bae0: pick([0, 1, 4, 0xffffffff]),
      h_74e9b0: pick([0, 1, 0x100]),
      slot_seed: seed,
      bm1: pick([0, 1 << slot0, 0xffffffff]),
      bm2: pick([0, 1 << slot0, 0xffffffff]),
      ...occ,
      r74bba0b_f10_f8: pick([0, 0xabcdef12, 0xffffffff]),
      slot_8: pick([0, 1, 2, 3, 4, 8, 0xffffffff]),
      h_70d360: pick([0, 1, 4, 0xffffffff]),
      genrand_tail: pick([0, 1, 0x123, 0xffffffff]),
    });
  }
});

test("room v67a trigger-clear audio 7f7a40 mutation checks (helpers ABI 67)", () => {
  /* Each mutant must change behaviour AND a pinned assertion must catch
     it: the test itself FAILS on the mutated build. */
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const P = MEM + 0x9e00;
  const S = MEM + 0x9f00;
  const writeRetry = (content, label) => writeSourceRetry(content);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeRetry(toFile(bad), label);
    let threw = false;
    try {
      check();
    } catch {
      threw = true;
    }
    writeRetry(original, label);
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  const S2 = MEM + 0xa100;
  const writeGates = (src, view, tca) => {
    const f = [
      "a1", "a2", "game_26584", "room_type_8", "desc_f10_f10",
      "h_74ea50", "game_stage_0", "game_2654c", "h_706940_80",
      "obj_2c7", "obj_8", "game_26630", "game_26589", "game_26550",
      "game_c", "h_6f9400", "h_6f95a0", "game_18304", "game_182d0",
      "game_4", "room_728", "room_f10_f8", "r74bba0_f10_f8",
      "game_present",
    ];
    f.forEach((k, i) => view.setUint32(S2 + i * 4, src[k] >>> 0, true));
    tca(S2, P);
  };
  try {
    /* (1) abort_2c LOW-BYTE test: 0x1002c must NOT abort. */
    withMutant("v67a 2c gate low-byte",
      (s) => s.replace(
        "out->abort_2c = (a2_byte == 0u && src->game_26584 == 0x2cu) ? 1u : 0u;",
        "out->abort_2c = (a2_byte == 0u && (src->game_26584 & 0xffu) == 0x2cu) ? 1u : 0u;",
      ),
      () => {
        const { memory, tca7f7a40Gates } = loadExports();
        const view = new DataView(memory.buffer);
        writeGates({
          a1: 1, a2: 0, game_26584: 0x1002c, room_type_8: 1,
          desc_f10_f10: 0, h_74ea50: 0, game_stage_0: 6, game_2654c: 0,
          h_706940_80: 0, obj_2c7: 0, obj_8: 0, game_26630: 0,
          game_26589: 0, game_26550: 0, game_c: 0, h_6f9400: 0,
          h_6f95a0: 0, game_18304: 1, game_182d0: 1, game_4: 6,
          room_728: 0, room_f10_f8: 0, r74bba0_f10_f8: 0, game_present: 1,
        }, view, tca7f7a40Gates);
        assert.equal(view.getUint32(P + 4, true), 0,
          "cmp dword [Game+0x26584],0x2c FULL: 0x1002c != 0x2c");
      });
    /* (2) play flag UNSIGNED 0x26630 flipped to signed: 0xffffffff must
       still play (ja). */
    withMutant("v67a play 26630 signed",
      (s) => s.replace(
        "((src->game_26630 > 0u) || ((src->game_26589 & 0xffu) != 0u))",
        "(((int32_t)src->game_26630 > 0) || ((src->game_26589 & 0xffu) != 0u))",
      ),
      () => {
        const { memory, tca7f7a40Gates } = loadExports();
        const view = new DataView(memory.buffer);
        writeGates({
          a1: 1, a2: 0, game_26584: 0, room_type_8: 1, desc_f10_f10: 0,
          h_74ea50: 0, game_stage_0: 6, game_2654c: 0, h_706940_80: 0,
          obj_2c7: 0, obj_8: 2, game_26630: 0xffffffff, game_26589: 0,
          game_26550: 0, game_c: 0, h_6f9400: 0, h_6f95a0: 0,
          game_18304: 1, game_182d0: 1, game_4: 6, room_728: 0,
          room_f10_f8: 0, r74bba0_f10_f8: 0, game_present: 1,
        }, view, tca7f7a40Gates);
        assert.equal(view.getUint32(P + 28, true), 1,
          "ja UNSIGNED: 0xffffffff > 0u -> b03 -> play 1");
      });
    /* (3) actual play-flag low-byte on 0x2c7: 0x100 must NOT count. */
    withMutant("v67a obj_2c7 full-dword",
      (s) => s.replace(
        "((src->obj_2c7 & 0xffu) != 0u) ||",
        "(src->obj_2c7 != 0u) ||",
      ),
      () => {
        const { memory, tca7f7a40Gates } = loadExports();
        const view = new DataView(memory.buffer);
        writeGates({
          a1: 1, a2: 0, game_26584: 0, room_type_8: 1, desc_f10_f10: 0,
          h_74ea50: 0, game_stage_0: 6, game_2654c: 0, h_706940_80: 0,
          obj_2c7: 0x100, obj_8: 0, game_26630: 0, game_26589: 0,
          game_26550: 0, game_c: 0, h_6f9400: 0, h_6f95a0: 0,
          game_18304: 1, game_182d0: 1, game_4: 6, room_728: 0,
          room_f10_f8: 0, r74bba0_f10_f8: 0, game_present: 1,
        }, view, tca7f7a40Gates);
        assert.equal(view.getUint32(P + 28, true), 0,
          "cmp byte [obj+0x2c7],0: 0x100 low byte 0 -> no play");
      });
    /* (4) 0x740bc0 post-check folds the pre-call arg (defect-class-1). */
    withMutant("v67a 740bc0 folds pre arg",
      (s) => s.replace(
        "out->abort_740bc0 =\n      (fire_740bc0 != 0u && src->h_740bc0_ret_8 != src->game_18314) ? 1u : 0u;",
        "out->abort_740bc0 =\n      (fire_740bc0 != 0u && src->game_18304 != src->game_18314) ? 1u : 0u;",
      ),
      () => {
        const { memory, tca7f7a40Fail } = loadExports();
        const view = new DataView(memory.buffer);
        const PF = MEM + 0xa300;
        const SF = MEM + 0xa400;
        const f = [
          "a1", "a2", "game_26584", "game_26630", "game_26589",
          "game_18304", "game_18314", "h_740bc0_ret_8", "h_706940b_80",
          "obj_1e3", "obj_8", "h_74bae0", "h_74e9b0", "slot_seed",
          "bm1", "bm2", "slot_occ0", "slot_occ1", "slot_occ2",
          "slot_occ3", "slot_occ4", "slot_occ5", "slot_occ6",
          "slot_occ7", "r74bba0b_f10_f8", "slot_8", "h_70d360",
          "genrand_tail",
        ];
        const src = {
          a1: 1, a2: 0, game_26584: 0, game_26630: 0, game_26589: 0,
          game_18304: 0x55, game_18314: 0x11, h_740bc0_ret_8: 0x11,
          h_706940b_80: 2, obj_1e3: 1, obj_8: 2, h_74bae0: 1,
          h_74e9b0: 0, slot_seed: 0x12345678, bm1: 1, bm2: 0,
          slot_occ0: 0, slot_occ1: 1, slot_occ2: 1, slot_occ3: 1,
          slot_occ4: 1, slot_occ5: 1, slot_occ6: 1, slot_occ7: 1,
          r74bba0b_f10_f8: 0, slot_8: 3, h_70d360: 1, genrand_tail: 0,
        };
        f.forEach((k, i) => view.setUint32(SF + i * 4, src[k] >>> 0, true));
        tca7f7a40Fail(SF, PF);
        assert.equal(view.getUint32(PF + 8, true), 0,
          "POST-call snapshot [r740bc0+8]=0x11 == 18314 -> pass");
      });
    /* (5) slot-hash shift order (2/9/15 misplaced): 0x12345678 differs. */
    withMutant("v67a hash shift order",
      (s) => s.replace(
        "const uint32_t u0 = t0 ^ (t0 << 9u);",
        "const uint32_t u0 = t0 ^ (t0 << 15u);",
      ),
      () => {
        const { memory, tca7f7a40Fail } = loadExports();
        const view = new DataView(memory.buffer);
        const PF = MEM + 0xa500;
        const SF = MEM + 0xa600;
        const f = [
          "a1", "a2", "game_26584", "game_26630", "game_26589",
          "game_18304", "game_18314", "h_740bc0_ret_8", "h_706940b_80",
          "obj_1e3", "obj_8", "h_74bae0", "h_74e9b0", "slot_seed",
          "bm1", "bm2", "slot_occ0", "slot_occ1", "slot_occ2",
          "slot_occ3", "slot_occ4", "slot_occ5", "slot_occ6", "slot_occ7",
          "r74bba0b_f10_f8", "slot_8", "h_70d360", "genrand_tail",
        ];
        const src = {
          a1: 1, a2: 0, game_26584: 0, game_26630: 0, game_26589: 0,
          game_18304: 0, game_18314: 0, h_740bc0_ret_8: 0,
          h_706940b_80: 2, obj_1e3: 1, obj_8: 2, h_74bae0: 1,
          h_74e9b0: 0, slot_seed: 0x12345678, bm1: 0, bm2: 0,
          slot_occ0: 0, slot_occ1: 1, slot_occ2: 1, slot_occ3: 1,
          slot_occ4: 1, slot_occ5: 1, slot_occ6: 1, slot_occ7: 1,
          r74bba0b_f10_f8: 0, slot_8: 3, h_70d360: 1, genrand_tail: 0,
        };
        f.forEach((k, i) => view.setUint32(SF + i * 4, src[k] >>> 0, true));
        tca7f7a40Fail(SF, PF);
        const t0p = 0x12345678 ^ (0x12345678 >>> 2);
        const want = (((t0p ^ (t0p << 9)) >>> 0) ^ (((t0p ^ (t0p << 9)) >>> 0) >>> 15)) >>> 0;
        assert.equal(view.getUint32(PF + 48, true), want,
          "hash = u ^ (u>>15) with shift 9 (not 15)");
      });
  } finally {
    writeRetry(original, "v67a final restore");
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});

/* ---- ABI v68: FUN_007f8190 spawn/audio-relay decision laws ---- */

/* v68 struct layouts (pack 1). */
const V68_DIVMOD_OUT_OFF = { rem: 0, quot: 4 };
const V68_GATES_OUT_OFF = {
  fatal_bounds: 0, skip_range: 4, skip_collision: 8, alloc_needed: 12,
  grid_host_va: 16, alloc_host_va: 20, alloc_arg: 24, ctor_host_va: 28,
  init_host_va: 32, vtable: 36, subtype: 40, slot_off: 44,
  slot_stride: 48, obj_f8_val: 52, obj_f18_val: 56,
};
const V68_FRAME_OUT_OFF = {
  a0_type: 0, a1_variant: 4, a2_pos_ptr: 8, a3_posvec: 12,
  a4_zero: 16, a5_zero: 20, a6_rng: 24, a7_zero: 28,
  arity: 32, host_va: 36,
};

function v68ReadDivmod(view, base) {
  return { rem: view.getInt32(base, true), quot: view.getInt32(base + 4, true) };
}
function v68ReadGates(view, base) {
  const out = {};
  for (const [k, off] of Object.entries(V68_GATES_OUT_OFF)) {
    out[k] = view.getUint32(base + off, true) >>> 0;
  }
  return out;
}
function v68ReadFrame(view, base) {
  const out = {};
  for (const [k, off] of Object.entries(V68_FRAME_OUT_OFF)) {
    out[k] = view.getUint32(base + off, true) >>> 0;
  }
  return out;
}

test("room v68: FUN_007f8190 head gate + slot law + path (PE 0x7f8190..0x7f8240)", () => {
  assert.equal(ROOM_PURE_ABI_VERSION, 88);
  assert.equal(ROOM_8190_VA, 0x007f8190);
  assert.equal(ROOM_8190_RET_VA, 0x007f83a3);
  assert.equal(ROOM_8190_NEXT_VA, 0x007f83b0);
  assert.equal(ROOM_8190_SEH_HANDLER_VA, 0x00b012c7);
  assert.equal(ROOM_8190_OWNER_HOST_VA, 0x009be080);
  assert.equal(ROOM_8190_OWNER_COLLECTIBLE, 0x25a);
  assert.equal(ROOM_8190_OWNER_RNG_OFF, 0x1baa8);
  assert.equal(ROOM_8190_GENRAND_VA, 0x006eef60);
  assert.equal(ROOM_8190_CREATE_HOST_VA, 0x006fe410);
  assert.equal(ROOM_8190_CREATE_TYPE, 0x3e8);
  assert.equal(ROOM_8190_CREATE_VARIANT, 0x9c);
  assert.equal(ROOM_8190_CREATE_POS_VEC_VA, 0x00c7b640);
  assert.equal(ROOM_8190_CREATE_ARITY, 8);

  const {
    memory, room8190Va, room8190RetVa, room8190NextVa,
    room8190HeadRet0: wHead, room8190SlotLaw: wSlot, room8190SpawnPath: wPath,
  } = loadExports();
  assert.equal(room8190Va() >>> 0, 0x007f8190, "wasm head VA");
  assert.equal(room8190RetVa() >>> 0, 0x007f83a3, "wasm ret VA");
  assert.equal(room8190NextVa() >>> 0, 0x007f83b0, "wasm next VA");
  const view = new DataView(memory.buffer);

  /* HEAD GATE (LOW-BYTE arg). */
  const headJL = (arg, this8, owner, this4_0) => {
    const want = room8190HeadRet0(arg, this8, owner, this4_0);
    const got = wHead(arg >>> 0, this8 >>> 0, owner >>> 0, this4_0 | 0) >>> 0;
    assert.equal(got, want, `head(${arg},${this8},${owner},${this4_0})`);
    return got;
  };
  /* arg low byte != 0 -> proceed (ret0 = 0) regardless of the rest. */
  assert.equal(headJL(0x1ff, 0, 0, 0), 0, "arg byte 0xff -> proceed");
  assert.equal(headJL(0xffffffff, 2, 0, 0), 0, "arg byte 0xff -> proceed");
  /* WIDE byte gate: 0x100 low byte 0 -> ret0 law runs. */
  assert.equal(headJL(0x100, 3, 0, 0), 1, "0x100 byte 0 + this8!=2 -> ret0");
  assert.equal(headJL(0x100, 2, 0, 0), 1, "0x100 byte 0 + owner 0 + this4 0 -> ret0");
  assert.equal(headJL(0x100, 2, 1, 0), 0, "owner!=0 -> proceed");
  assert.equal(headJL(0x100, 2, 0, -1), 0, "this4_0<0 (jl) -> proceed");
  assert.equal(headJL(0x100, 2, 0, 0x7fffffff), 1, "this4_0>=0 -> ret0");
  assert.equal(headJL(0, 2, 0, 0), 1, "arg 0 same as byte 0");
  assert.equal(headJL(0xff, 3, 0, 0), 0, "arg byte 0xff -> proceed (this8 ignored)");

  /* SLOT LAW (all SIGNED; raw48 FULL dword ==6). */
  const slotJL = (c, f10, raw48) => {
    const want = room8190SlotLaw(c, f10, raw48);
    const got = wSlot(c | 0, f10 | 0, raw48 >>> 0) | 0;
    assert.equal(got, want, `slot(${c},${f10},${raw48})`);
    return got;
  };
  assert.equal(slotJL(0xfffffff6, 2, 0), -1, "c -10 signed: no c+0xa");
  assert.equal(slotJL(11, 1, 0), -1, "f10 1: no");
  assert.equal(slotJL(11, 2, 0), 21, "c 11 f10 2 raw48!=6 -> c+0xa");
  assert.equal(slotJL(11, 2, 6), -1, "raw48==6 && c<=0x14 -> -1 OVERWRITE");
  assert.equal(slotJL(0x14, 3, 6), -1, "c==0x14 (jle) -> -1");
  assert.equal(slotJL(0x15, 3, 6), 62, "c 0x15 f10 3 raw48 6 -> 2*(0x1f)");
  assert.equal(slotJL(0x15, 3, 5), 31, "raw48!=6 -> stays 0x1f");
  assert.equal(slotJL(0x15, 2, 6), -1, "f10 2 (jle) -> -1");
  assert.equal(slotJL(0x7ffffff7, 3, 6), 2,
    "c+0xa wraps to 0x80000001; *2 wraps to 2 (int32)");
  assert.equal(slotJL(0xfffffff6, 2, 6), -1, "c -10, raw48 6 -> -1");

  /* PATH GATE (SIGNED). */
  const pathJL = (v) => {
    const want = room8190SpawnPath(v);
    const got = wPath(v | 0) >>> 0;
    assert.equal(got, want, `path(${v})`);
    return got;
  };
  assert.equal(pathJL(-1), 1, "-1 spawn");
  assert.equal(pathJL(0xffffffff), 1, "0xffffffff spawn (SIGNED)");
  assert.equal(pathJL(0), 0, "0 slot-path");
  assert.equal(pathJL(0x7fffffff), 0, "max slot-path");
});

test("room v68: FUN_007f8190 tile divmod + pos f32 + create frame (PE 0x7f8240..0x7f82a6)", () => {
  const { memory, room8190TileDivmod: wDiv, room8190TilePosX: wX,
          room8190TilePosY: wY, room8190CreateFrame: wFrame } = loadExports();
  const view = new DataView(memory.buffer);
  const DO = MEM + 0xa800, FO = MEM + 0xa810;

  /* SIGNED idiv: slot/width -> quot, rem (cdq). */
  const divJL = (slot, width) => {
    const want = room8190TileDivmod(slot, width);
    wDiv(slot | 0, width | 0, DO);
    const got = v68ReadDivmod(view, DO);
    assert.equal(got.quot, want.quot, `divmod(${slot},${width}).quot`);
    assert.equal(got.rem, want.rem, `divmod(${slot},${width}).rem`);
    return got;
  };
  {
    const g = divJL(31, 13);
    assert.equal(g.quot, 2, "31/13 = 2");
    assert.equal(g.rem, 5, "31%13 = 5");
  }
  {
    /* WIDE SIGNED: slot -1 (0xffffffff) -> quot 0, rem -1 (NOT u32 rem 6). */
    const g = divJL(-1, 13);
    assert.equal(g.quot, 0, "-1/13 = 0");
    assert.equal(g.rem, -1, "-1%13 = -1");
  }
  {
    const g = divJL(-31, 13);
    assert.equal(g.quot, -2, "-31/13 = -2");
    assert.equal(g.rem, -5, "-31%13 = -5");
  }
  {
    const g = divJL(0x15, 7);
    assert.equal(g.quot, 3, "21/7 = 3");
    assert.equal(g.rem, 0, "21%7 = 0");
  }

  /* Tile pos f32: the export RETURNS the f32 (by value, like the PE's
     xmm0); the model oracle is Math.fround'd — compare exactly. */
  const xJL = (rem) => {
    const want = room8190TilePosX(rem);
    const got = wX(rem | 0);
    assert.equal(Math.fround(got), Math.fround(want), `posX(${rem}) f32`);
    return want;
  };
  const yJL = (quot) => {
    const want = room8190TilePosY(quot);
    const got = wY(quot | 0);
    assert.equal(Math.fround(got), Math.fround(want), `posY(${quot}) f32`);
    return want;
  };
  assert.equal(xJL(0), 40, "x(0) = 0*40+40");
  assert.equal(xJL(-1), 0, "x(-1) = -40+40 = 0");
  assert.equal(xJL(5), 240, "x(5) = 240");
  assert.equal(yJL(0), 120, "y(0) = 120");
  assert.equal(yJL(1), 160, "y(1) = 40+120");
  assert.equal(yJL(2), 200, "y(2) = 80+120");
  /* Large rem: f32 rounding, rem = 0x100 -> 40*256+40 = 10280. */
  assert.equal(xJL(0x100), 10280, "x(0x100) = 10280");
  assert.equal(ROOM_8190_POS_X_BITS, 0x42200000, "40.0f bits");
  assert.equal(ROOM_8190_POS_Y_BITS, 0x42f00000, "120.0f bits");

  /* Create frame: constants + a6 = rng (8 args + ecx=Game). */
  const frameJL = (index, rng) => {
    const want = room8190CreateFrame(index, rng);
    wFrame(index >>> 0, rng >>> 0, FO);
    const got = v68ReadFrame(view, FO);
    for (const k of Object.keys(V68_FRAME_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `frame.${k}(${index},${rng})`);
    }
    return got;
  };
  const fr = frameJL(0, 0x12345678);
  assert.equal(fr.a0_type, 0x3e8, "arg0 type");
  assert.equal(fr.a1_variant, 0x9c, "arg1 variant");
  assert.equal(fr.a3_posvec, 0x00c7b640, "arg3 posvec global");
  assert.equal(fr.a6_rng, 0x12345678, "arg6 rng passthrough");
  assert.equal(fr.a4_zero, 0, "arg4 zero");
  assert.equal(fr.a5_zero, 0, "arg5 zero");
  assert.equal(fr.a7_zero, 0, "arg7 zero");
  assert.equal(fr.arity, 8, "8 pushed dwords");
  assert.equal(fr.host_va, 0x006fe410, "create host");
  frameJL(6, 0xdeadbeef);
  frameJL(7, 0);
});

test("room v68: FUN_007f8190 slot-path gates (PE 0x7f82f4..0x7f833e)", () => {
  const { memory, room8190SlotGates: wGates } = loadExports();
  const view = new DataView(memory.buffer);
  const GO = MEM + 0xa900;
  const gatesJL = (slot, gridcoll) => {
    const want = room8190SlotGates(slot, gridcoll);
    wGates(slot | 0, gridcoll | 0, GO);
    const got = v68ReadGates(view, GO);
    for (const k of Object.keys(V68_GATES_OUT_OFF)) {
      assert.equal(got[k], want[k] >>> 0, `gates(${slot},${gridcoll}).${k}`);
    }
    return got;
  };
  assert.equal(ROOM_8190_SLOT_FATAL_MAX, 0x1c0, "fatal max");
  assert.equal(ROOM_8190_SLOT_SKIP_MAX, 0x1bf, "skip max");
  assert.equal(ROOM_8190_GRID_HOST_VA, 0x007f0800, "gridcoll");
  assert.equal(ROOM_8190_ALLOC_HOST_VA, 0x00a0f4c0, "alloc");
  assert.equal(ROOM_8190_ALLOC_ARG, 0x154, "alloc arg");
  assert.equal(ROOM_8190_VTABLE, 0x00b7da10, "vtable");
  assert.equal(ROOM_8190_SUBTYPE, 0x12, "subtype");
  assert.equal(ROOM_8190_SLOT_ARR_OFF, 0x24, "slot arr off");
  assert.equal(ROOM_8190_SLOT_STRIDE, 4, "slot stride");
  assert.equal(ROOM_8190_OBJ_F8_VAL, 2, "[obj+8]");
  assert.equal(ROOM_8190_OBJ_F18_VAL, 0, "[obj+0x18]");
  assert.equal(ROOM_8190_SFX_ID, 0x394, "sound id");
  assert.equal(ROOM_8190_FATAL_ARG0, 0x00b6c138, "fatal arg0");

  {
    /* slot -1 (0xffffffff): (int)<0 -> fatal; (u32)>0x1bf -> range skip. */
    const g = gatesJL(-1, 0);
    assert.equal(g.fatal_bounds, 1, "-1 fatal bounds");
    assert.equal(g.skip_range, 1, "-1 range skip (unsigned ja)");
    assert.equal(g.alloc_needed, 0, "-1 no alloc");
  }
  {
    const g = gatesJL(0x1bf, 0);
    assert.equal(g.fatal_bounds, 0, "0x1bf ok");
    assert.equal(g.skip_range, 0, "0x1bf not > 0x1bf");
    assert.equal(g.alloc_needed, 1, "0x1bf alloc");
  }
  {
    const g = gatesJL(0x1c0, 0);
    assert.equal(g.fatal_bounds, 1, "0x1c0 >= 0x1c0 fatal");
    assert.equal(g.skip_range, 1, "0x1c0 range skip");
    assert.equal(g.alloc_needed, 0, "0x1c0 no alloc");
  }
  {
    /* collision: jg -> skip iff gridcoll > 0 (SIGNED). */
    const g = gatesJL(5, 1);
    assert.equal(g.skip_collision, 1, "gridcoll 1 skip");
    assert.equal(g.alloc_needed, 0, "no alloc on collision");
    const g0 = gatesJL(5, 0);
    assert.equal(g0.skip_collision, 0, "gridcoll 0 alloc path");
    assert.equal(g0.alloc_needed, 1, "alloc on 0");
    const gn = gatesJL(5, -1);
    assert.equal(gn.skip_collision, 0, "gridcoll -1 no skip (jg)");
  }
});

test("room v68: FUN_007f8190 mutation discrimination", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, label + ": mutant did not apply");
    writeSourceRetry(crlfFile ? bad.replace(/\n/g, "\r\n") : bad);
    let threw = false;
    try { check(); } catch { threw = true; }
    writeSourceRetry(original);
    assert.ok(threw, label + ": mutant survived every assertion");
  };
  const eq = (a, b, m) => { try { assert.equal(a, b, m); } catch { throw new Error(m); } };

  try {
    /* (1) HEAD ARG LOW-BYTE MASK DROPPED: 0x100 byte 0 must take the
        ret0 path; the full-dword test sees 0x100 != 0 -> proceed. */
    withMutant("8190 head arg low-byte",
      (s) => s.replace(
        "const uint32_t arg_byte = arg & 0xffu;",
        "const uint32_t arg_byte = arg; /* low-byte mask dropped */"),
      () => {
        const { room8190HeadRet0 } = loadExports();
        eq(room8190HeadRet0(0x100, 2, 0, 0) >>> 0, 1,
          "0x100 low byte 0 + owner 0 + this4 0 -> ret0");
      });
    /* (2) SLOT LAW SIGNED->UNSIGNED: c 0xfffffff6 (-10) must NOT be
        > 0xa (signed); unsigned mutant accepts -> slot 0. */
    withMutant("8190 slot law unsigned",
      (s) => s.replace(
        "int32_t slot = (c > 0xa && f10 > 1) ? c + 0xa : -1;",
        "int32_t slot =\n      (static_cast<uint32_t>(c) > 0xau && f10 > 1) ? c + 0xa : -1;"),
      () => {
        const { room8190SlotLaw } = loadExports();
        eq(room8190SlotLaw(0xfffffff6, 2, 0) | 0, -1,
          "c -10 (SIGNED) -> slot -1, not 0");
      });
    /* (3) RAW48 OVERWRITE DROPPED: raw48==6 && c<=0x14 -> or edi,-1
        (mutant keeps the c+0xa value). */
    withMutant("8190 raw48 overwrite dropped",
      (s) => s.replace(
        "} else {\n      /* 0x7f8238 or edi,0xffffffff — OVERWRITES the c+0xa value. */\n      slot = -1;\n    }",
        "} else {\n      /* mutant: no -1 overwrite */\n    }"),
      () => {
        const { room8190SlotLaw } = loadExports();
        eq(room8190SlotLaw(0xf, 3, 6) | 0, -1,
          "raw48 6 + c 15 (<=0x14) -> -1, not 0x13");
      });
    /* (4) PATH GATE SIGNED->UNSIGNED: 0xffffffff must be spawn-path. */
    withMutant("8190 path gate unsigned",
      (s) => s.replace(
        "return (this4_0 < 0) ? 1u : 0u;",
        "return (static_cast<uint32_t>(this4_0) < 0x80000000u) ? 1u : 0u;"),
      () => {
        const { room8190SpawnPath } = loadExports();
        eq(room8190SpawnPath(0xffffffff) >>> 0, 1,
          "0xffffffff (int -1) -> spawn-path 1");
      });
    /* (5) DIVMOD UNSIGNED: slot -1 / 13 -> signed rem -1, not 6. */
    withMutant("8190 divmod unsigned",
      (s) => s.replace(
        "out->quot = slot / width;\n  out->rem = slot % width;",
        "out->quot = static_cast<int32_t>(\n      static_cast<uint32_t>(slot) / static_cast<uint32_t>(width));\n  out->rem = static_cast<int32_t>(\n      static_cast<uint32_t>(slot) % static_cast<uint32_t>(width));"),
      () => {
        const { memory, room8190TileDivmod } = loadExports();
        const view = new DataView(memory.buffer);
        room8190TileDivmod(-1, 13, MEM + 0xaa00);
        eq(view.getInt32(MEM + 0xaa04, true), 0, "signed -1/13 quot 0");
        eq(view.getInt32(MEM + 0xaa00, true), -1, "signed -1%13 rem -1");
      });
    /* (6) POS-Y ADDEND: y = quot*40+120, NOT quot*40+40 (0xbaaa00 vs
        0xbaa904). */
    withMutant("8190 pos y addend 40",
      (s) => s.replace(
        "const float base = __builtin_bit_cast(float, 0x42f00000u); /* 120.0f */\n  return static_cast<float>(static_cast<float>(quot) * scale) + base;",
        "return static_cast<float>(static_cast<float>(quot) * scale) + scale;"),
      () => {
        const { room8190TilePosY } = loadExports();
        eq(room8190TilePosY(1), 160, "y(1) = 40+120 = 160 f32");
        eq(room8190TilePosY(1), 160, "y(1) f32 = 160");
      });
    /* (7) COLLISION GATE jg->jge: gridcoll 0 must NOT skip (jg), the
        jge mutant skips. */
    withMutant("8190 collision jge",
      (s) => s.replace(
        "const uint32_t skip_collision = (gridcoll > 0) ? 1u : 0u;",
        "const uint32_t skip_collision = (gridcoll >= 0) ? 1u : 0u;"),
      () => {
        const { memory, room8190SlotGates } = loadExports();
        const view = new DataView(memory.buffer);
        room8190SlotGates(5, 0, MEM + 0xab00);
        eq(view.getUint32(MEM + 0xab08, true), 0,
          "gridcoll 0: jg NOT taken -> alloc path");
        eq(view.getUint32(MEM + 0xab0c, true), 1, "alloc_needed 1");
      });
  } finally {
    writeSourceRetry(original);
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  assert.equal(loadExports().abi(), ROOM_PURE_ABI_VERSION, "fresh green build after restore");
});

