  assert.equal(ROOM_VALUE_92B0_GAME_1839C_OFF, 0x1839c);
  assert.equal(ROOM_VALUE_92B0_GAME_18334_OFF, 0x18334);
  assert.equal(ROOM_VALUE_92B0_GAME_26548_OFF, 0x26548);
  assert.equal(ROOM_VALUE_92B0_GAME_26554_OFF, 0x26554);
  assert.equal(ROOM_VALUE_92B0_GAME_2663C_OFF, 0x2663c);
  assert.equal(ROOM_VALUE_92B0_GAME_269C8_OFF, 0x269c8);
  assert.equal(ROOM_VALUE_92B0_FLAGS_BIT_1, 1);
  assert.equal(ROOM_VALUE_92B0_FLAGS_BIT_4, 4);
  assert.equal(ROOM_VALUE_92B0_FLAGS_BIT_40, 0x40);
  assert.equal(ROOM_VALUE_92B0_FLAGS26548_BIT, 0x20000000);
  assert.equal(ROOM_VALUE_92B0_MODE_2663C, 0x11);
  assert.equal(ROOM_VALUE_92B0_MODE_2, 2);
